import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Problem, UserRole, Solution, Review, SiteConfig, Payment } from '../types';
import { auth, db } from '../services/firebase';
import { supabase } from '../services/supabase';

interface AppContextType {
  user: User | null;
  loading: boolean;
  allUsers: User[];
  problems: Problem[];
  payments: Payment[];
  siteConfig: SiteConfig;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string, role: UserRole, name: string, extraInfo: string) => Promise<void>;
  logout: () => void;
  resetPassword: (email: string) => Promise<void>;
  addProblem: (title: string, description: string, bounty: string, tags: string[]) => void;
  editProblem: (problemId: string, title: string, description: string, bounty: string, tags: string[]) => Promise<void>;
  manualCloseProblem: (problemId: string) => Promise<void>;
  addSolution: (problemId: string, content: string, file?: File) => Promise<void>;
  acceptSolution: (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, paymentMethod: string) => Promise<void>;
  updateUserProfile: (name: string, bio: string, skills: string[], file?: File, websiteUrl?: string) => Promise<void>;
  adminBanUser: (userId: string, currentStatus: boolean) => Promise<void>;
  adminDeleteUser: (userId: string) => Promise<void>;
  adminDeleteProblem: (problemId: string) => Promise<void>;
  updateSiteConfig: (newConfig: Partial<SiteConfig>) => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [problems, setProblems] = useState<Problem[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [siteConfig, setSiteConfig] = useState<SiteConfig>({ baseFontSize: 16, enableDarkMode: true });

  const solutionUnsubscribes = useRef<Record<string, () => void>>({});

  useEffect(() => {
    const docRef = db.collection("settings").doc("global");
    const unsub = docRef.onSnapshot((docSnap) => {
        if (docSnap.exists) {
            setSiteConfig(docSnap.data() as SiteConfig);
        }
    });
    return () => unsub();
  }, []);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (firebaseUser) => {
      if (firebaseUser && firebaseUser.emailVerified) {
        try {
          const docRef = db.collection("users").doc(firebaseUser.uid);
          const docSnap = await docRef.get();
          if (docSnap.exists) {
            const userData = { id: firebaseUser.uid, ...docSnap.data() } as User;
            if (!userData.isBanned) setUser(userData);
            else await auth.signOut();
          }
        } catch (error) { setUser(null); }
      } else { setUser(null); }
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const unsub = db.collection("users").onSnapshot((snapshot) => {
      setAllUsers(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as User)));
    });
    return () => unsub();
  }, [user?.id]);

  useEffect(() => {
    const unsub = db.collection("problems").orderBy("createdAt", "desc").onSnapshot((snapshot) => {
      const problemsData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data(), solutions: [] })) as Problem[];
      setProblems(problemsData);

      problemsData.forEach(p => {
        if (!solutionUnsubscribes.current[p.id]) {
          solutionUnsubscribes.current[p.id] = db.collection("problems").doc(p.id).collection("solutions").onSnapshot(s => {
            setProblems(current => current.map(cp => cp.id === p.id ? { ...cp, solutions: s.docs.map(sd => ({ id: sd.id, ...sd.data() } as Solution)) } : cp));
          });
        }
      });
    });
    return () => unsub();
  }, [user?.id]);

  useEffect(() => {
    if (!user) { setPayments([]); return; }
    const q = db.collection("payments").orderBy("timestamp", "desc");
    const unsub = q.onSnapshot((snap) => {
      const allPayments = snap.docs.map(d => ({ id: d.id, ...d.data() } as Payment));
      if (user.role === UserRole.ADMIN) setPayments(allPayments);
      else setPayments(allPayments.filter(p => p.fromId === user.id || p.toId === user.id));
    });
    return () => unsub();
  }, [user?.id]);

  const login = async (email: string, password: string) => {
    await auth.signInWithEmailAndPassword(email, password);
  };

  const register = async (email: string, password: string, role: UserRole, name: string, extraInfo: string) => {
    const userCredential = await auth.createUserWithEmailAndPassword(email, password);
    const uid = userCredential.user!.uid;
    const newUser = { id: uid, email, name, role, university: role === UserRole.STUDENT ? extraInfo : null, companyName: role === UserRole.COMPANY ? extraInfo : null, rating: role === UserRole.STUDENT ? 0 : null, solvedCount: 0, reviews: [], lastSeen: new Date().toISOString(), bio: '', profilePicUrl: '', skills: [] };
    await db.collection("users").doc(uid).set(newUser);
    await userCredential.user!.sendEmailVerification();
    await auth.signOut();
  };

  const logout = () => auth.signOut();
  const resetPassword = (email: string) => auth.sendPasswordResetEmail(email);

  const addProblem = async (title: string, description: string, bounty: string, tags: string[]) => {
    if (!user || user.role !== UserRole.COMPANY) return;
    await db.collection("problems").add({ companyId: user.id, companyName: user.companyName, title, description, bounty, status: 'OPEN', createdAt: new Date().toISOString(), tags });
  };

  const editProblem = async (id: string, title: string, description: string, bounty: string, tags: string[]) => {
    await db.collection("problems").doc(id).update({ title, description, bounty, tags });
  };

  const manualCloseProblem = async (id: string) => {
    await db.collection("problems").doc(id).update({ status: 'CLOSED' });
  };

  const addSolution = async (problemId: string, content: string, file?: File) => {
    if (!user) return;
    let attachmentUrl = null, attachmentName = null;
    if (file) {
      const path = `${problemId}/${user.id}/${Date.now()}_${file.name}`;
      await supabase.storage.from('solutions').upload(path, file);
      attachmentUrl = supabase.storage.from('solutions').getPublicUrl(path).data.publicUrl;
      attachmentName = file.name;
    }
    await db.collection("problems").doc(problemId).collection("solutions").add({ problemId, studentId: user.id, studentName: user.name, content, submittedAt: new Date().toISOString(), isAccepted: false, attachmentUrl, attachmentName });
  };

  const acceptSolution = async (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, paymentMethod: string) => {
    if (!user) return;
    const prob = problems.find(p => p.id === problemId);
    const student = allUsers.find(u => u.id === studentId);
    if (!prob || !student) return;

    await db.runTransaction(async (transaction) => {
      const probRef = db.collection("problems").doc(problemId);
      const solRef = probRef.collection("solutions").doc(solutionId);
      const studentRef = db.collection("users").doc(studentId);
      const payRef = db.collection("payments").doc();

      transaction.update(solRef, { isAccepted: true, rating, feedback });
      transaction.update(probRef, { status: 'CLOSED' });

      const newReview = { id: solutionId, problemTitle: prob.title, rating, feedback, createdAt: new Date().toISOString(), companyName: user.companyName };
      const totalScore = ((student.rating || 0) * (student.reviews?.length || 0)) + rating;
      const newRating = Number((totalScore / ((student.reviews?.length || 0) + 1)).toFixed(1));

      transaction.update(studentRef, { 
        solvedCount: (student.solvedCount || 0) + 1, 
        rating: newRating, 
        reviews: [...(student.reviews || []), newReview] 
      });

      transaction.set(payRef, {
        problemId,
        problemTitle: prob.title,
        amount: prob.bounty,
        status: 'COMPLETED',
        fromId: user.id,
        fromName: user.companyName,
        toId: studentId,
        toName: student.name,
        timestamp: new Date().toISOString(),
        method: paymentMethod
      });
    });
  };

  const updateUserProfile = async (name: string, bio: string, skills: string[], file?: File, websiteUrl?: string) => {
    if (!user) return;
    await db.collection("users").doc(user.id).update({ name, bio, skills, websiteUrl });
    setUser(prev => prev ? { ...prev, name, bio, skills, websiteUrl } : null);
  };

  const adminBanUser = async (id: string, status: boolean) => {
    await db.collection("users").doc(id).update({ isBanned: !status });
  };
  const adminDeleteUser = async (id: string) => { await db.collection("users").doc(id).delete(); };
  const adminDeleteProblem = async (id: string) => { await db.collection("problems").doc(id).delete(); };
  const updateSiteConfig = async (c: Partial<SiteConfig>) => { await db.collection("settings").doc("global").set(c, { merge: true }); };

  return (
    <AppContext.Provider value={{ user, loading, allUsers, problems, payments, siteConfig, login, register, logout, resetPassword, addProblem, addSolution, acceptSolution, editProblem, manualCloseProblem, updateUserProfile, adminBanUser, adminDeleteUser, adminDeleteProblem, updateSiteConfig }}>
      {children}
    </AppContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useStore must be used within AppProvider");
  return context;
};

import React, { useState, useEffect } from 'react';
import { AppProvider, useStore } from './context/Store';
import { UserRole } from './types';
import { Loader2 } from 'lucide-react';

import Navbar from './components/Navbar';
import ScrollToTopButton from './components/ScrollToTopButton';

import LandingPage from './pages/LandingPage';
import AuthPage from './pages/AuthPage';
import AdminPortal from './pages/AdminPortal';
import StudentPortal from './pages/StudentPortal';
import CompanyPortal from './pages/CompanyPortal';
import LegalPage from './pages/LegalPage';
import ContactPage from './pages/ContactPage';
import Leaderboard from './pages/Leaderboard';
import PaymentHistory from './pages/PaymentHistory';

type ViewState = 'HOME' | 'LEADERBOARD' | 'PRIVACY' | 'TERMS' | 'CONTACT' | 'AUTH' | 'DASHBOARD' | 'PAYMENT_HISTORY';

const FixMyProblemApp: React.FC = () => {
  const { user, loading, siteConfig } = useStore();
  const [view, setView] = useState<ViewState>('HOME');
  const [authRole, setAuthRole] = useState<UserRole>(UserRole.STUDENT);

  useEffect(() => {
    if (user && view === 'AUTH') setView('DASHBOARD');
  }, [user]);

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
    </div>
  );

  let currentContent;
  if (view === 'HOME' && !user) currentContent = <LandingPage onLoginClick={(role) => { setAuthRole(role); setView('AUTH'); }} onViewChange={setView} />;
  else if (view === 'LEADERBOARD') currentContent = <Leaderboard />;
  else if (view === 'PRIVACY' || view === 'TERMS') currentContent = <LegalPage type={view} />;
  else if (view === 'CONTACT') currentContent = <ContactPage />;
  else if (view === 'PAYMENT_HISTORY') currentContent = <PaymentHistory />;
  else if (view === 'AUTH' && !user) currentContent = <AuthPage initialRole={authRole} onBack={() => setView('HOME')} />;
  else if (user) {
      if (view === 'DASHBOARD') {
        if (user.role === UserRole.ADMIN) currentContent = <AdminPortal />;
        else if (user.role === UserRole.COMPANY) currentContent = <CompanyPortal />;
        else currentContent = <StudentPortal />;
      } else {
        currentContent = <LandingPage onLoginClick={(role) => { setAuthRole(role); setView('AUTH'); }} onViewChange={setView} />;
      }
  } else {
      currentContent = <LandingPage onLoginClick={(role) => { setAuthRole(role); setView('AUTH'); }} onViewChange={setView} />;
  }

  const showGlobalNav = view !== 'HOME' && view !== 'AUTH';

  return (
    <div className="font-sans text-gray-900 bg-gray-50 min-h-screen" style={{ fontSize: `${siteConfig.baseFontSize}px` }}>
      {showGlobalNav && <Navbar onViewChange={setView} />}
      {currentContent}
      <ScrollToTopButton />
    </div>
  );
};

const App: React.FC = () => {
  return (
    <AppProvider>
      <FixMyProblemApp />
    </AppProvider>
  );
};

export default App;

import React, { useState } from 'react';
import { useStore } from '../context/Store';
import { UserRole } from '../types';
import { LogOut, Code2, Trophy, Info, Briefcase, Mail, Menu, X, CreditCard } from 'lucide-react';
import ProfileCard from './ProfileCard';

type ViewState = 'HOME' | 'LEADERBOARD' | 'PRIVACY' | 'TERMS' | 'CONTACT' | 'AUTH' | 'DASHBOARD' | 'PAYMENT_HISTORY';

interface NavbarProps {
  onViewChange: (view: ViewState) => void;
  transparent?: boolean;
}

const Navbar: React.FC<NavbarProps> = ({ onViewChange, transparent }) => {
  const { user, logout } = useStore();
  const [showProfileCard, setShowProfileCard] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const handleNavLinkClick = (view: ViewState, hash?: string) => {
    if (view === 'HOME' && hash) {
      onViewChange('HOME');
      setTimeout(() => {
        const element = document.getElementById(hash);
        if (element) element.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    } else {
      onViewChange(view);
    }
    setIsMobileMenuOpen(false);
  };

  const commonNavLinkClasses = (isMobile = false) => `
    font-medium text-sm flex items-center transition-opacity hover:opacity-80
    ${transparent && !isMobile ? 'text-white/90' : 'text-gray-600'}
    ${isMobile ? 'text-white/90 justify-center py-3 w-full hover:bg-white/10 rounded-lg' : ''}
  `;

  const renderNavLinks = (isMobile = false) => (
    <>
      <button onClick={() => handleNavLinkClick('HOME', 'about')} className={commonNavLinkClasses(isMobile)}>
        <Info className="w-4 h-4 mr-1" /> About
      </button>
      <button onClick={() => handleNavLinkClick('LEADERBOARD')} className={commonNavLinkClasses(isMobile)}>
        <Trophy className="w-4 h-4 mr-1" /> Rankings
      </button>
      {user && (
        <button onClick={() => handleNavLinkClick('PAYMENT_HISTORY')} className={commonNavLinkClasses(isMobile)}>
          <CreditCard className="w-4 h-4 mr-1" /> Payments
        </button>
      )}
      <button onClick={() => handleNavLinkClick('CONTACT')} className={commonNavLinkClasses(isMobile)}>
        <Mail className="w-4 h-4 mr-1" /> Contact
      </button>
    </>
  );

  return (
    <nav className={`fixed top-0 w-full z-50 transition-all duration-300 ${transparent ? 'bg-transparent pt-4' : 'bg-white/90 backdrop-blur-md border-b border-gray-200'}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16 items-center">
          <div className="flex items-center cursor-pointer group" onClick={() => handleNavLinkClick('DASHBOARD')}>
            <div className={`rounded-lg p-1.5 mr-2 transition-colors ${transparent ? 'bg-white/10 group-hover:bg-white/20' : 'bg-blue-600'}`}>
              <Code2 className="h-6 w-6 text-white" />
            </div>
            <span className={`text-xl font-extrabold tracking-tight ${transparent ? 'text-white' : 'text-gray-900'}`}>FixMyProblem</span>
          </div>

          <div className="hidden md:flex items-center space-x-6">
            {renderNavLinks()}
            {user ? (
              <div className="flex items-center space-x-4 relative" onMouseEnter={() => setShowProfileCard(true)} onMouseLeave={() => setShowProfileCard(false)}>
                <div className={`text-sm hidden md:block text-right ${transparent ? 'text-white' : 'text-gray-700'}`}>
                  <div className="font-semibold">{user.name}</div>
                  <div className={`uppercase text-[10px] tracking-wider ${transparent ? 'text-white/60' : 'text-gray-500'}`}>{user.role}</div>
                </div>
                {user.profilePicUrl ? <img src={user.profilePicUrl} className="w-10 h-10 rounded-full border-2 border-white object-cover" /> : <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold border-2 border-white">{user.name.charAt(0)}</div>}
                {showProfileCard && <ProfileCard user={user} onClose={() => setShowProfileCard(false)} positionClasses="top-full right-0 mt-2" />}
                <button onClick={logout} className={`p-2 rounded-full transition-colors ${transparent ? 'hover:bg-white/10 text-white' : 'hover:bg-gray-100 text-gray-600'}`}><LogOut className="h-5 w-5" /></button>
              </div>
            ) : <button onClick={() => handleNavLinkClick('AUTH')} className="text-sm font-bold px-5 py-2 rounded-full bg-slate-900 text-white">Login</button>}
          </div>

          <div className="md:hidden flex items-center">
            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className={transparent ? 'text-white' : 'text-gray-600'}>
              {isMobileMenuOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
            </button>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

import React, { useState } from 'react';
import Modal from './Modal';
import { Loader2, CreditCard, Landmark, Smartphone, ShieldCheck, CheckCircle2 } from 'lucide-react';

interface PaymentGatewayModalProps {
  isOpen: boolean;
  onClose: () => void;
  amount: string;
  recipient: string;
  onSuccess: (method: string) => void;
}

const PaymentGatewayModal: React.FC<PaymentGatewayModalProps> = ({ isOpen, onClose, amount, recipient, onSuccess }) => {
  const [step, setStep] = useState<'CHOICE' | 'PROCESSING' | 'SUCCESS'>('CHOICE');
  const [method, setMethod] = useState('');

  const handlePay = (selectedMethod: string) => {
    setMethod(selectedMethod);
    setStep('PROCESSING');
    setTimeout(() => {
      setStep('SUCCESS');
      setTimeout(() => {
        onSuccess(selectedMethod);
        setStep('CHOICE');
      }, 1500);
    }, 2000);
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="Secure Checkout">
      <div className="p-2">
        {step === 'CHOICE' && (
          <div className="space-y-6">
            <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
              <p className="text-xs text-blue-600 font-bold uppercase tracking-wider mb-1">Total Payout</p>
              <div className="flex justify-between items-end">
                <span className="text-3xl font-black text-blue-900">{amount}</span>
                <span className="text-sm text-blue-700 font-medium">to {recipient}</span>
              </div>
            </div>

            <div className="grid grid-cols-1 gap-3">
              <button onClick={() => handlePay('Credit Card')} className="flex items-center justify-between p-4 border border-gray-200 rounded-xl hover:border-blue-500 hover:bg-blue-50 transition-all group">
                <div className="flex items-center">
                  <div className="bg-gray-100 p-2 rounded-lg group-hover:bg-blue-100 transition-colors">
                    <CreditCard className="w-5 h-5 text-gray-600 group-hover:text-blue-600" />
                  </div>
                  <span className="ml-3 font-bold text-gray-700 group-hover:text-blue-900">Credit / Debit Card</span>
                </div>
                <div className="w-2 h-2 rounded-full bg-gray-300 group-hover:bg-blue-500"></div>
              </button>

              <button onClick={() => handlePay('UPI')} className="flex items-center justify-between p-4 border border-gray-200 rounded-xl hover:border-blue-500 hover:bg-blue-50 transition-all group">
                <div className="flex items-center">
                  <div className="bg-gray-100 p-2 rounded-lg group-hover:bg-blue-100 transition-colors">
                    <Smartphone className="w-5 h-5 text-gray-600 group-hover:text-blue-600" />
                  </div>
                  <span className="ml-3 font-bold text-gray-700 group-hover:text-blue-900">UPI (GPay / PhonePe)</span>
                </div>
                <div className="w-2 h-2 rounded-full bg-gray-300 group-hover:bg-blue-500"></div>
              </button>

              <button onClick={() => handlePay('Net Banking')} className="flex items-center justify-between p-4 border border-gray-200 rounded-xl hover:border-blue-500 hover:bg-blue-50 transition-all group">
                <div className="flex items-center">
                  <div className="bg-gray-100 p-2 rounded-lg group-hover:bg-blue-100 transition-colors">
                    <Landmark className="w-5 h-5 text-gray-600 group-hover:text-blue-600" />
                  </div>
                  <span className="ml-3 font-bold text-gray-700 group-hover:text-blue-900">Net Banking</span>
                </div>
                <div className="w-2 h-2 rounded-full bg-gray-300 group-hover:bg-blue-500"></div>
              </button>
            </div>

            <p className="text-[10px] text-gray-400 text-center flex items-center justify-center">
              <ShieldCheck className="w-3 h-3 mr-1 text-green-500" /> Secure 256-bit SSL Encrypted Payment
            </p>
          </div>
        )}

        {step === 'PROCESSING' && (
          <div className="py-20 flex flex-col items-center">
            <Loader2 className="w-16 h-16 text-blue-600 animate-spin mb-6" />
            <h3 className="text-xl font-bold text-gray-900">Processing Payment...</h3>
            <p className="text-sm text-gray-500 mt-2">Connecting to secure {method} gateway</p>
          </div>
        )}

        {step === 'SUCCESS' && (
          <div className="py-20 flex flex-col items-center text-center animate-pop-in">
            <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-6 border-4 border-green-500 animate-bounce">
              <CheckCircle2 className="w-12 h-12" />
            </div>
            <h3 className="text-2xl font-black text-gray-900">Payment Successful!</h3>
            <p className="text-gray-500 mt-2">Bounty has been transferred to the student's wallet.</p>
          </div>
        )}
      </div>
    </Modal>
  );
};

export default PaymentGatewayModal;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/Store';
import { UserRole, Problem, Solution, User } from '../types';
import { Briefcase, Edit2, Power, Download, Award, Star, IndianRupee, Sparkles, CheckCircle2, Globe, Loader2, BookOpenText, CalendarDays, Wallet } from 'lucide-react';
import { refineProblemDescription } from '../services/geminiService';
import Modal from '../components/Modal';
import ProfileEditModal from '../components/ProfileEditModal';
import StarRatingInput from '../components/StarRatingInput';
import ProblemDetailModal from '../components/ProblemDetailModal';
import ProfileCard from '../components/ProfileCard';
import PaymentGatewayModal from '../components/PaymentGatewayModal';

const CompanyPortal: React.FC = () => {
    const { user, problems, addProblem, acceptSolution, allUsers, editProblem, manualCloseProblem } = useStore();

    const [modalMode, setModalMode] = useState<'POST' | 'EDIT' | null>(null);
    const [acceptModalOpen, setAcceptModalOpen] = useState<Solution | null>(null);
    const [showProblemDetailModal, setShowProblemDetailModal] = useState(false);
    const [showPaymentGateway, setShowPaymentGateway] = useState(false);

    const [currentProblem, setCurrentProblem] = useState<Problem | null>(null);
    const [title, setTitle] = useState('');
    const [desc, setDesc] = useState('');
    const [bounty, setBounty] = useState('');
    const [tags, setTags] = useState('');

    const [rating, setRating] = useState(5);
    const [feedback, setFeedback] = useState('');

    const [isRefining, setIsRefining] = useState(false);
    const [isProfileOpen, setIsProfileOpen] = useState(false);
    const [showCompanyProfileCard, setShowCompanyProfileCard] = useState(false);

    const myProblems = problems.filter(p => p.companyId === user?.id);
    const topStudents = useMemo(() => allUsers.filter(u => u.role === UserRole.STUDENT).sort((a, b) => (b.rating || 0) - (a.rating || 0)).slice(0, 5), [allUsers]);

    const openPostModal = () => {
        setCurrentProblem(null);
        setTitle(''); setDesc(''); setBounty(''); setTags('');
        setModalMode('POST');
    };

    const openEditModal = (problem: Problem) => {
        setCurrentProblem(problem);
        setTitle(problem.title);
        setDesc(problem.description);
        setBounty(problem.bounty);
        setTags(problem.tags.join(', '));
        setModalMode('EDIT');
    };

    const handleFormSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (modalMode === 'EDIT' && currentProblem) {
            await editProblem(currentProblem.id, title, desc, bounty, tags.split(',').map(t => t.trim()));
        } else {
            addProblem(title, desc, bounty, tags.split(',').map(t => t.trim()));
        }
        setModalMode(null);
    };

    const handleAcceptClick = () => {
        setAcceptModalOpen(null);
        setShowPaymentGateway(true);
    };

    const handlePaymentSuccess = async (method: string) => {
        if (acceptModalOpen) {
            await acceptSolution(acceptModalOpen.problemId, acceptModalOpen.id, acceptModalOpen.studentId, rating, feedback, method);
            setShowPaymentGateway(false);
            setAcceptModalOpen(null);
            setRating(5);
            setFeedback('');
        }
    };

    const handleAIRefine = async () => {
        if (!desc) return;
        setIsRefining(true);
        try {
            const refined = await refineProblemDescription(desc);
            setDesc(refined);
        } catch (error) { console.error("AI Refinement failed", error); }
        setIsRefining(false);
    };

    const handleCloseProblem = async (problemId: string) => {
        if (window.confirm("Are you sure? This will close the problem for new submissions.")) {
            await manualCloseProblem(problemId);
        }
    };

    const openProblemDetails = (problem: Problem) => {
        setCurrentProblem(problem);
        setShowProblemDetailModal(true);
    };

    return (
        <div className="min-h-screen bg-gray-50 pt-20 px-4 pb-12">
            <div className="max-w-7xl mx-auto">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
                    <div>
                        <h1 className="text-2xl md:text-3xl font-bold text-gray-900">Company Dashboard</h1>
                        <div className="relative group" onMouseEnter={() => setShowCompanyProfileCard(true)} onMouseLeave={() => setShowCompanyProfileCard(false)}>
                            <button onClick={() => setIsProfileOpen(true)} className="text-sm text-blue-600 hover:text-blue-800 font-bold mt-2 flex items-center">
                                <Edit2 className="w-4 h-4 mr-1" /> Edit Profile
                            </button>
                            {showCompanyProfileCard && user && <ProfileCard user={user} onClose={() => setShowCompanyProfileCard(false)} positionClasses="top-full left-0 mt-2" />}
                        </div>
                    </div>
                    <button onClick={openPostModal} className="bg-blue-600 text-white px-6 py-3 rounded-lg font-bold hover:bg-blue-700 flex items-center shadow-md">
                        <Briefcase className="w-5 h-5 mr-2" /> Post Challenge
                    </button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    <div className="lg:col-span-2 space-y-6">
                        <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center">
                            <Briefcase className="w-5 h-5 mr-2 text-blue-600" /> Your Challenges
                        </h2>
                        {myProblems.map(p => (
                            <div key={p.id} className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
                                <div className="flex justify-between mb-4">
                                    <h3 className="text-lg font-bold">{p.title}</h3>
                                    <div className="flex items-center gap-2">
                                        <button onClick={() => openEditModal(p)} className="p-2 text-gray-400 hover:text-blue-600 rounded-full"><Edit2 className="w-4 h-4" /></button>
                                        {p.status === 'OPEN' && <button onClick={() => handleCloseProblem(p.id)} className="p-2 text-gray-400 hover:text-red-600 rounded-full"><Power className="w-4 h-4"/></button>}
                                        <span className={`px-2 py-1 rounded text-xs font-bold ${p.status === 'OPEN' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'}`}>{p.status}</span>
                                    </div>
                                </div>
                                <div onClick={() => openProblemDetails(p)} className="cursor-pointer">
                                  <p className="text-sm text-gray-500 line-clamp-2 mb-4">{p.description}</p>
                                </div>
                                <div className="mt-4">
                                    <h4 className="font-bold text-xs text-gray-400 uppercase mb-3">Submissions</h4>
                                    <div className="space-y-2">
                                        {p.solutions?.map(s => (
                                            <div key={s.id} className={`flex justify-between items-center p-3 rounded-lg border ${s.isAccepted ? 'bg-green-50 border-green-200' : 'bg-gray-50 border-gray-100'}`}>
                                                <span className="font-bold text-gray-800 text-sm">{s.studentName}</span>
                                                <div className="flex gap-2">
                                                    {s.attachmentUrl && <a href={s.attachmentUrl} target="_blank" className="p-2 text-gray-500 hover:text-blue-600"><Download className="w-4 h-4"/></a>}
                                                    {p.status === 'OPEN' && !s.isAccepted && <button onClick={() => setAcceptModalOpen(s)} className="text-xs bg-green-600 text-white px-3 py-1.5 rounded-lg font-bold hover:bg-green-700">Accept</button>}
                                                    {s.isAccepted && <span className="text-xs text-green-600 font-black uppercase flex items-center"><CheckCircle2 className="w-4 h-4 mr-1"/> Accepted</span>}
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="space-y-6">
                        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
                            <h2 className="text-lg font-bold text-gray-800 mb-4 flex items-center">
                                <Award className="w-5 h-5 mr-2 text-yellow-500" /> Leaderboard
                            </h2>
                            <div className="space-y-4">
                                {topStudents.map((s, idx) => (
                                    <div key={s.id} className="flex items-center justify-between py-2 border-b border-gray-50 last:border-0">
                                        <div className="flex items-center">
                                            <span className="text-xs font-bold text-gray-400 mr-3">#{idx+1}</span>
                                            <div>
                                                <div className="font-bold text-sm text-gray-900">{s.name}</div>
                                                <div className="text-[10px] text-gray-500 uppercase">{s.university}</div>
                                            </div>
                                        </div>
                                        <div className="font-bold text-blue-600 text-sm">{s.rating?.toFixed(1)} ★</div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <Modal isOpen={!!modalMode} onClose={() => setModalMode(null)} title={modalMode === 'EDIT' ? 'Edit Challenge' : 'Post Challenge'}>
                <form onSubmit={handleFormSubmit} className="space-y-4">
                    <input required className="w-full border p-3 rounded-lg text-sm" placeholder="Title" value={title} onChange={e => setTitle(e.target.value)} />
                    <div className="flex justify-between items-center">
                       <label className="text-xs font-bold text-gray-500 uppercase">Description</label>
                       <button type="button" onClick={handleAIRefine} className="text-xs text-blue-600 font-bold flex items-center">
                            {isRefining ? <Loader2 className="w-3 h-3 mr-1 animate-spin" /> : <Sparkles className="w-3 h-3 mr-1" />} AI Polish
                       </button>
                    </div>
                    <textarea required className="w-full border p-3 rounded-lg h-32 text-sm" placeholder="Details..." value={desc} onChange={e => setDesc(e.target.value)} />
                    <div className="grid grid-cols-2 gap-4">
                        <input required className="border p-3 rounded-lg text-sm" placeholder="Bounty (e.g. ₹5000)" value={bounty} onChange={e => setBounty(e.target.value)} />
                        <input className="border p-3 rounded-lg text-sm" placeholder="Tags" value={tags} onChange={e => setTags(e.target.value)} />
                    </div>
                    <button type="submit" className="w-full bg-blue-600 text-white py-3 rounded-lg font-bold">Publish</button>
                </form>
            </Modal>

            <Modal isOpen={!!acceptModalOpen} onClose={() => setAcceptModalOpen(null)} title="Approve Solution">
                <div className="space-y-6">
                    <p className="text-sm text-gray-600">Reviewing solution from <span className="font-bold text-gray-900">{acceptModalOpen?.studentName}</span>. Proceeding will initiate the bounty transfer.</p>
                    <div className="py-6 bg-gray-50 rounded-xl border border-gray-100 flex flex-col items-center">
                        <label className="text-xs font-bold text-gray-400 uppercase mb-4">Quality Rating</label>
                        <StarRatingInput rating={rating} setRating={setRating} />
                    </div>
                    <textarea className="w-full border p-3 rounded-lg h-24 text-sm" placeholder="Feedback for student..." value={feedback} onChange={e => setFeedback(e.target.value)} />
                    <button onClick={handleAcceptClick} className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold flex items-center justify-center shadow-lg">
                        <Wallet className="w-5 h-5 mr-2" /> Proceed to Payout
                    </button>
                </div>
            </Modal>

            <PaymentGatewayModal 
                isOpen={showPaymentGateway} 
                onClose={() => setShowPaymentGateway(false)} 
                amount={problems.find(p => p.id === acceptModalOpen?.problemId)?.bounty || '0'}
                recipient={acceptModalOpen?.studentName || ''}
                onSuccess={handlePaymentSuccess}
            />

            <ProfileEditModal isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} />
            <ProblemDetailModal isOpen={showProblemDetailModal} onClose={() => setShowProblemDetailModal(false)} problem={currentProblem} />
        </div>
    );
};

export default CompanyPortal;

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Problem, UserRole, Solution, Review, SiteConfig, Payment } from '../types';
import { auth, db } from '../services/firebase';
import { supabase } from '../services/supabase';

interface AppContextType {
  user: User | null;
  loading: boolean;
  allUsers: User[];
  problems: Problem[];
  payments: Payment[];
  siteConfig: SiteConfig;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string, role: UserRole, name: string, extraInfo: string) => Promise<void>;
  logout: () => void;
  resetPassword: (email: string) => Promise<void>;
  addProblem: (title: string, description: string, bounty: string, tags: string[]) => void;
  editProblem: (problemId: string, title: string, description: string, bounty: string, tags: string[]) => Promise<void>;
  manualCloseProblem: (problemId: string) => Promise<void>;
  addSolution: (problemId: string, content: string, file?: File) => Promise<void>;
  acceptSolution: (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, paymentMethod: string) => Promise<void>;
  updateUserProfile: (name: string, bio: string, skills: string[], file?: File, websiteUrl?: string) => Promise<void>;
  adminBanUser: (userId: string, currentStatus: boolean) => Promise<void>;
  adminDeleteUser: (userId: string) => Promise<void>;
  adminDeleteProblem: (problemId: string) => Promise<void>;
  updateSiteConfig: (newConfig: Partial<SiteConfig>) => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [problems, setProblems] = useState<Problem[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [siteConfig, setSiteConfig] = useState<SiteConfig>({ baseFontSize: 16, enableDarkMode: true });

  const solutionUnsubscribes = useRef<Record<string, () => void>>({});

  useEffect(() => {
    const docRef = db.collection("settings").doc("global");
    const unsub = docRef.onSnapshot(
      (docSnap) => {
        if (docSnap.exists) {
            setSiteConfig(docSnap.data() as SiteConfig);
        }
      },
      (error) => {
        console.warn("Settings listener restricted:", error.message);
      }
    );
    return () => unsub();
  }, []);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (firebaseUser) => {
      if (firebaseUser && firebaseUser.emailVerified) {
        try {
          const docRef = db.collection("users").doc(firebaseUser.uid);
          const docSnap = await docRef.get();
          if (docSnap.exists) {
            const userData = { id: firebaseUser.uid, ...docSnap.data() } as User;
            if (!userData.isBanned) setUser(userData);
            else await auth.signOut();
          }
        } catch (error) { setUser(null); }
      } else { setUser(null); }
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    // Only fetch all users if someone is logged in (usually for profile cards/leaderboard)
    if (!user) {
      setAllUsers([]);
      return;
    }
    const unsub = db.collection("users").onSnapshot(
      (snapshot) => {
        setAllUsers(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as User)));
      },
      (error) => {
        console.warn("Users list listener restricted:", error.message);
      }
    );
    return () => unsub();
  }, [user?.id]);

  useEffect(() => {
    const unsub = db.collection("problems").orderBy("createdAt", "desc").onSnapshot(
      (snapshot) => {
        const problemsData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data(), solutions: [] })) as Problem[];
        setProblems(problemsData);

        problemsData.forEach(p => {
          if (!solutionUnsubscribes.current[p.id]) {
            solutionUnsubscribes.current[p.id] = db.collection("problems").doc(p.id).collection("solutions").onSnapshot(
              (s) => {
                setProblems(current => current.map(cp => cp.id === p.id ? { ...cp, solutions: s.docs.map(sd => ({ id: sd.id, ...sd.data() } as Solution)) } : cp));
              },
              (err) => {
                console.warn(`Solutions listener restricted for problem ${p.id}:`, err.message);
              }
            );
          }
        });
      },
      (error) => {
        console.warn("Problems listener restricted:", error.message);
      }
    );
    return () => {
      unsub();
      Object.values(solutionUnsubscribes.current).forEach(u => u());
      solutionUnsubscribes.current = {};
    };
  }, [user?.id]);

  useEffect(() => {
    if (!user) { setPayments([]); return; }
    const q = db.collection("payments").orderBy("timestamp", "desc");
    const unsub = q.onSnapshot(
      (snap) => {
        const allPayments = snap.docs.map(d => ({ id: d.id, ...d.data() } as Payment));
        if (user.role === UserRole.ADMIN) setPayments(allPayments);
        else setPayments(allPayments.filter(p => p.fromId === user.id || p.toId === user.id));
      },
      (error) => {
        console.warn("Payments listener restricted:", error.message);
      }
    );
    return () => unsub();
  }, [user?.id]);

  const login = async (email: string, password: string) => {
    await auth.signInWithEmailAndPassword(email, password);
  };

  const register = async (email: string, password: string, role: UserRole, name: string, extraInfo: string) => {
    const userCredential = await auth.createUserWithEmailAndPassword(email, password);
    const uid = userCredential.user!.uid;
    const newUser = { id: uid, email, name, role, university: role === UserRole.STUDENT ? extraInfo : null, companyName: role === UserRole.COMPANY ? extraInfo : null, rating: role === UserRole.STUDENT ? 0 : null, solvedCount: 0, reviews: [], lastSeen: new Date().toISOString(), bio: '', profilePicUrl: '', skills: [] };
    await db.collection("users").doc(uid).set(newUser);
    await userCredential.user!.sendEmailVerification();
    await auth.signOut();
  };

  const logout = () => auth.signOut();
  const resetPassword = (email: string) => auth.sendPasswordResetEmail(email);

  const addProblem = async (title: string, description: string, bounty: string, tags: string[]) => {
    if (!user || user.role !== UserRole.COMPANY) return;
    await db.collection("problems").add({ companyId: user.id, companyName: user.companyName, title, description, bounty, status: 'OPEN', createdAt: new Date().toISOString(), tags });
  };

  const editProblem = async (id: string, title: string, description: string, bounty: string, tags: string[]) => {
    await db.collection("problems").doc(id).update({ title, description, bounty, tags });
  };

  const manualCloseProblem = async (id: string) => {
    await db.collection("problems").doc(id).update({ status: 'CLOSED' });
  };

  const addSolution = async (problemId: string, content: string, file?: File) => {
    if (!user) return;
    let attachmentUrl = null, attachmentName = null;
    if (file) {
      const path = `${problemId}/${user.id}/${Date.now()}_${file.name}`;
      await supabase.storage.from('solutions').upload(path, file);
      attachmentUrl = supabase.storage.from('solutions').getPublicUrl(path).data.publicUrl;
      attachmentName = file.name;
    }
    await db.collection("problems").doc(problemId).collection("solutions").add({ problemId, studentId: user.id, studentName: user.name, content, submittedAt: new Date().toISOString(), isAccepted: false, attachmentUrl, attachmentName });
  };

  const acceptSolution = async (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, paymentMethod: string) => {
    if (!user) return;
    const prob = problems.find(p => p.id === problemId);
    const student = allUsers.find(u => u.id === studentId);
    if (!prob || !student) return;

    await db.runTransaction(async (transaction) => {
      const probRef = db.collection("problems").doc(problemId);
      const solRef = probRef.collection("solutions").doc(solutionId);
      const studentRef = db.collection("users").doc(studentId);
      const payRef = db.collection("payments").doc();

      transaction.update(solRef, { isAccepted: true, rating, feedback });
      transaction.update(probRef, { status: 'CLOSED' });

      const newReview = { id: solutionId, problemTitle: prob.title, rating, feedback, createdAt: new Date().toISOString(), companyName: user.companyName };
      const totalScore = ((student.rating || 0) * (student.reviews?.length || 0)) + rating;
      const newRating = Number((totalScore / ((student.reviews?.length || 0) + 1)).toFixed(1));

      transaction.update(studentRef, { 
        solvedCount: (student.solvedCount || 0) + 1, 
        rating: newRating, 
        reviews: [...(student.reviews || []), newReview] 
      });

      transaction.set(payRef, {
        problemId,
        problemTitle: prob.title,
        amount: prob.bounty,
        status: 'COMPLETED',
        fromId: user.id,
        fromName: user.companyName,
        toId: studentId,
        toName: student.name,
        timestamp: new Date().toISOString(),
        method: paymentMethod
      });
    });
  };

  const updateUserProfile = async (name: string, bio: string, skills: string[], file?: File, websiteUrl?: string) => {
    if (!user) return;
    await db.collection("users").doc(user.id).update({ name, bio, skills, websiteUrl });
    setUser(prev => prev ? { ...prev, name, bio, skills, websiteUrl } : null);
  };

  const adminBanUser = async (id: string, status: boolean) => {
    await db.collection("users").doc(id).update({ isBanned: !status });
  };
  const adminDeleteUser = async (id: string) => { await db.collection("users").doc(id).delete(); };
  const adminDeleteProblem = async (id: string) => { await db.collection("problems").doc(id).delete(); };
  const updateSiteConfig = async (c: Partial<SiteConfig>) => { await db.collection("settings").doc("global").set(c, { merge: true }); };

  return (
    <AppContext.Provider value={{ user, loading, allUsers, problems, payments, siteConfig, login, register, logout, resetPassword, addProblem, addSolution, acceptSolution, editProblem, manualCloseProblem, updateUserProfile, adminBanUser, adminDeleteUser, adminDeleteProblem, updateSiteConfig }}>
      {children}
    </AppContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useStore must be used within AppProvider");
  return context;
};

