type ViewState = 'HOME' | 'LEADERBOARD' | 'PRIVACY' | 'TERMS' | 'CONTACT' | 'AUTH' | 'DASHBOARD' | 'PAYMENT_HISTORY';

interface NavbarProps {
  onViewChange: (view: ViewState) => void;
  transparent?: boolean;
}

const Navbar: React.FC<NavbarProps> = ({ onViewChange, transparent }) => {
  const { user, logout } = useStore();
  const [showProfileCard, setShowProfileCard] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const handleNavLinkClick = (view: ViewState, hash?: string) => {
    if (view === 'HOME' && hash) {
      onViewChange('HOME');
      setTimeout(() => {
        const element = document.getElementById(hash);
        if (element) element.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    } else {
      onViewChange(view);
    }
    setIsMobileMenuOpen(false);
  };

  const commonNavLinkClasses = (isMobile = false) => `
    font-medium text-sm flex items-center transition-opacity hover:opacity-80
    ${transparent && !isMobile ? 'text-gray-900' : 'text-gray-600'}
    ${isMobile ? 'text-white/90 justify-center py-3 w-full hover:bg-white/10 rounded-lg' : ''}
  `;

  const renderNavLinks = (isMobile = false) => (
    <>
      <button onClick={() => handleNavLinkClick('HOME', 'about')} className={commonNavLinkClasses(isMobile)}>
        <Info className="w-4 h-4 mr-1" /> About
      </button>
      <button onClick={() => handleNavLinkClick('LEADERBOARD')} className={commonNavLinkClasses(isMobile)}>
        <Trophy className="w-4 h-4 mr-1" /> Rankings
      </button>
      <button onClick={() => handleNavLinkClick('CONTACT')} className={commonNavLinkClasses(isMobile)}>
        <Mail className="w-4 h-4 mr-1" /> Contact
      </button>
    </>
  );

  return (
    <nav className={`fixed top-0 w-full z-50 transition-all duration-300 ${transparent ? 'bg-transparent pt-4' : 'bg-white/95 backdrop-blur-md border-b border-gray-100'}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
