                                    <div className="flex items-center font-black text-forest text-xl">
                                        <IndianRupee className="w-4 h-4" />
                                        {p.bounty.replace(/[^\d]/g, '')}
                                    </div>
                                </div>
                            </div>

                            <h3 className="text-2xl font-black text-black mb-4 line-clamp-2 leading-tight group-hover:text-coral transition-colors">{p.title}</h3>
                            <p className="text-gray-500 text-sm font-medium line-clamp-3 mb-8 flex-grow leading-relaxed">{p.description}</p>

                            <div className="flex flex-wrap gap-2 mb-8">
                                {p.tags.slice(0, 3).map(tag => (
                                    <span key={tag} className="text-[9px] font-black uppercase tracking-[0.2em] bg-gray-100 border border-black/5 px-2 py-1 rounded">
                                        {tag}
                                    </span>
                                ))}
                            </div>

                            <button 
                                disabled={p.status !== 'OPEN'} 
                                className={`tactile-btn w-full py-4 rounded-xl font-black text-sm uppercase tracking-widest flex items-center justify-center transition-all ${p.status === 'OPEN' ? 'bg-black text-white hover:bg-coral' : 'bg-gray-100 text-gray-400 cursor-not-allowed border-gray-200 shadow-none'}`}
                            >
                                {p.status === 'OPEN' ? (
                                    <>
                                        <Code2 className="w-4 h-4 mr-2" />
                                        Attempt Challenge
                                    </>
                                ) : (
                                    <>
                                        <Lock className="w-4 h-4 mr-2" />
                                        Protocol Locked
                                    </>
                                )}
                            </button>
                        </div>
                    ))}
                </div>

                {filteredProblems.length === 0 && (
                    <div className="text-center py-40 border-2 border-dashed border-black/10 rounded-[3rem]">
                        <Terminal className="w-16 h-16 text-gray-200 mx-auto mb-6" />
                        <p className="text-gray-400 text-xl font-black uppercase tracking-widest">No matching roadblocks found.</p>
                        <button onClick={() => setSearchQuery('')} className="mt-4 text-coral font-black underline decoration-citrus decoration-4 underline-offset-4">Reset Search Protocol</button>
                    </div>
                )}
           </div>

           {/* Modals remain mostly same but could use the same visual styling internally */}
           <ProblemDetailModal
                isOpen={showProblemDetailModal}
                onClose={() => setShowProblemDetailModal(false)}
                problem={currentProblemForDetails}
                onSolveClick={handleSolveFromDetails}
            />

           <Modal isOpen={!!selectedProblemIdForSubmission} onClose={() => setSelectedProblemIdForSubmission(null)} title="Submit Protocol Execution">
                <form onSubmit={handleSubmit} className="space-y-8">
                    <div>
                        <label className="text-xs font-black uppercase tracking-widest text-gray-400 block mb-3">System Task</label>
                        <div className="p-4 bg-gray-100 border-2 border-black rounded-xl font-bold text-gray-800">
                            {activeProblemForSubmission?.title}
                        </div>
                    </div>

                    <div>
                        <label className="text-xs font-black uppercase tracking-widest text-gray-400 block mb-3">Solution Payload</label>
                        <textarea 
                            required 
                            className="w-full border-2 border-black rounded-2xl p-6 h-64 font-mono text-sm focus:ring-0 outline-none transition-all shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] focus:translate-x-1 focus:translate-y-1 focus:shadow-none" 
                            placeholder="PASTE YOUR CODE OR ARCHITECTURAL LOGIC HERE..." 
                            value={solutionText} 
                            onChange={e => setSolutionText(e.target.value)} 
                        />
                    </div>

                    <div>
                        <label className="text-xs font-black uppercase tracking-widest text-gray-400 block mb-3">Package Archive (Optional)</label>
                        <div className="border-2 border-dashed border-black/20 rounded-2xl p-8 bg-gray-50/50 hover:bg-gray-50 transition-colors text-center">
                            <input 
                                type="file" 
                                accept=".zip,application/zip" 
                                onChange={e => setSolutionFile(e.target.files ? e.target.files[0] : null)} 
                                className="block w-full text-xs text-gray-400 file:mr-4 file:py-3 file:px-6 file:rounded-xl file:border-2 file:border-black file:text-xs file:font-black file:bg-citrus file:text-black hover:file:bg-black hover:file:text-white cursor-pointer"
                            />
                        </div>
                    </div>

                    <button 
                        type="submit" 
                        disabled={isSubmitting} 
                        className="tactile-btn w-full bg-coral text-white py-5 rounded-2xl font-black text-lg uppercase tracking-widest flex items-center justify-center"
                    >
                        {isSubmitting ? <Loader2 className="w-6 h-6 animate-spin" /> : <>Deploy Solution <ArrowUpRight className="ml-3 w-5 h-5" /></>}
                    </button>
                </form>
           </Modal>

           <ProfileEditModal isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} />
           <SubmissionSuccessModal 
                isOpen={showSuccessModal} 
                onClose={() => setShowSuccessModal(false)} 
                problemTitle={activeProblemForSubmission?.title || 'the challenge'}
            />
        </div>
    );
};

