import React, { useState, useEffect } from 'react';
import { AppProvider, useStore } from './context/Store';
import { UserRole } from './types';
import { Loader2 } from 'lucide-react';

import Navbar from './components/Navbar';
import ScrollToTopButton from './components/ScrollToTopButton';

import LandingPage from './pages/LandingPage';
import AuthPage from './pages/AuthPage';
import AdminPortal from './pages/AdminPortal';
import StudentPortal from './pages/StudentPortal';
import CompanyPortal from './pages/CompanyPortal';
import LegalPage from './pages/LegalPage';
import ContactPage from './pages/ContactPage';
import Leaderboard from './pages/Leaderboard';
import PaymentHistory from './pages/PaymentHistory';

type ViewState = 'HOME' | 'LEADERBOARD' | 'PRIVACY' | 'TERMS' | 'CONTACT' | 'AUTH' | 'DASHBOARD' | 'PAYMENT_HISTORY';

const FixMyProblemApp: React.FC = () => {
  const { user, loading, siteConfig } = useStore();
  const [view, setView] = useState<ViewState>('HOME');
  const [authRole, setAuthRole] = useState<UserRole>(UserRole.STUDENT);

  // Toggle landing page specific features like the emoji cursor
  useEffect(() => {
    if (view === 'HOME' && !user) {
      document.body.classList.add('landing-active');
    } else {
      document.body.classList.remove('landing-active');
    }
  }, [view, user]);

  useEffect(() => {
    if (user && view === 'AUTH') setView('DASHBOARD');
  }, [user]);

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-paper">
        <Loader2 className="w-12 h-12 animate-spin text-coral" />
    </div>
  );

  let currentContent;
  if (view === 'HOME' && !user) currentContent = <LandingPage onLoginClick={(role) => { setAuthRole(role); setView('AUTH'); }} onViewChange={setView} />;
  else if (view === 'LEADERBOARD') currentContent = <Leaderboard />;
  else if (view === 'PRIVACY' || view === 'TERMS') currentContent = <LegalPage type={view} />;
  else if (view === 'CONTACT') currentContent = <ContactPage />;
  else if (view === 'PAYMENT_HISTORY') currentContent = <PaymentHistory />;
  else if (view === 'AUTH' && !user) currentContent = <AuthPage initialRole={authRole} onBack={() => setView('HOME')} />;
  else if (user) {
      if (view === 'DASHBOARD') {
        if (user.role === UserRole.ADMIN) currentContent = <AdminPortal />;
        else if (user.role === UserRole.COMPANY) currentContent = <CompanyPortal />;
        else currentContent = <StudentPortal />;
      } else {
        currentContent = <LandingPage onLoginClick={(role) => { setAuthRole(role); setView('AUTH'); }} onViewChange={setView} />;
      }
  } else {
      currentContent = <LandingPage onLoginClick={(role) => { setAuthRole(role); setView('AUTH'); }} onViewChange={setView} />;
  }

  const showGlobalNav = view !== 'HOME' && view !== 'AUTH';

  return (
    <div className="font-sans text-black bg-paper min-h-screen" style={{ fontSize: `${siteConfig.baseFontSize}px` }}>
      {showGlobalNav && <Navbar onViewChange={setView} />}
      {currentContent}
      <ScrollToTopButton />
    </div>
  );
};

const App: React.FC = () => {
  return (
    <AppProvider>
      <FixMyProblemApp />
    </AppProvider>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/Store';
import { UserRole, Problem, Solution, User } from '../types';
import { GraduationCap, Search, Edit2, Star, Download, Loader2, Code2, Paperclip, Terminal, CheckCircle2, Briefcase, IndianRupee, Lock, Wallet, ArrowUpRight, Zap, Target } from 'lucide-react';
import Modal from '../components/Modal';
import ProfileEditModal from '../components/ProfileEditModal';
import SubmissionSuccessModal from '../components/SubmissionSuccessModal';
import ProblemDetailModal from '../components/ProblemDetailModal';
import ProfileCard from '../components/ProfileCard';

const StudentPortal: React.FC = () => {
    const { user, allUsers, problems, addSolution, payments } = useStore();
    const [selectedProblemIdForSubmission, setSelectedProblemIdForSubmission] = useState<string | null>(null);
    const [currentProblemForDetails, setCurrentProblemForDetails] = useState<Problem | null>(null);
    const [showProblemDetailModal, setShowProblemDetailModal] = useState(false);
    const [solutionText, setSolutionText] = useState('');
    const [solutionFile, setSolutionFile] = useState<File | null>(null);
    const [searchQuery, setSearchQuery] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isProfileOpen, setIsProfileOpen] = useState(false);
    const [showSuccessModal, setShowSuccessModal] = useState(false);

    const [showStudentProfileCard, setShowStudentProfileCard] = useState(false);

    const currentUserData = allUsers.find(u => u.id === user?.id) || user;
    const activeProblemForSubmission = problems.find(p => p.id === selectedProblemIdForSubmission);

    const totalEarned = payments.reduce((acc, p) => acc + (parseFloat(p.netAmount?.replace(/[^\d.]/g, '') || '0')), 0);

    const filteredProblems = useMemo(() => {
        return problems.filter(p => {
          const query = searchQuery.toLowerCase();
          return !query || p.title.toLowerCase().includes(query) || p.description.toLowerCase().includes(query) || p.tags.some(tag => tag.toLowerCase().includes(query));
        }).sort((a, b) => {
            if (a.status === 'OPEN' && b.status !== 'OPEN') return -1;
            if (a.status !== 'OPEN' && b.status === 'OPEN') return 1;
            return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
        });
    }, [problems, searchQuery]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (selectedProblemIdForSubmission && solutionText.trim()) {
            setIsSubmitting(true);
            try {
                await addSolution(selectedProblemIdForSubmission, solutionText, solutionFile || undefined);
                setSolutionText(''); 
                setSolutionFile(null); 
                setSelectedProblemIdForSubmission(null);
                setShowSuccessModal(true);
            } catch (error: any) { alert(`Submission Failed: ${error.message}`); }
            setIsSubmitting(false);
        }
    };

    const handleOpenProblemDetails = (problem: Problem) => {
        setCurrentProblemForDetails(problem);
        setShowProblemDetailModal(true);
    };

    const handleSolveFromDetails = (problemId: string) => {
        setSelectedProblemIdForSubmission(problemId);
        setShowProblemDetailModal(false);
    };

