                    <div className="space-y-4 reveal">
                        <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-black text-white rounded-xl text-[10px] font-black uppercase tracking-widest border border-black shadow-[4px_4px_0px_0px_rgba(253,224,71,1)]">
                           <Zap className="w-4 h-4 text-citrus fill-citrus" /> Active Protocol: Solver Tier Alpha
                        </div>
                        <h1 className="text-5xl md:text-7xl font-black text-black tracking-tighter leading-none">
                           Solver <span className="text-coral italic">Workspace.</span>
                        </h1>
                        <div 
                          className="flex items-center gap-4 relative group cursor-help"
                          onMouseEnter={() => setShowStudentProfileCard(true)}
                          onMouseLeave={() => setShowStudentProfileCard(false)}
                        >
                            <div className="w-14 h-14 rounded-2xl border-2 border-black bg-citrus overflow-hidden flex items-center justify-center font-black shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]">
                               {currentUserData?.profilePicUrl ? <img src={currentUserData.profilePicUrl} className="w-full h-full object-cover" /> : currentUserData?.name.charAt(0)}
                            </div>
                            <div>
                                <span className="text-2xl font-black hover:text-coral transition-colors">{currentUserData?.name}</span>
                                <div className="text-[10px] font-black uppercase tracking-widest text-gray-400">IIT Kharagpur Grid</div>
                            </div>
                            {showStudentProfileCard && currentUserData && <ProfileCard user={currentUserData} onClose={() => setShowStudentProfileCard(false)} positionClasses="top-full left-0 mt-4" />}
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-6 w-full lg:w-auto reveal">
                       <div className="tactile-card bg-forest text-white p-6 rounded-3xl flex flex-col justify-between">
                          <p className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-4">Net Extraction</p>
                          <div className="flex items-center text-3xl font-black">
                             <IndianRupee className="w-5 h-5 mr-1" />
                             {totalEarned.toLocaleString('en-IN')}
                          </div>
                       </div>
                       <div className="tactile-card bg-citrus text-black p-6 rounded-3xl flex flex-col justify-between border-black">
                          <p className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-4">Reputation Score</p>
                          <div className="flex items-center text-3xl font-black">
                             {currentUserData?.rating?.toFixed(1) || '0.0'}
                             <Star className="w-5 h-5 ml-1 fill-black" />
                          </div>
                       </div>
                    </div>
                </div>

                {/* Main Filter & Grid */}
                <div className="mb-12 relative group reveal">
                    <Search className="absolute left-6 top-1/2 -translate-y-1/2 h-6 w-6 text-gray-400 group-focus-within:text-coral transition-colors" />
                    <input 
                       type="text" 
                       placeholder="Scan roadblocks by tech, bounty or ID..." 
                       className="w-full pl-16 pr-8 py-6 rounded-[2rem] border-4 border-black shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] focus:shadow-none focus:translate-x-1 focus:translate-y-1 outline-none transition-all text-xl font-bold placeholder:text-gray-300" 
                       value={searchQuery} 
                       onChange={e => setSearchQuery(e.target.value)} 
                    />
                </div>

                <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-10">
                    {filteredProblems.map((p, idx) => (
                        <div 
                            key={p.id} 
                            onClick={() => handleOpenProblemDetails(p)}
