                        >
                            <div className="sticker-tape opacity-10 group-hover:opacity-100 transition-opacity"></div>

                            <div className="flex justify-between items-start mb-6">
                                <div className="px-3 py-1 bg-gray-50 border-2 border-black rounded-lg text-[10px] font-black uppercase tracking-widest flex items-center gap-2">
