                            <div className="flex flex-wrap gap-2 mb-8">
                                {p.tags.slice(0, 3).map(tag => (
                                    <span key={tag} className="text-[9px] font-black uppercase tracking-[0.2em] bg-citrus/20 border border-black/5 px-2 py-1 rounded">
                                        {tag}
                                    </span>
                                ))}
                            </div>

                            <button 
                                disabled={p.status !== 'OPEN'} 
                                className={`tactile-btn w-full py-5 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center transition-all ${p.status === 'OPEN' ? 'bg-black text-white hover:bg-coral' : 'bg-gray-100 text-gray-400 cursor-not-allowed border-black/10 shadow-none'}`}
                            >
                                {p.status === 'OPEN' ? (
                                    <>
                                        <Code2 className="w-4 h-4 mr-2" />
                                        Initialize Solution
                                    </>
                                ) : (
                                    <>
                                        <Lock className="w-4 h-4 mr-2" />
                                        System Locked
                                    </>
                                )}
                            </button>
                        </div>
                    ))}
                </div>

                {filteredProblems.length === 0 && (
                    <div className="text-center py-40 tactile-card border-dashed bg-white/50 rounded-[3rem]">
