                    </div>
                )}
           </div>

           {/* Modals are already quite tactile but let's ensure they are using App components */}
           <ProblemDetailModal
                isOpen={showProblemDetailModal}
                onClose={() => setShowProblemDetailModal(false)}
                problem={currentProblemForDetails}
                onSolveClick={handleSolveFromDetails}
            />

           <Modal isOpen={!!selectedProblemIdForSubmission} onClose={() => setSelectedProblemIdForSubmission(null)} title="Deploy Solution Protocol">
                <form onSubmit={handleSubmit} className="space-y-8">
                    <div>
                        <label className="text-xs font-black uppercase tracking-widest text-gray-400 block mb-3">Project Link</label>
                        <div className="p-4 bg-gray-100 border-2 border-black rounded-xl font-black text-forest">
                            {activeProblemForSubmission?.title}
