                            {showCompanyProfileCard && user && <ProfileCard user={user} onClose={() => setShowCompanyProfileCard(false)} positionClasses="top-full left-0 mt-4" />}
                        </div>
                    </div>
                    <button onClick={openPostModal} className="tactile-btn w-full md:w-auto px-10 py-5 bg-black text-white rounded-2xl font-black text-xl flex items-center justify-center shadow-md hover:bg-forest transition-all">
                        <Plus className="w-6 h-6 mr-3" /> Post Challenge
