                        <h2 className="text-xl md:text-2xl font-black text-black tracking-widest uppercase flex items-center">
                            <Briefcase className="w-6 h-6 mr-3 text-coral" /> Active Bounties
                        </h2>

                        {myProblems.length === 0 ? (
                            <div className="tactile-card p-12 text-center bg-white rounded-[2rem] border-dashed">
                                <p className="text-gray-400 font-black uppercase tracking-widest">No active protocols detected.</p>
                                <button onClick={openPostModal} className="mt-6 text-coral font-black underline underline-offset-4 decoration-2">Initialize First Challenge</button>
                            </div>
                        ) : myProblems.map((p, idx) => (
                            <div key={p.id} className={`tactile-card p-6 md:p-10 rounded-[2.5rem] bg-white transition-all duration-300 ${idx % 2 === 0 ? 'rotate-[-0.5deg]' : 'rotate-[0.5deg]'} hover:rotate-0`}>
                                <div className="sticker-tape opacity-10"></div>
                                <div className="flex flex-col sm:flex-row justify-between items-start gap-4 mb-6">
                                    <h3 className="text-2xl md:text-3xl font-black text-black tracking-tighter hover:text-coral transition-colors cursor-pointer" onClick={() => openProblemDetails(p)}>{p.title}</h3>
                                    <div className="flex items-center gap-3 w-full sm:w-auto">
                                        <button onClick={() => openEditModal(p)} className="flex-1 sm:flex-none p-3 bg-paper border-2 border-black rounded-xl hover:bg-citrus transition-all flex items-center justify-center"><Edit2 className="w-5 h-5" /></button>
                                        {p.status === 'OPEN' && <button onClick={() => handleCloseProblem(p.id)} className="flex-1 sm:flex-none p-3 bg-paper border-2 border-black rounded-xl hover:bg-coral hover:text-white transition-all flex items-center justify-center"><Power className="w-5 h-5"/></button>}
                                        <span className={`px-4 py-1.5 rounded-full border-2 border-black font-black text-[10px] uppercase tracking-[0.2em] whitespace-nowrap ${p.status === 'OPEN' ? 'bg-citrus' : 'bg-gray-100 text-gray-400'}`}>{p.status}</span>
