                                </div>

                                <div className="pt-8 border-t-2 border-black/5">
                                    <h4 className="font-black text-[10px] text-gray-400 uppercase tracking-[0.3em] mb-6 flex items-center gap-2">
                                       <Activity className="w-4 h-4" /> Solver Submissions
