                                            <div key={s.id} className={`tactile-card flex flex-col md:flex-row justify-between items-center p-6 rounded-2xl gap-4 ${s.isAccepted ? 'bg-citrus/10 border-forest' : 'bg-gray-50 border-black/5 shadow-none'}`}>
                                                <div className="text-center md:text-left">
                                                   <span className="font-black text-black text-lg block">{s.studentName}</span>
                                                   <span className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Protocol Version: 1.2</span>
                                                </div>
                                                <div className="flex gap-4 w-full md:w-auto">
                                                    {s.attachmentUrl && <a href={s.attachmentUrl} target="_blank" className="flex-1 md:flex-none p-3 bg-white border-2 border-black rounded-xl hover:scale-110 transition-transform flex items-center justify-center"><Download className="w-5 h-5 text-black"/></a>}
                                                    {p.status === 'OPEN' && !s.isAccepted && <button onClick={() => setAcceptModalOpen(s)} className="flex-[2] md:flex-none tactile-btn bg-black text-white px-6 py-2 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-forest">Audit & Accept</button>}
                                                    {s.isAccepted && <span className="flex-1 md:flex-none px-4 py-2 bg-forest text-citrus rounded-xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2 shadow-[3px_3px_0px_0px_rgba(0,0,0,1)]"><CheckCircle2 className="w-4 h-4"/> Accepted</span>}
                                                </div>
                                            </div>
                                        ))}
                                        {(!p.solutions || p.solutions.length === 0) && (
                                            <p className="text-center text-xs font-black text-gray-300 uppercase py-10 border-2 border-dashed border-black/10 rounded-2xl">Awaiting Solver Protocol...</p>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Right Column: Rankings & Tips */}
                    <div className="space-y-12 reveal">
                        <div className="tactile-card bg-black text-white p-8 md:p-10 rounded-[3rem] overflow-hidden">
                            <div className="absolute top-0 right-0 w-32 h-32 bg-citrus/10 rounded-full -mr-16 -mt-16"></div>
                            <h2 className="text-xl md:text-2xl font-black tracking-widest uppercase mb-8 flex items-center gap-3">
                                <Award className="w-6 h-6 text-citrus fill-citrus" /> Solver Rankings
