// Refines a raw problem description into a more professional and clear technical brief.
export const refineProblemDescription = async (rawDescription: string): Promise<string> => {
  // Direct initialization inside function as per safety requirements
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    console.error("API_KEY missing from environment");
    return rawDescription;
  }

  const ai = new GoogleGenAI({ apiKey });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Please refine and improve the following technical problem description for a professional bounty platform. 
      Make it clearer, more structured, and technically precise while maintaining all original requirements:

      "${rawDescription}"`,
      config: {
        systemInstruction: "You are a world-class senior engineering manager at a top tech company. You specialize in writing clear, professional, and attractive problem statements for expert software engineers."
      }
    });

    return response.text || rawDescription;
  } catch (error) {
    console.error("Gemini refinement error:", error);
    return rawDescription;
  }
};

// Fetches live trending engineering insights to populate the app's marquee/feed.
export const getLiveInsights = async (): Promise<string[]> => {
  const apiKey = process.env.API_KEY;
  const fallbackInsights = [
    "Optimizing Large Language Model latency for edge devices",
    "Scaling distributed databases for real-time fintech analytics",
    "Securing cross-origin authentication in zero-trust architectures",
    "Refactoring legacy monoliths to serverless microservices",
    "Implementing robust end-to-end encryption for healthcare data",
    "Reducing memory overhead in high-frequency trading systems",
    "Automating Kubernetes cluster management with custom operators"
  ];

  if (!apiKey) return fallbackInsights;

  const ai = new GoogleGenAI({ apiKey });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: "Generate 7 high-quality, diverse, and trending software engineering industry headlines or technical insights (e.g., about AI, cloud architecture, security, developer productivity). Return them as a JSON array of strings only.",
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.STRING
          }
        }
      }
    });

    const text = response.text || "[]";
    return JSON.parse(text.trim());
  } catch (error) {
    console.error("Gemini insights error:", error);
    return fallbackInsights;
  }
};

