import React, { useState } from 'react';
import { useStore } from '../context/Store.tsx';
import { UserRole } from '../types.ts';
import { Loader2, ArrowLeft, CheckCircle2, AlertTriangle, Zap, Terminal, Shield, Lock, Cpu, ArrowRight, Sparkles, Fingerprint } from 'lucide-react';

interface AuthPageProps {
  initialRole?: UserRole;
  onBack: () => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ initialRole, onBack }) => {
  const { login, register, resetPassword } = useStore();
  const [isLogin, setIsLogin] = useState(true);
  const [role, setRole] = useState<UserRole>(initialRole || UserRole.STUDENT);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [extraInfo, setExtraInfo] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isForgotPassword, setIsForgotPassword] = useState(false);
  const [message, setMessage] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setMessage('');
    setLoading(true);

    try {
      if (isForgotPassword) {
        await resetPassword(email);
        setMessage('Reset link deployed to your inbox. Check junk if missing.');
        setLoading(false);
        return;
      }

      if (isLogin) {
        await login(email, password);
      } else {
        if (role === UserRole.STUDENT) {
            const eduRegex = /^[a-zA-Z0-9._%+-]+@[a-zA-Z0-9.-]+\.(edu|ac\.[a-z]{2}|edu\.in)$/;
            if (!eduRegex.test(email)) throw new Error("Solver requires .edu or .ac.xx credentials.");
        }
        if (role === UserRole.ADMIN && extraInfo !== 'admin2024') throw new Error("Invalid Root Key.");

        await register(email, password, role, name, extraInfo);
        setMessage(`Verification sent to ${email}. Authenticate to proceed.`);
        setIsLogin(true);
      }
    } catch (err: any) {
      setError(err.message || 'System error detected.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-paper p-6 relative overflow-hidden">
      {/* Decorative Background Elements */}
      <div className="absolute top-10 left-10 opacity-5 animate-float hidden lg:block">
        <Cpu className="w-64 h-64" />
      </div>
      <div className="absolute bottom-10 right-10 opacity-5 animate-float [animation-delay:2s] hidden lg:block">
        <Terminal className="w-64 h-64" />
      </div>
      <div className="absolute top-1/2 left-[-100px] w-64 h-64 bg-citrus/10 rounded-full blur-[100px] pointer-events-none"></div>
      <div className="absolute top-1/2 right-[-100px] w-64 h-64 bg-coral/10 rounded-full blur-[100px] pointer-events-none"></div>

      <button 
        onClick={onBack}
        className="fixed top-8 left-8 z-50 flex items-center gap-3 px-6 py-3 bg-white border-[3px] border-black font-black text-[10px] uppercase tracking-widest shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] hover:translate-x-1 hover:translate-y-1 hover:shadow-none transition-all group"
      >
        <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" /> 
        Back to Grid
      </button>

      <div className="w-full max-w-xl relative">
        <div className="tactile-card bg-white p-8 md:p-14 rounded-[3rem] relative overflow-visible border-[3px] md:border-4">
          <div className="sticker-tape"></div>

          <div className="text-center mb-10">
             <div className="inline-flex items-center gap-2 px-4 py-2 bg-black text-white rounded-xl text-[9px] font-black uppercase tracking-[0.2em] mb-8 shadow-[4px_4px_0px_0px_rgba(255,95,95,1)]">
                <Fingerprint className="w-4 h-4 text-citrus animate-pulse" />
                {isLogin ? 'Identity Authentication' : 'Protocol Initialization'}
             </div>
             <h2 className="text-4xl md:text-6xl font-black text-black tracking-tighter leading-none mb-3">
                {isForgotPassword ? 'Reset Access' : (isLogin ? 'Welcome Back.' : 'Join the Grid.')}
             </h2>
             <p className="text-gray-400 text-[10px] font-black uppercase tracking-[0.3em] mt-4">
                {isForgotPassword ? "System recovery sequence" : "Sync your credentials to access the vault"}
             </p>
          </div>

          {message && (
             <div className="bg-forest text-white p-5 rounded-2xl mb-8 text-[10px] font-black uppercase tracking-widest border-[3px] border-black shadow-[4px_4px_0px_0px_rgba(253,224,71,1)] flex items-center">
                <CheckCircle2 className="w-5 h-5 mr-4 flex-shrink-0 text-citrus" /> {message}
             </div>
          )}

          {error && (
            <div className="bg-coral text-white p-5 rounded-2xl mb-8 text-[10px] font-black uppercase tracking-widest border-[3px] border-black shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] flex items-center">
                <AlertTriangle className="w-5 h-5 mr-4 flex-shrink-0" /> {error}
             </div>
          )}

          <form className="space-y-6" onSubmit={handleSubmit}>
             {!isLogin && !isForgotPassword && (
               <div className="grid grid-cols-2 gap-4 mb-10">
                  <button 
                    type="button" 
                    onClick={() => setRole(UserRole.STUDENT)} 
                    className={`py-5 text-[10px] font-black uppercase tracking-widest rounded-2xl border-[3px] transition-all flex flex-col items-center justify-center gap-3 ${role === UserRole.STUDENT ? 'bg-black text-white border-black shadow-[6px_6px_0px_0px_rgba(253,224,71,1)]' : 'bg-white text-gray-400 border-gray-100 hover:border-black hover:text-black'}`}
                  >
                    <Zap className={`w-6 h-6 ${role === UserRole.STUDENT ? 'text-citrus fill-citrus' : ''}`} /> Solver
