                    className={`py-5 text-[10px] font-black uppercase tracking-widest rounded-2xl border-[3px] transition-all flex flex-col items-center justify-center gap-3 ${role === UserRole.COMPANY ? 'bg-black text-white border-black shadow-[6px_6px_0px_0px_rgba(255,95,95,1)]' : 'bg-white text-gray-400 border-gray-100 hover:border-black hover:text-black'}`}
                  >
                    <Shield className={`w-6 h-6 ${role === UserRole.COMPANY ? 'text-coral fill-coral' : ''}`} /> Company
