             <div className="space-y-6">
               {!isLogin && !isForgotPassword && (
                 <>
                   <div className="space-y-2">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-2">Entity Name / Identity</label>
                     <input type="text" required placeholder="Major Motoko Kusanagi" className="w-full bg-paper border-[3px] border-black rounded-2xl px-6 py-5 text-black font-black placeholder:text-gray-200 focus:bg-citrus/10 outline-none transition-all shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] focus:shadow-none focus:translate-x-1 focus:translate-y-1" value={name} onChange={e => setName(e.target.value)} />
                   </div>
                   <div className="space-y-2">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-2">
                       {role === UserRole.STUDENT ? "University Hub" : "Corporate Grid"}
                     </label>
                     <input type="text" required placeholder={role === UserRole.STUDENT ? "MIT Grid" : "Hanka Robotics"} className="w-full bg-paper border-[3px] border-black rounded-2xl px-6 py-5 text-black font-black placeholder:text-gray-200 focus:bg-citrus/10 outline-none transition-all shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] focus:shadow-none focus:translate-x-1 focus:translate-y-1" value={extraInfo} onChange={e => setExtraInfo(e.target.value)} />
