                            >
                                {p.status === 'OPEN' ? (
                                    <>
                                        <Code2 className="w-4 h-4 mr-2" />
                                        Initialize Solution
                                    </>
                                ) : (
                                    <>
                                        <Lock className="w-4 h-4 mr-2" />
                                        System Locked
                                    </>
                                )}
                            </button>
                        </div>
                    ))}
                </div>

                {filteredProblems.length === 0 && (
                    <div className="text-center py-20 md:py-32 tactile-card border-dashed bg-white/50 rounded-[2rem] px-6">
