const Navbar: React.FC<NavbarProps> = ({ onViewChange, transparent, onProfileClick }) => {
  const { user, logout } = useStore();
  const [showProfileCard, setShowProfileCard] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleNav = useCallback((view: ViewState) => {
    onViewChange(view);
    setIsMobileMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [onViewChange]);

  const isDarkNavbar = scrolled || !transparent || isMobileMenuOpen;

  return (
    <nav className={`fixed top-0 w-full z-[100] transition-all duration-300 ${isDarkNavbar ? 'bg-white border-b-[3px] border-black py-3' : 'bg-transparent py-6 md:py-8'}`}>
      <div className="max-w-7xl mx-auto px-6 md:px-10 flex justify-between items-center">

        {/* Brand */}
        <div 
          className="flex items-center cursor-pointer group relative z-[110]" 
          onClick={() => handleNav('HOME')}
        >
          <div className="rounded-xl p-2 mr-3 bg-black border-2 border-citrus shadow-[3px_3px_0px_0px_rgba(255,95,95,1)] group-hover:rotate-6 transition-all duration-300">
            <Code2 className="h-5 w-5 text-white" />
          </div>
          <span className="text-xl md:text-2xl font-black tracking-tighter text-black">
            FixMyProblem
          </span>
        </div>

        {/* Desktop Nav */}
        <div className="hidden md:flex items-center space-x-8">
          <button onClick={() => handleNav('LEADERBOARD')} className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500 hover:text-black transition-colors">Solvers</button>
          <button onClick={() => handleNav('CONTACT')} className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500 hover:text-black transition-colors">Contact</button>
          {user ? (
            <div className="flex items-center space-x-6">
              <div 
                className="relative" 
                onMouseEnter={() => setShowProfileCard(true)} 
                onMouseLeave={() => setShowProfileCard(false)}
              >
                <div 
                  onClick={() => handleNav('DASHBOARD')}
                  className="w-11 h-11 rounded-2xl bg-citrus border-2 border-black overflow-hidden flex items-center justify-center font-black shadow-[3px_3px_0px_0px_rgba(0,0,0,1)] cursor-pointer"
                >
                  {user.profilePicUrl ? <img src={user.profilePicUrl} className="w-full h-full object-cover" /> : user.name.charAt(0)}
                </div>
                {showProfileCard && <ProfileCard user={user} onClose={() => setShowProfileCard(false)} positionClasses="top-full right-0 mt-6" />}
              </div>
              <button onClick={logout} className="p-2.5 rounded-xl hover:bg-red-50 text-gray-400 hover:text-red-600 border-2 border-transparent hover:border-black transition-all">
                <LogOut className="h-5 w-5" />
              </button>
            </div>
          ) : (
            <button 
              onClick={() => handleNav('AUTH')} 
              className="tactile-btn px-8 py-3 bg-black text-white rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-forest transition-all"
            >
              Get Started
            </button>
          )}
        </div>

        {/* Mobile Toggle */}
        <div className="md:hidden flex items-center relative z-[110]">
          <button 
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} 
            className="p-2 bg-black text-white rounded-lg border-2 border-black"
          >
            {isMobileMenuOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
          </button>
        </div>
      </div>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="md:hidden fixed inset-0 z-[100] bg-white flex flex-col items-center justify-center p-8 text-center space-y-8 animate-fade-in">
          <button onClick={() => handleNav('HOME')} className="text-4xl font-black text-black">Home</button>
          <button onClick={() => handleNav('LEADERBOARD')} className="text-4xl font-black text-black">Solvers</button>
          <button onClick={() => handleNav('CONTACT')} className="text-4xl font-black text-black">Contact</button>
          {user ? (
            <>
              <button onClick={() => handleNav('DASHBOARD')} className="text-4xl font-black text-coral">Workspace</button>
              <button onClick={logout} className="text-2xl font-black text-gray-400 pt-10">Disconnect</button>
            </>
          ) : (
            <button 
              onClick={() => handleNav('AUTH')} 
              className="tactile-btn w-full py-5 bg-black text-white rounded-2xl font-black text-xl uppercase tracking-widest"
            >
              Authenticate
            </button>
          )}
        </div>
      )}
    </nav>
  );
};

export default Navbar;

