    const handleRefine = async () => {
        if (!desc.trim()) return;
        setIsRefining(true);
        const refined = await refineProblemDescription(desc);
        setDesc(refined);
        setIsRefining(false);
    };

    const openPostModal = () => {
        setCurrentProblem(null);
        resetForm();
        setModalMode('POST');
