import React, { useEffect, useState, useRef } from 'react';

const CustomCursor: React.FC = () => {
  const cursorRef = useRef<HTMLDivElement>(null);
  const dotRef = useRef<HTMLDivElement>(null);
  const [isPointer, setIsPointer] = useState(false);
  const [isHidden, setIsHidden] = useState(false);
  const [isMouseDown, setIsMouseDown] = useState(false);

  useEffect(() => {
    const onMouseMove = (e: MouseEvent) => {
      const { clientX, clientY } = e;
      if (cursorRef.current && dotRef.current) {
        // Fast move for dot
        dotRef.current.style.transform = `translate3d(${clientX}px, ${clientY}px, 0)`;

        // Smooth move for ring using CSS transition/delay via JS if needed, 
        // but simple transform is most performant.
        // We use translate3d to trigger GPU acceleration.
        cursorRef.current.style.transform = `translate3d(${clientX}px, ${clientY}px, 0)`;
      }

      const target = e.target as HTMLElement;
      setIsPointer(
        window.getComputedStyle(target).cursor === 'pointer' || 
        target.tagName === 'BUTTON' || 
        target.tagName === 'A' ||
        !!target.closest('.tactile-card') ||
        !!target.closest('.tactile-btn')
      );
    };

    const onMouseDown = () => setIsMouseDown(true);
    const onMouseUp = () => setIsMouseDown(false);
    const onMouseLeave = () => setIsHidden(true);
    const onMouseEnter = () => setIsHidden(false);

    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mousedown', onMouseDown);
    document.addEventListener('mouseup', onMouseUp);
    document.addEventListener('mouseenter', onMouseEnter);
    document.addEventListener('mouseleave', onMouseLeave);

    return () => {
      document.removeEventListener('mousemove', onMouseMove);
      document.removeEventListener('mousedown', onMouseDown);
      document.removeEventListener('mouseup', onMouseUp);
      document.removeEventListener('mouseenter', onMouseEnter);
      document.removeEventListener('mouseleave', onMouseLeave);
    };
  }, []);

  return (
    <>
      {/* Main Ring */}
      <div 
        ref={cursorRef}
        className={`custom-cursor fixed top-0 left-0 w-10 h-10 border-2 border-black rounded-full pointer-events-none z-[9999] transition-all duration-300 ease-out mix-blend-difference -ml-5 -mt-5 ${isHidden ? 'opacity-0' : 'opacity-100'} ${isPointer ? 'scale-150 border-citrus bg-citrus/10' : 'scale-100'} ${isMouseDown ? 'scale-90' : ''}`}
        style={{ willChange: 'transform' }}
      />
      {/* Center Dot */}
      <div 
        ref={dotRef}
        className={`custom-cursor fixed top-0 left-0 w-1.5 h-1.5 bg-coral rounded-full pointer-events-none z-[10000] -ml-[3px] -mt-[3px] transition-opacity duration-300 ${isHidden ? 'opacity-0' : 'opacity-100'}`}
        style={{ willChange: 'transform' }}
      />
    </>
  );
};

export default CustomCursor;

