import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Problem, UserRole, Solution, Review, SiteConfig, Payment, Badge } from '../types.ts';
import { auth, db } from '../services/firebase.ts';
import { supabase } from '../services/supabase.ts';

interface AppContextType {
  user: User | null;
  loading: boolean;
  allUsers: User[];
  problems: Problem[];
  payments: Payment[];
  siteConfig: SiteConfig;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string, role: UserRole, name: string, extraInfo: string) => Promise<void>;
  logout: () => void;
  resetPassword: (email: string) => Promise<void>;
  addProblem: (data: Partial<Problem>) => Promise<void>;
  editProblem: (problemId: string, data: Partial<Problem>) => Promise<void>;
  manualCloseProblem: (problemId: string) => Promise<void>;
  addSolution: (problemId: string, content: string, file?: File) => Promise<void>;
  acceptSolution: (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, paymentMethod: string) => Promise<void>;
  verifySimulationSolution: (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string) => Promise<void>;
  updateUserProfile: (data: Partial<User>) => Promise<void>;
  adminBanUser: (userId: string, currentStatus: boolean) => Promise<void>;
  adminDeleteUser: (userId: string) => Promise<void>;
  adminDeleteProblem: (problemId: string) => Promise<void>;
  updateSiteConfig: (newConfig: Partial<SiteConfig>) => Promise<void>;
  fetchSingleUser: (userId: string) => Promise<User | null>;
  fetchUserByUsername: (username: string) => Promise<User | null>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const BADGE_RULES = [
    { id: 'first_fix', name: 'First Fix', threshold: 1, icon: '🎯', description: 'Solved your first practice simulation.' },
    { id: 'debugger', name: 'Debugger', threshold: 5, icon: '🐛', description: 'Crushed 5 technical simulations.' },
    { id: 'pro_solver', name: 'Pro Solver', threshold: 20, icon: '🔥', description: '20 simulations verified. Industry-ready.' }
];

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [problems, setProblems] = useState<Problem[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [siteConfig, setSiteConfig] = useState<SiteConfig>({ baseFontSize: 16, enableDarkMode: true });

  const solutionUnsubscribes = useRef<Record<string, () => void>>({});

  // Global Settings Listener
  useEffect(() => {
    const docRef = db.collection("settings").doc("global");
    const unsub = docRef.onSnapshot((docSnap) => {
        if (docSnap.exists) setSiteConfig((docSnap as any).data() as SiteConfig);
    }, (error) => { 
        console.warn("Global settings access restricted:", error.message); 
    });
    return () => unsub();
  }, []);

  // Authentication State Listener
  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (firebaseUser) => {
      if (firebaseUser && firebaseUser.emailVerified) {
        try {
          const docRef = db.collection("users").doc(firebaseUser.uid);
          const docSnap = await docRef.get();
          if (docSnap.exists) {
            const userData = { id: firebaseUser.uid, ...(docSnap as any).data() } as User;
            if (!userData.isBanned) setUser(userData);
            else await auth.signOut();
          }
        } catch (error) { 
          console.error("User document fetch failed:", error);
          setUser(null); 
        }
      } else { 
        setUser(null); 
      }
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // All Users Listener - Gated by Authentication and Role
  useEffect(() => {
    // We only attempt to listen to the full users collection if authenticated.
    // In a strict production environment, only Admins/Mentors would have this permission.
    if (!user) {
      setAllUsers([]);
      return;
    }

    const unsub = db.collection("users").onSnapshot((snapshot: any) => {
        const usersList = snapshot.docs.map((doc: any) => ({ id: doc.id, ...doc.data() } as User));
        setAllUsers(usersList);
    }, (error) => {
        console.warn("Full user list sync restricted:", error.message);
        // Fallback: maybe just keep current user in the list for UI consistency
        setAllUsers(user ? [user] : []);
    });
    return () => unsub();
  }, [user]);

  // Problems and Solutions Listener - Gated by Authentication
  useEffect(() => {
    // Only listen if user is authenticated to match likely Firestore security rules
    if (!user) {
      setProblems([]);
      return;
    }

    const unsub = db.collection("problems").orderBy("createdAt", "desc").onSnapshot((snapshot) => {
        const problemsData = snapshot.docs.map(doc => ({ id: doc.id, ...(doc as any).data(), solutions: [] })) as Problem[];
        setProblems(problemsData);

        // Setup sub-listeners for solutions
        problemsData.forEach(p => {
          if (!solutionUnsubscribes.current[p.id]) {
            solutionUnsubscribes.current[p.id] = db.collection("problems").doc(p.id).collection("solutions").onSnapshot((s) => {
                setProblems(current => current.map(cp => cp.id === p.id ? { ...cp, solutions: s.docs.map(sd => ({ id: sd.id, ...(sd as any).data() } as Solution)) } : cp));
            }, (err) => {
                console.warn(`Solutions listener restricted for problem ${p.id}:`, err.message);
            });
          }
        });
      }, (error) => {
        console.warn("Problems sync restricted:", error.message);
      });

    return () => {
      unsub();
      Object.values(solutionUnsubscribes.current).forEach((un: any) => un());
      solutionUnsubscribes.current = {};
    };
  }, [user]);

  const fetchSingleUser = async (userId: string) => {
    try {
      const doc = await db.collection("users").doc(userId).get();
      return doc.exists ? { id: doc.id, ...doc.data() } as User : null;
    } catch (e) {
      console.error("fetchSingleUser permission error:", e);
      return null;
    }
  };

  const fetchUserByUsername = async (username: string) => {
    try {
      const snap = await db.collection("users").where("username", "==", username).limit(1).get();
      return !snap.empty ? { id: snap.docs[0].id, ...snap.docs[0].data() } as User : null;
    } catch (e) {
      console.error("fetchUserByUsername permission error:", e);
      return null;
    }
  };

  const login = async (email: string, password: string) => {
    await auth.signInWithEmailAndPassword(email, password);
  };

  const register = async (email: string, password: string, role: UserRole, name: string, extraInfo: string) => {
    const userCredential = await auth.createUserWithEmailAndPassword(email, password);
    const uid = userCredential.user!.uid;
    const username = name.toLowerCase().replace(/\s+/g, '_') + '_' + Math.floor(Math.random() * 1000);
    const newUser: Partial<User> = { 
      id: uid, username, email, name, role, 
      university: role === UserRole.STUDENT ? extraInfo : undefined, 
      companyName: role === UserRole.COMPANY ? extraInfo : undefined, 
      rating: 0, solvedCount: 0, simSolvedCount: 0, 
      badges: [], reviews: [], joinedAt: new Date().toISOString(),
      bio: '', skills: [] 
    };
    await db.collection("users").doc(uid).set(newUser);
    await userCredential.user!.sendEmailVerification();
    await auth.signOut();
  };

  const logout = async () => {
    setUser(null);
    setAllUsers([]);
    setProblems([]);
    await auth.signOut();
  };

  const resetPassword = (email: string) => auth.sendPasswordResetEmail(email);

  const addProblem = async (data: Partial<Problem>) => {
    if (!user) return;
    await db.collection("problems").add({ 
        ...data, 
        companyId: user.id, 
        companyName: user.companyName || user.name, 
        status: 'OPEN', 
        createdAt: new Date().toISOString() 
    });
  };

  const verifySimulationSolution = async (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string) => {
    if (!user || (user.role !== UserRole.MENTOR && user.role !== UserRole.ADMIN)) return;

    await db.runTransaction(async (transaction) => {
      const studentRef = db.collection("users").doc(studentId);
      const solRef = db.collection("problems").doc(problemId).collection("solutions").doc(solutionId);

      const studentSnap = await transaction.get(studentRef);
      const studentData = studentSnap.data() as User;

      transaction.update(solRef, { 
        isVerified: true, 
        rating, 
        feedback, 
        mentorId: user.id, 
        mentorName: user.name 
      });

      const newSimCount = (studentData.simSolvedCount || 0) + 1;
      const currentReviews = studentData.reviews?.length || 0;
      const currentRating = studentData.rating || 0;
      const newRating = Number(((currentRating * currentReviews + rating) / (currentReviews + 1)).toFixed(1));

      const earnedBadges = studentData.badges || [];
      const newBadges: Badge[] = [];
      BADGE_RULES.forEach(rule => {
          if (newSimCount >= rule.threshold && !earnedBadges.find(b => b.id === rule.id)) {
              newBadges.push({ ...rule, awardedAt: new Date().toISOString() });
          }
      });

      transaction.update(studentRef, {
          simSolvedCount: newSimCount,
          rating: newRating,
          badges: [...earnedBadges, ...newBadges],
          reviews: [...(studentData.reviews || []), {
              id: solutionId,
              problemTitle: 'Simulation Exercise',
              rating,
              feedback,
              createdAt: new Date().toISOString(),
              companyName: `Mentor: ${user.name}`
          }]
      });
    });
  };

  const addSolution = async (problemId: string, content: string, file?: File) => {
    if (!user) return;
    let attachmentUrl = null, attachmentName = null;
    if (file) {
      const path = `simulations/${problemId}/${user.id}/${Date.now()}_${file.name}`;
      await supabase.storage.from('solutions').upload(path, file);
      attachmentUrl = supabase.storage.from('solutions').getPublicUrl(path).data.publicUrl;
      attachmentName = file.name;
    }
    await db.collection("problems").doc(problemId).collection("solutions").add({ 
        problemId, studentId: user.id, studentName: user.name, 
        content, submittedAt: new Date().toISOString(), 
        isAccepted: false, isVerified: false, 
        attachmentUrl, attachmentName 
    });
  };

  const acceptSolution = async (pId: string, sId: string, stId: string, r: number, f: string, pm: string) => {
      // Standard bounty logic remains unchanged or handled via cloud functions usually
  };

  const updateUserProfile = async (data: Partial<User>) => {
    if (!user) return;
    await db.collection("users").doc(user.id).update(data);
    setUser(prev => prev ? { ...prev, ...data } : null);
  };

  const adminBanUser = async (id: string, s: boolean) => { await db.collection("users").doc(id).update({ isBanned: !s }); };
  const adminDeleteUser = async (id: string) => { await db.collection("users").doc(id).delete(); };
  const adminDeleteProblem = async (id: string) => { await db.collection("problems").doc(id).delete(); };
  const updateSiteConfig = async (c: Partial<SiteConfig>) => { await db.collection("settings").doc("global").set(c, { merge: true }); };
  const editProblem = async (id: string, d: any) => { await db.collection("problems").doc(id).update(d); };
  const manualCloseProblem = async (id: string) => { await db.collection("problems").doc(id).update({ status: 'CLOSED' }); };

  return (
    <AppContext.Provider value={{ user, loading, allUsers, problems, payments, siteConfig, login, register, logout, resetPassword, addProblem, addSolution, acceptSolution, verifySimulationSolution, editProblem, manualCloseProblem, updateUserProfile, adminBanUser, adminDeleteUser, adminDeleteProblem, updateSiteConfig, fetchSingleUser, fetchUserByUsername }}>
      {children}
    </AppContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useStore error");
  return context;
};

