                                                        <SearchCheck className="w-3 h-3" />
                                                        <span className="text-[10px] font-black">{plag?.similarityPercentage.toFixed(0)}% Match</span>
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                        <button 
