                <h3 className="text-3xl font-black mb-10 flex items-center tracking-tighter"><Settings className="w-8 h-8 mr-4 text-coral" /> Global Protocols 👀</h3>

                <div className="space-y-12">
                    <div>
                        <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] mb-4">Grid Scale (Base Font)</label>
                        <div className="flex items-center space-x-6">
                            <span className="text-[10px] font-black uppercase">Alpha</span>
                            <input 
                                type="range" 
                                min="12" max="20" step="1"
                                value={siteConfig.baseFontSize}
                                onChange={(e) => updateSiteConfig({ baseFontSize: parseInt(e.target.value) })}
                                className="flex-1 h-3 bg-gray-100 rounded-lg appearance-none cursor-pointer accent-black border-2 border-black"
                            />
                            <span className="text-[10px] font-black uppercase">Omega</span>
                            <span className="w-16 text-center font-black text-xl border-2 border-black rounded-xl p-2 bg-citrus">{siteConfig.baseFontSize}px</span>
                        </div>
                    </div>

                    <div className="tactile-card flex items-center justify-between p-8 bg-paper rounded-3xl border-2 border-black">
                        <div>
                            <span className="block font-black text-lg text-black uppercase tracking-tighter">Night Ops Mode 🪄</span>
                            <span className="text-xs font-bold text-gray-400">Force high-contrast cyber theme globally. 😁</span>
                        </div>
                        <div className="relative inline-block w-14 h-8 select-none transition duration-200 ease-in">
                            <input 
                                type="checkbox" 
                                checked={siteConfig.enableDarkMode} 
                                onChange={(e) => updateSiteConfig({ enableDarkMode: e.target.checked })}
                                className="absolute block w-8 h-8 rounded-xl bg-white border-4 appearance-none cursor-pointer transition-transform duration-200 ease-in-out border-black"
                                style={{ transform: siteConfig.enableDarkMode ? 'translateX(75%)' : 'translateX(0)' }}
                            />
                            <label className={`block overflow-hidden h-8 rounded-xl cursor-pointer border-2 border-black ${siteConfig.enableDarkMode ? 'bg-citrus' : 'bg-gray-200'}`}></label>
                        </div>
                    </div>
                </div>
            </div>
        )}
      </div>

      {/* Post/Edit Simulation Modal */}
      <Modal isOpen={isPostModalOpen} onClose={() => setIsPostModalOpen(false)} title={editingId ? "Reconfigure Simulation" : "Deploy Practice Simulation"}>
          <form onSubmit={handlePostOrUpdateSimulation} className="space-y-6 max-h-[70vh] overflow-y-auto px-1 custom-scrollbar">
                <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><Terminal className="w-3 h-3"/> Simulation Title</label>
                    <input required className="w-full border-2 border-black p-4 rounded-xl font-black bg-paper outline-none focus:bg-citrus/5 transition-all" placeholder="Broken React Component Hook" value={title} onChange={e => setTitle(e.target.value)} />
                </div>

                <div className="space-y-2">
                    <div className="flex justify-between items-center mb-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><Info className="w-3 h-3"/> Technical Brief</label>
                        <button 
                            type="button" 
                            onClick={handleRefine}
                            disabled={isRefining || !desc.trim()}
                            className="flex items-center gap-1.5 px-3 py-1 bg-black text-white rounded-lg text-[9px] font-black uppercase tracking-widest hover:bg-forest disabled:opacity-40 transition-all border border-citrus/30"
                        >
                            {isRefining ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />} AI Refine
                        </button>
                    </div>
                    <textarea required className="w-full border-2 border-black p-4 rounded-xl h-24 font-bold bg-paper outline-none text-sm focus:bg-citrus/5 transition-all" placeholder="Describe the simulation scenario..." value={desc} onChange={e => setDesc(e.target.value)} />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><CheckCircle2 className="w-3 h-3"/> Target Outcome</label>
                        <textarea className="w-full border-2 border-black p-4 rounded-xl h-24 font-bold bg-paper outline-none text-sm focus:bg-citrus/5 transition-all" placeholder="What is the expected fix?" value={expectedBehavior} onChange={e => setExpectedBehavior(e.target.value)} />
                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><AlertTriangle className="w-3 h-3"/> Current Error/Bug</label>
                        <textarea className="w-full border-2 border-black p-4 rounded-xl h-24 font-bold bg-paper outline-none text-sm focus:bg-citrus/5 transition-all" placeholder="What is currently failing?" value={currentBehavior} onChange={e => setCurrentBehavior(e.target.value)} />
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><Activity className="w-3 h-3"/> Tier Level</label>
                        <select 
                            className="w-full border-2 border-black p-4 rounded-xl font-black bg-paper outline-none focus:bg-citrus/5 transition-all appearance-none" 
                            value={difficulty} 
                            onChange={e => setDifficulty(e.target.value as any)}
                        >
                            <option value="EASY">EASY PROTOCOL</option>
                            <option value="MEDIUM">MEDIUM PROTOCOL</option>
                            <option value="HARD">HARD PROTOCOL</option>
                        </select>
                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><Tag className="w-3 h-3"/> Metadata Tags</label>
                        <input className="w-full border-2 border-black p-4 rounded-xl font-bold bg-paper outline-none focus:bg-citrus/5 transition-all" placeholder="React, Vite, Bug..." value={tags} onChange={e => setTags(e.target.value)} />
                    </div>
                </div>

                <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><Cpu className="w-3 h-3"/> System Stack</label>
                    <input className="w-full border-2 border-black p-4 rounded-xl font-bold bg-paper outline-none focus:bg-citrus/5 transition-all" placeholder="TypeScript, Node.js..." value={techStack} onChange={e => setTechStack(e.target.value)} />
                </div>

                <button 
                    type="submit" 
                    disabled={!!processingId}
                    className="tactile-btn w-full bg-black text-white py-5 rounded-2xl font-black text-xl uppercase tracking-widest mt-4 flex items-center justify-center gap-4"
                >
                    {processingId === 'POSTING' ? <Loader2 className="w-6 h-6 animate-spin" /> : <><Plus className="w-6 h-6" /> {editingId ? 'Sync Updates' : 'Deploy Simulation'}</>}
                </button>
          </form>
      </Modal>

      {/* Simulation Review Modal */}
      <Modal isOpen={!!reviewingItem} onClose={() => setReviewingItem(null)} title="Technical Validation">
          {reviewingItem && (
            <div className="space-y-8">
                <div className="p-6 bg-paper border-2 border-black rounded-3xl">
                    <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest block mb-1">Subject Node</label>
                    <h4 className="text-xl font-black leading-tight mb-4">{reviewingItem.problem.title}</h4>
                    <div className="p-4 bg-white border-2 border-black rounded-2xl font-mono text-xs whitespace-pre-wrap max-h-48 overflow-y-auto">
                        {reviewingItem.solution.content}
                    </div>
                </div>

                <div className="flex flex-col items-center">
                    <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-4">Competency Rank</label>
                    <StarRatingInput rating={auditRating} setRating={setAuditRating} />
                </div>

                <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest block px-1">Audit Feedback</label>
                    <textarea 
                        className="w-full border-2 border-black p-5 rounded-2xl h-32 font-bold bg-paper outline-none focus:bg-citrus/5 transition-all text-sm" 
                        placeholder="Log technical corrections or praise..." 
                        value={auditFeedback} 
                        onChange={e => setAuditFeedback(e.target.value)} 
                    />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <button 
                      onClick={() => handleAuditAction('REJECTED')}
                      disabled={isAuditing || !auditFeedback.trim()}
                      className="tactile-btn bg-coral text-white py-5 rounded-2xl font-black text-sm uppercase tracking-widest flex items-center justify-center gap-3 disabled:opacity-50"
                  >
                      {isAuditing ? <Loader2 className="w-5 h-5 animate-spin" /> : <><XCircle className="w-5 h-5" /> Reject</>}
                  </button>
                  <button 
                      onClick={() => handleAuditAction('VERIFIED')}
                      disabled={isAuditing || !auditFeedback.trim()}
                      className="tactile-btn bg-forest text-white py-5 rounded-2xl font-black text-sm uppercase tracking-widest flex items-center justify-center gap-3 disabled:opacity-50"
                  >
                      {isAuditing ? <Loader2 className="w-5 h-5 animate-spin" /> : <><CheckCircle2 className="w-5 h-5" /> Verify</>}
                  </button>
                </div>
            </div>
          )}
      </Modal>

      <ProblemDetailModal 
          isOpen={showProblemDetailModal}
          onClose={() => setShowProblemDetailModal(false)}
          problem={currentProblemForDetails}
          onProfileClick={onProfileClick}
      />
    </div>
  );
};

export default AdminPortal;

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Problem, UserRole, Solution, Review, SiteConfig, Payment, Badge, SkillLevel } from '../types.ts';
import { auth, db } from '../services/firebase.ts';
import { supabase } from '../services/supabase.ts';
import { evaluateSolutionWithAI } from '../services/geminiService.ts';

interface AppContextType {
  user: User | null;
  loading: boolean;
  allUsers: User[];
  problems: Problem[];
  payments: Payment[];
  siteConfig: SiteConfig;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string, role: UserRole, name: string, extraInfo: string) => Promise<void>;
  logout: () => void;
  resetPassword: (email: string) => Promise<void>;
  addProblem: (data: Partial<Problem>) => Promise<void>;
  editProblem: (problemId: string, data: Partial<Problem>) => Promise<void>;
  manualCloseProblem: (problemId: string) => Promise<void>;
  addSolution: (problemId: string, content: string, file?: File) => Promise<void>;
  acceptSolution: (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, paymentMethod: string) => Promise<void>;
  verifySimulationSolution: (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, status: 'VERIFIED' | 'REJECTED') => Promise<void>;
  updateUserProfile: (data: Partial<User>) => Promise<void>;
  adminBanUser: (userId: string, currentStatus: boolean) => Promise<void>;
  adminVerifyUser: (userId: string) => Promise<void>;
  adminDeleteUser: (userId: string) => Promise<void>;
  adminDeleteProblem: (problemId: string) => Promise<void>;
  updateSiteConfig: (newConfig: Partial<SiteConfig>) => Promise<void>;
  fetchSingleUser: (userId: string) => Promise<User | null>;
  fetchUserByUsername: (username: string) => Promise<User | null>;
  clearAuditNotification: () => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const calculateSkillLevel = (avg: number): SkillLevel => {
  if (avg >= 90) return 'Advanced';
  if (avg >= 75) return 'Intermediate';
  if (avg >= 60) return 'Junior';
  return 'Beginner';
};

const BADGE_RULES: Badge[] = [
    { id: 'first_fix', name: 'First Fix', threshold: 1, icon: '🎯', description: 'Solved your first practice simulation.', bonusPoints: 10, awardedAt: '' } as any,
    { id: 'debugger', name: 'Debugger', threshold: 5, icon: '🐛', description: 'Crushed 5 technical simulations.', bonusPoints: 50, awardedAt: '' } as any,
    { id: 'pro_solver', name: 'Pro Solver', threshold: 20, icon: '🔥', description: '20 simulations verified.', bonusPoints: 200, awardedAt: '' } as any
];

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [problems, setProblems] = useState<Problem[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [siteConfig, setSiteConfig] = useState<SiteConfig>({ baseFontSize: 16, enableDarkMode: true });

  const solutionUnsubscribes = useRef<Record<string, () => void>>({});

  const detectPlagiarism = (content: string, problemId: string): { similarity: number, status: 'CLEAN' | 'FLAGGED' | 'PENALIZED' } => {
    const currentProblem = problems.find(p => p.id === problemId);
    if (!currentProblem || !currentProblem.solutions) return { similarity: 0, status: 'CLEAN' };

    let maxSim = 0;
    currentProblem.solutions.forEach(s => {
      const common = s.content.split('').filter((c, i) => content[i] === c).length;
      const sim = (common / Math.max(content.length, s.content.length)) * 100;
      if (sim > maxSim) maxSim = sim;
    });

    if (maxSim > 90) return { similarity: maxSim, status: 'PENALIZED' };
    if (maxSim > 80) return { similarity: maxSim, status: 'FLAGGED' };
    return { similarity: maxSim, status: 'CLEAN' };
  };

  useEffect(() => {
    const unsub = db.collection("settings").doc("global").onSnapshot((doc) => {
        if (doc.exists) setSiteConfig(doc.data() as SiteConfig);
    }, (error) => {
        console.warn("Global settings access restricted:", error.message);
    });
    return () => unsub();
  }, []);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (firebaseUser) => {
      if (firebaseUser && firebaseUser.emailVerified) {
        const unsub = db.collection("users").doc(firebaseUser.uid).onSnapshot((snap) => {
          if (snap.exists) {
            const userData = { id: firebaseUser.uid, ...snap.data() } as User;
            if (!userData.isBanned) setUser(userData);
            else auth.signOut();
          }
        }, (error) => {
            console.error("User profile sync error:", error.message);
        });
        return () => unsub();
      } else { 
        setUser(null); 
      }
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const unsub = db.collection("users").onSnapshot((snapshot) => {
        const usersList = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() } as User));
        setAllUsers(usersList);
    }, (error) => {
        console.warn("Users list restricted for guest/role:", error.message);
        setAllUsers(user ? [user] : []);
    });
    return () => unsub();
  }, [user?.id]);

  useEffect(() => {
    const unsub = db.collection("problems").orderBy("createdAt", "desc").onSnapshot((snapshot) => {
        const problemsData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data(), solutions: [] })) as Problem[];
        setProblems(problemsData);

        if (auth.currentUser) {
          problemsData.forEach(p => {
            if (!solutionUnsubscribes.current[p.id]) {
              solutionUnsubscribes.current[p.id] = db.collection("problems").doc(p.id).collection("solutions").onSnapshot((s) => {
                  setProblems(current => current.map(cp => cp.id === p.id ? { ...cp, solutions: s.docs.map(sd => ({ id: sd.id, ...sd.data() } as Solution)) } : cp));
              }, (error) => {
                  // Silently handle nested solutions permissions
              });
            }
          });
        }
      }, (error) => {
          console.warn("Problems feed restricted:", error.message);
          setProblems([]);
      });

    return () => {
      unsub();
      Object.values(solutionUnsubscribes.current).forEach((un: any) => un());
      solutionUnsubscribes.current = {};
    };
  }, [user?.id]);

  const clearAuditNotification = async () => {
    if (!user) return;
    await db.collection("users").doc(user.id).update({ auditNotification: null });
  };

  const fetchSingleUser = async (userId: string) => {
    try {
        const doc = await db.collection("users").doc(userId).get();
        return doc.exists ? { id: doc.id, ...doc.data() } as User : null;
    } catch { return null; }
  };

  const fetchUserByUsername = async (username: string) => {
    try {
        const snap = await db.collection("users").where("username", "==", username).limit(1).get();
        return !snap.empty ? { id: snap.docs[0].id, ...snap.docs[0].data() } as User : null;
    } catch { return null; }
  };

  const login = async (email: string, password: string) => {
    await auth.signInWithEmailAndPassword(email, password);
  };

  const register = async (email: string, password: string, role: UserRole, name: string, extraInfo: string) => {
    const userCredential = await auth.createUserWithEmailAndPassword(email, password);
    const uid = userCredential.user!.uid;
    const username = name.toLowerCase().replace(/\s+/g, '_') + '_' + Math.floor(Math.random() * 1000);

    // Logic: Companies start unverified, others (Students/Mentors) start verified or subject to email verify
    const isVerifiedInitially = role !== UserRole.COMPANY;

    const newUser: any = { 
      id: uid, 
      username, 
      email, 
      name, 
      role, 
      rating: 0, 
      leaderboardScore: 0, 
      penaltyPoints: 0, 
      solvedCount: 0, 
      simSolvedCount: 0, 
      skillLevel: 'Beginner', 
      badges: [], 
      reviews: [], 
      joinedAt: new Date().toISOString(),
      bio: '', 
      skills: [],
      isVerified: isVerifiedInitially
    };

    // Only add these fields if they have a value to avoid 'undefined' errors in Firestore
    if (role === UserRole.STUDENT) {
      newUser.university = extraInfo || "";
    } else if (role === UserRole.COMPANY) {
      newUser.companyName = extraInfo || "";
    }

    await db.collection("users").doc(uid).set(newUser);
    await userCredential.user!.sendEmailVerification();
    await auth.signOut();
  };

  const logout = async () => {
    Object.values(solutionUnsubscribes.current).forEach((un: any) => un());
    solutionUnsubscribes.current = {};
    setUser(null);
    await auth.signOut();
  };

  const resetPassword = (email: string) => auth.sendPasswordResetEmail(email);

  const addProblem = async (data: Partial<Problem>) => {
    if (!user || !user.isVerified) return;
    await db.collection("problems").add({ 
        ...data, companyId: user.id, companyName: user.companyName || user.name, 
        status: 'OPEN', createdAt: new Date().toISOString() 
    });
  };

  const addSolution = async (problemId: string, content: string, file?: File) => {
    if (!user) return;
    const plag = detectPlagiarism(content, problemId);
    const prob = problems.find(p => p.id === problemId);
    const aiEval = await evaluateSolutionWithAI(prob?.description || "", content);

    let attachmentUrl = null;
    if (file) {
      const path = `solutions/${problemId}/${user.id}/${Date.now()}_${file.name}`;
      const { data: uploadData, error: uploadError } = await supabase.storage.from('solutions').upload(path, file);

      if (uploadError) {
          console.error("Supabase Storage Error:", uploadError);
          if (uploadError.message.includes("Bucket not found")) {
              throw new Error("Critical: 'solutions' bucket missing in Supabase. Check dashboard.");
          }
          throw uploadError;
      }

      attachmentUrl = supabase.storage.from('solutions').getPublicUrl(path).data.publicUrl;
    }

    await db.collection("problems").doc(problemId).collection("solutions").add({ 
        problemId, studentId: user.id, studentName: user.name, 
        content, submittedAt: new Date().toISOString(), 
        isAccepted: false, isVerified: false, isRejected: false,
        reviewStatus: 'PENDING',
        aiEvaluation: aiEval,
        plagiarismMetadata: plag,
        attachmentUrl 
    });
  };

  const verifySimulationSolution = async (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, status: 'VERIFIED' | 'REJECTED') => {
    if (!user || (user.role !== UserRole.MENTOR && user.role !== UserRole.ADMIN)) return;

    await db.runTransaction(async (transaction) => {
      const studentRef = db.collection("users").doc(studentId);
      const solRef = db.collection("problems").doc(problemId).collection("solutions").doc(solutionId);

      const studentSnap = await transaction.get(studentRef);
      const solSnap = await transaction.get(solRef);

      if (!studentSnap.exists || !solSnap.exists) {
          throw new Error("Target node or submission detached.");
      }

      const studentData = studentSnap.data() as User;
      const solData = solSnap.data() as Solution;
      const isVerified = status === 'VERIFIED';

      transaction.update(solRef, { 
        isVerified, 
        isRejected: !isVerified, 
        reviewStatus: status,
        rating, 
        feedback, 
        mentorId: user.id, 
        mentorName: user.name 
      });

      if (isVerified) {
        const verifiedSims = (studentData.simSolvedCount || 0) + 1;
        const pastScores = (studentData.reviews || []).map(r => r.rating).slice(-4);
        const allScores = [...pastScores, rating];
        const rollingAvg = Math.round(allScores.reduce((a,b) => a + b, 0) / allScores.length);

        let bonusPoints = 0;
        const earnedBadges = studentData.badges || [];
        const newBadges: Badge[] = [];
        BADGE_RULES.forEach(rule => {
            if (verifiedSims >= (rule as any).threshold && !earnedBadges.find(b => b.id === rule.id)) {
                const b = { ...rule, awardedAt: new Date().toISOString() };
                newBadges.push(b);
                bonusPoints += b.bonusPoints;
            }
        });

        const plag = solData.plagiarismMetadata;
        let penaltyInc = 0;
        if (plag?.status === 'PENALIZED') penaltyInc = 100;
        else if (plag?.status === 'FLAGGED') penaltyInc = 25;

        const finalScore = (verifiedSims * 10) + (rollingAvg * 2) + bonusPoints - ((studentData.penaltyPoints || 0) + penaltyInc);

        transaction.update(studentRef, {
            simSolvedCount: verifiedSims,
            rollingAverage: rollingAvg,
            skillLevel: calculateSkillLevel(rollingAvg),
            penaltyPoints: (studentData.penaltyPoints || 0) + penaltyInc,
            leaderboardScore: finalScore,
            badges: [...earnedBadges, ...newBadges],
            reviews: [...(studentData.reviews || []), {
                id: solutionId, problemTitle: 'Simulation Exercise',
                rating, feedback, createdAt: new Date().toISOString(),
                companyName: `Mentor: ${user.name}`
            }],
            auditNotification: { 
                problemId, 
                problemTitle: 'Simulation Verified', 
                status: 'VERIFIED', 
                feedback, 
                read: false 
            }
        });
      } else {
        transaction.update(studentRef, {
            auditNotification: { 
                problemId, 
                problemTitle: 'Simulation Review', 
                status: 'REJECTED', 
                feedback, 
                read: false 
            }
        });
      }
    });
  };

  const acceptSolution = async (pId: string, sId: string, stId: string, r: number, f: string) => {
      if (!user) return;
      await db.runTransaction(async (transaction) => {
          const studentRef = db.collection("users").doc(stId);
          const solRef = db.collection("problems").doc(pId).collection("solutions").doc(sId);
          const studentSnap = await transaction.get(studentRef);

          transaction.update(solRef, { isAccepted: true, rating: r, feedback: f });
          transaction.update(db.collection("problems").doc(pId), { status: 'CLOSED' });

          if (studentSnap.exists) {
            const data = studentSnap.data() as User;
            transaction.update(studentRef, { solvedCount: (data.solvedCount || 0) + 1 });
          }
      });
  };

  const updateUserProfile = async (data: Partial<User>) => {
    if (!user) return;
    await db.collection("users").doc(user.id).update(data);
  };

  const adminBanUser = async (id: string, s: boolean) => { await db.collection("users").doc(id).update({ isBanned: !s }); };
  const adminVerifyUser = async (id: string) => { await db.collection("users").doc(id).update({ isVerified: true }); };
  const adminDeleteUser = async (id: string) => { await db.collection("users").doc(id).delete(); };
  const adminDeleteProblem = async (id: string) => { await db.collection("problems").doc(id).delete(); };
  const updateSiteConfig = async (c: Partial<SiteConfig>) => { await db.collection("settings").doc("global").set(c, { merge: true }); };
  const editProblem = async (id: string, d: any) => { await db.collection("problems").doc(id).update(d); };
  const manualCloseProblem = async (id: string) => { await db.collection("problems").doc(id).update({ status: 'CLOSED' }); };

  return (
    <AppContext.Provider value={{ user, loading, allUsers, problems, payments, siteConfig, login, register, logout, resetPassword, addProblem, addSolution, acceptSolution, verifySimulationSolution, editProblem, manualCloseProblem, updateUserProfile, adminBanUser, adminVerifyUser, adminDeleteUser, adminDeleteProblem, updateSiteConfig, fetchSingleUser, fetchUserByUsername, clearAuditNotification }}>
      {children}
    </AppContext.Provider>
  );
};

