      setReviewingItem(null);
      setAuditFeedback('');
      setAuditRating(5);
    } catch (error: any) {
      console.error("Verification Error Details:", error);
      alert(`Verification protocol failure: ${error.message || 'Check browser console for RPC details.'}`);
