  const processBulkUpload = async () => {
    if (!bulkFile) return;
    setBulkStatus('parsing');

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const json = XLSX.utils.sheet_to_json(worksheet) as any[];

        if (json.length === 0) throw new Error("Spreadsheet node is empty.");

        // Transform and validate
        const problemsData: Partial<Problem>[] = json.map(item => ({
          title: String(item.title || item.Title || "Untitled Simulation"),
          description: String(item.description || item.Description || ""),
          expectedBehavior: String(item.expectedBehavior || item['Expected Behavior'] || ""),
          currentBehavior: String(item.currentBehavior || item['Current Behavior'] || ""),
