export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [problems, setProblems] = useState<Problem[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [siteConfig, setSiteConfig] = useState<SiteConfig>({ baseFontSize: 16, enableDarkMode: true });

  const solutionUnsubscribes = useRef<Record<string, () => void>>({});

  const detectPlagiarism = (content: string, problemId: string): { similarity: number, status: 'CLEAN' | 'FLAGGED' | 'PENALIZED' } => {
    const currentProblem = problems.find(p => p.id === problemId);
    if (!currentProblem || !currentProblem.solutions) return { similarity: 0, status: 'CLEAN' };

    let maxSim = 0;
    currentProblem.solutions.forEach(s => {
      const common = s.content.split('').filter((c, i) => content[i] === c).length;
      const sim = (common / Math.max(content.length, s.content.length)) * 100;
      if (sim > maxSim) maxSim = sim;
    });

    if (maxSim > 90) return { similarity: maxSim, status: 'PENALIZED' };
    if (maxSim > 80) return { similarity: maxSim, status: 'FLAGGED' };
    return { similarity: maxSim, status: 'CLEAN' };
  };

  useEffect(() => {
    const unsub = db.collection("settings").doc("global").onSnapshot((doc) => {
        if (doc.exists) setSiteConfig(doc.data() as SiteConfig);
    }, (error) => {
        console.warn("Global settings access restricted:", error.message);
    });
    return () => unsub();
  }, []);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (firebaseUser) => {
      if (firebaseUser && firebaseUser.emailVerified) {
        const unsub = db.collection("users").doc(firebaseUser.uid).onSnapshot((snap) => {
          if (snap.exists) {
            const userData = { id: firebaseUser.uid, ...snap.data() } as User;
            if (!userData.isBanned) setUser(userData);
            else auth.signOut();
          }
        }, (error) => {
            console.error("User profile sync error:", error.message);
        });
        return () => unsub();
      } else { 
        setUser(null); 
      }
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const unsub = db.collection("users").onSnapshot((snapshot) => {
        const usersList = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() } as User));
        setAllUsers(usersList);
    }, (error) => {
        console.warn("Users list restricted for guest/role:", error.message);
        setAllUsers(user ? [user] : []);
    });
    return () => unsub();
  }, [user?.id]);

  useEffect(() => {
    const unsub = db.collection("problems").orderBy("createdAt", "desc").onSnapshot((snapshot) => {
        const problemsData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data(), solutions: [] })) as Problem[];
        setProblems(problemsData);

        if (auth.currentUser) {
          problemsData.forEach(p => {
            if (!solutionUnsubscribes.current[p.id]) {
              solutionUnsubscribes.current[p.id] = db.collection("problems").doc(p.id).collection("solutions").onSnapshot((s) => {
                  setProblems(current => current.map(cp => cp.id === p.id ? { ...cp, solutions: s.docs.map(sd => ({ id: sd.id, ...sd.data() } as Solution)) } : cp));
              }, (error) => {
                  // Silently handle nested solutions permissions
              });
            }
          });
        }
      }, (error) => {
          console.warn("Problems feed restricted:", error.message);
          setProblems([]);
      });

    return () => {
      unsub();
      Object.values(solutionUnsubscribes.current).forEach((un: any) => un());
      solutionUnsubscribes.current = {};
    };
  }, [user?.id]);

  const clearAuditNotification = async () => {
    if (!user) return;
    await db.collection("users").doc(user.id).update({ auditNotification: null });
  };

  const fetchSingleUser = async (userId: string) => {
    try {
        const doc = await db.collection("users").doc(userId).get();
        return doc.exists ? { id: doc.id, ...doc.data() } as User : null;
    } catch { return null; }
  };

  const fetchUserByUsername = async (username: string) => {
    try {
        const snap = await db.collection("users").where("username", "==", username).limit(1).get();
        return !snap.empty ? { id: snap.docs[0].id, ...snap.docs[0].data() } as User : null;
    } catch { return null; }
  };

  const login = async (email: string, password: string) => {
    await auth.signInWithEmailAndPassword(email, password);
  };

  const register = async (email: string, password: string, role: UserRole, name: string, extraInfo: string) => {
    const userCredential = await auth.createUserWithEmailAndPassword(email, password);
    const uid = userCredential.user!.uid;
    const username = name.toLowerCase().replace(/\s+/g, '_') + '_' + Math.floor(Math.random() * 1000);

    // Logic: Companies start unverified, others (Students/Mentors) start verified or subject to email verify
    const isVerifiedInitially = role !== UserRole.COMPANY;

    const newUser: any = { 
      id: uid, 
      username, 
      email, 
      name, 
      role, 
      rating: 0, 
      leaderboardScore: 0, 
      penaltyPoints: 0, 
      solvedCount: 0, 
      simSolvedCount: 0, 
      skillLevel: 'Beginner', 
      badges: [], 
      reviews: [], 
      joinedAt: new Date().toISOString(),
      bio: '', 
      skills: [],
      isVerified: isVerifiedInitially
    };

    // Only add these fields if they have a value to avoid 'undefined' errors in Firestore
    if (role === UserRole.STUDENT) {
      newUser.university = extraInfo || "";
    } else if (role === UserRole.COMPANY) {
      newUser.companyName = extraInfo || "";
    }

    await db.collection("users").doc(uid).set(newUser);
    await userCredential.user!.sendEmailVerification();
    await auth.signOut();
  };

  const logout = async () => {
    Object.values(solutionUnsubscribes.current).forEach((un: any) => un());
    solutionUnsubscribes.current = {};
    setUser(null);
    await auth.signOut();
  };

  const resetPassword = (email: string) => auth.sendPasswordResetEmail(email);

  const addProblem = async (data: Partial<Problem>) => {
    if (!user || !user.isVerified) return;
    await db.collection("problems").add({ 
        ...data, companyId: user.id, companyName: user.companyName || user.name, 
        status: 'OPEN', createdAt: new Date().toISOString() 
    });
  };

  const bulkAddProblems = async (problemsData: Partial<Problem>[]) => {
    if (!user || user.role !== UserRole.ADMIN) return;

    const batch = db.batch();
    const problemsCol = db.collection("problems");

    problemsData.forEach((data) => {
        const newDocRef = problemsCol.doc();
        batch.set(newDocRef, {
            ...data,
            companyId: user.id,
            companyName: data.companyName || 'Simulation Hub',
            status: 'OPEN',
            createdAt: new Date().toISOString(),
            isSimulation: data.isSimulation ?? true
        });
    });

    await batch.commit();
  };

  const addSolution = async (problemId: string, content: string, file?: File, details?: { githubLink?: string, techStack?: string, limitations?: string }) => {
    if (!user) return;
    const plag = detectPlagiarism(content, problemId);
    const prob = problems.find(p => p.id === problemId);
    const aiEval = await evaluateSolutionWithAI(prob?.description || "", content);

    let attachmentUrl = null;
    if (file) {
      const path = `solutions/${problemId}/${user.id}/${Date.now()}_${file.name}`;
      const { data: uploadData, error: uploadError } = await supabase.storage.from('solutions').upload(path, file);

      if (uploadError) {
          console.error("Supabase Storage Error:", uploadError);
          if (uploadError.message.includes("Bucket not found")) {
              throw new Error("Critical: 'solutions' bucket missing in Supabase. Check dashboard.");
          }
          throw uploadError;
      }

      attachmentUrl = supabase.storage.from('solutions').getPublicUrl(path).data.publicUrl;
    }

    await db.collection("problems").doc(problemId).collection("solutions").add({ 
        problemId, studentId: user.id, studentName: user.name, 
        content, 
        githubLink: details?.githubLink || "",
        techStack: details?.techStack || "",
        limitations: details?.limitations || "",
        submittedAt: new Date().toISOString(), 
        isAccepted: false, isVerified: false, isRejected: false,
        reviewStatus: 'PENDING',
        aiEvaluation: aiEval,
        plagiarismMetadata: plag,
        attachmentUrl 
    });
  };

  const verifySimulationSolution = async (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, status: 'VERIFIED' | 'REJECTED') => {
    if (!user || (user.role !== UserRole.MENTOR && user.role !== UserRole.ADMIN)) return;

    await db.runTransaction(async (transaction) => {
      const studentRef = db.collection("users").doc(studentId);
      const solRef = db.collection("problems").doc(problemId).collection("solutions").doc(solutionId);

      const studentSnap = await transaction.get(studentRef);
      const solSnap = await transaction.get(solRef);

      if (!studentSnap.exists || !solSnap.exists) {
          throw new Error("Target node or submission detached.");
      }

      const studentData = studentSnap.data() as User;
      const solData = solSnap.data() as Solution;
      const isVerified = status === 'VERIFIED';

      transaction.update(solRef, { 
        isVerified, 
        isRejected: !isVerified, 
        reviewStatus: status,
        rating, 
        feedback, 
        mentorId: user.id, 
        mentorName: user.name 
      });

      if (isVerified) {
        const verifiedSims = (studentData.simSolvedCount || 0) + 1;
        const pastScores = (studentData.reviews || []).map(r => r.rating).slice(-4);
        const allScores = [...pastScores, rating];
        const rollingAvg = Math.round(allScores.reduce((a,b) => a + b, 0) / allScores.length);

        let bonusPoints = 0;
        const earnedBadges = studentData.badges || [];
        const newBadges: Badge[] = [];
        BADGE_RULES.forEach(rule => {
            if (verifiedSims >= (rule as any).threshold && !earnedBadges.find(b => b.id === rule.id)) {
                const b = { ...rule, awardedAt: new Date().toISOString() };
                newBadges.push(b);
                bonusPoints += b.bonusPoints;
            }
        });

        const plag = solData.plagiarismMetadata;
        let penaltyInc = 0;
        if (plag?.status === 'PENALIZED') penaltyInc = 100;
        else if (plag?.status === 'FLAGGED') penaltyInc = 25;

        const finalScore = (verifiedSims * 10) + (rollingAvg * 2) + bonusPoints - ((studentData.penaltyPoints || 0) + penaltyInc);

        transaction.update(studentRef, {
            simSolvedCount: verifiedSims,
            rollingAverage: rollingAvg,
            skillLevel: calculateSkillLevel(rollingAvg),
            penaltyPoints: (studentData.penaltyPoints || 0) + penaltyInc,
            leaderboardScore: finalScore,
            badges: [...earnedBadges, ...newBadges],
            reviews: [...(studentData.reviews || []), {
                id: solutionId, problemTitle: 'Simulation Exercise',
                rating, feedback, createdAt: new Date().toISOString(),
                companyName: `Mentor: ${user.name}`
            }],
            auditNotification: { 
                problemId, 
                problemTitle: 'Simulation Verified', 
                status: 'VERIFIED', 
                feedback, 
                read: false 
            }
        });
      } else {
        transaction.update(studentRef, {
            auditNotification: { 
                problemId, 
                problemTitle: 'Simulation Review', 
                status: 'REJECTED', 
                feedback, 
                read: false 
            }
        });
      }
    });
  };

  const acceptSolution = async (pId: string, sId: string, stId: string, r: number, f: string) => {
      if (!user) return;
      await db.runTransaction(async (transaction) => {
          const studentRef = db.collection("users").doc(stId);
          const solRef = db.collection("problems").doc(pId).collection("solutions").doc(sId);
          const studentSnap = await transaction.get(studentRef);

          transaction.update(solRef, { isAccepted: true, rating: r, feedback: f });
          transaction.update(db.collection("problems").doc(pId), { status: 'CLOSED' });

          if (studentSnap.exists) {
            const data = studentSnap.data() as User;
            transaction.update(studentRef, { solvedCount: (data.solvedCount || 0) + 1 });
          }
      });
  };

  const updateUserProfile = async (data: Partial<User>) => {
    if (!user) return;
    await db.collection("users").doc(user.id).update(data);
  };

  const adminBanUser = async (id: string, s: boolean) => { await db.collection("users").doc(id).update({ isBanned: !s }); };
  const adminVerifyUser = async (id: string) => { await db.collection("users").doc(id).update({ isVerified: true }); };
  const adminDeleteUser = async (id: string) => { await db.collection("users").doc(id).delete(); };
  const adminDeleteProblem = async (id: string) => { await db.collection("problems").doc(id).delete(); };

  const bulkDeleteProblems = async (ids: string[]) => {
    if (!user || user.role !== UserRole.ADMIN) return;
    const batch = db.batch();
    ids.forEach(id => {
        batch.delete(db.collection("problems").doc(id));
    });
    await batch.commit();
  };

  const updateSiteConfig = async (c: Partial<SiteConfig>) => { await db.collection("settings").doc("global").set(c, { merge: true }); };
  const editProblem = async (id: string, d: any) => { await db.collection("problems").doc(id).update(d); };
  const manualCloseProblem = async (id: string) => { await db.collection("problems").doc(id).update({ status: 'CLOSED' }); };

  return (
    <AppContext.Provider value={{ user, loading, allUsers, problems, payments, siteConfig, login, register, logout, resetPassword, addProblem, bulkAddProblems, addSolution, acceptSolution, verifySimulationSolution, editProblem, manualCloseProblem, updateUserProfile, adminBanUser, adminVerifyUser, adminDeleteUser, adminDeleteProblem, bulkDeleteProblems, updateSiteConfig, fetchSingleUser, fetchUserByUsername, clearAuditNotification }}>
      {children}
    </AppContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useStore error");
  return context;
};

import React, { useState, useMemo, useRef } from 'react';
import { useStore } from '../context/Store.tsx';
import { UserRole, Problem, User, Solution } from '../types.ts';
import { 
  Users, CheckCircle2, Star, Trophy, Loader2, Shield, Activity, 
  Terminal, Cpu, IndianRupee, Settings, Trash2, Ban, Plus, 
  Briefcase, Layers, Info, Tag, Wand2, AlertTriangle, BarChart3, 
  BrainCircuit, Layout, Zap, Edit2, Eye, XCircle, Download, FileArchive, ArrowUpRight, ShieldCheck, UserCheck, FileSpreadsheet, X, HelpCircle,
  Square, CheckSquare, Trash
} from 'lucide-react';
import ProblemDetailModal from '../components/ProblemDetailModal.tsx';
import Modal from '../components/Modal.tsx';
import StarRatingInput from '../components/StarRatingInput.tsx';
import { refineProblemDescription } from '../services/geminiService.ts';
import * as XLSX from 'xlsx';

interface AdminPortalProps {
  onProfileClick: (id: string) => void;
}

const AdminPortal: React.FC<AdminPortalProps> = ({ onProfileClick }) => {
  const { allUsers, problems, siteConfig, updateSiteConfig, adminDeleteUser, adminDeleteProblem, bulkDeleteProblems, adminBanUser, adminVerifyUser, addProblem, bulkAddProblems, editProblem, verifySimulationSolution } = useStore();
  const [activeTab, setActiveTab] = useState<'OVERVIEW' | 'USERS' | 'CONTENT' | 'SIMULATION_AUDITS' | 'SETTINGS'>('OVERVIEW');
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [showProblemDetailModal, setShowProblemDetailModal] = useState(false);
  const [currentProblemForDetails, setCurrentProblemForDetails] = useState<Problem | null>(null);

  // Selection State
  const [selectedProblemIds, setSelectedProblemIds] = useState<string[]>([]);
  const [isBulkDeleting, setIsBulkDeleting] = useState(false);

  // Simulation Review State
  const [reviewingItem, setReviewingItem] = useState<{ solution: Solution, problem: Problem } | null>(null);
  const [auditRating, setAuditRating] = useState(5);
  const [auditFeedback, setAuditFeedback] = useState('');
  const [isAuditing, setIsAuditing] = useState(false);

  // Post/Edit Simulation State
  const [isPostModalOpen, setIsPostModalOpen] = useState(false);
  const [isBulkModalOpen, setIsBulkModalOpen] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [title, setTitle] = useState('');
  const [desc, setDesc] = useState('');
  const [expectedBehavior, setExpectedBehavior] = useState('');
  const [currentBehavior, setCurrentBehavior] = useState('');
  const [techStack, setTechStack] = useState('');
  const [stepsToReproduce, setStepsToReproduce] = useState('');
  const [difficulty, setDifficulty] = useState<'EASY' | 'MEDIUM' | 'HARD'>('MEDIUM');
  const [tags, setTags] = useState('');

  // Bulk Upload State
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [bulkStatus, setBulkStatus] = useState<'idle' | 'parsing' | 'uploading' | 'success' | 'error'>('idle');
  const [parsedCount, setParsedCount] = useState(0);

  const stats = useMemo(() => {
    const totalUsers = allUsers.length;
    const totalCompanies = allUsers.filter(u => u.role === UserRole.COMPANY).length;
    const totalStudents = allUsers.filter(u => u.role === UserRole.STUDENT).length;
    const pendingCompanies = allUsers.filter(u => u.role === UserRole.COMPANY && !u.isVerified).length;
    const onlineUsers = allUsers.filter(u => {
      if (!u.lastSeen) return false;
      const lastSeenTime = new Date(u.lastSeen).getTime();
      return (Date.now() - lastSeenTime) < 5 * 60 * 1000;
    }).length;

    const totalProblems = problems.length;
    const totalSimulations = problems.filter(p => p.isSimulation).length;
    const totalBountyValue = problems.reduce((acc, p) => {
      const val = parseFloat(p.bounty.replace(/[^0-9.]/g, '')) || 0;
      return acc + val;
    }, 0);

    return { totalUsers, totalCompanies, totalStudents, onlineUsers, totalProblems, totalSimulations, totalBountyValue, pendingCompanies };
  }, [allUsers, problems]);

  const pendingSimulationAudits = useMemo(() => {
    return problems
      .filter(p => p.isSimulation || p.companyName.toLowerCase().includes('practice'))
      .flatMap(p => (p.solutions || []).filter(s => s.reviewStatus === 'PENDING' || (!s.isVerified && !s.isRejected)).map(s => ({ problem: p, solution: s })));
  }, [problems]);

  const handleRefine = async () => {
    if (!desc.trim()) return;
    setIsRefining(true);
    const refined = await refineProblemDescription(desc);
    setDesc(refined);
    setIsRefining(false);
  };

  const handlePostOrUpdateSimulation = async (e: React.FormEvent) => {
    e.preventDefault();
    setProcessingId('POSTING');
    const problemData: Partial<Problem> = {
        title,
        description: desc,
        expectedBehavior,
        currentBehavior,
        techStack,
        stepsToReproduce,
        bounty: '₹0 (Practice)',
        isSimulation: true,
        difficulty,
        companyName: 'Simulation Hub',
        tags: tags.split(',').map(t => t.trim()).filter(t => t)
    };

    try {
        if (editingId) {
            await editProblem(editingId, problemData);
        } else {
            await addProblem(problemData);
        }
        setIsPostModalOpen(false);
        resetForm();
    } catch (error) {
        alert("Operation failed on the grid.");
    } finally {
        setProcessingId(null);
    }
  };

  const resetForm = () => {
      setTitle(''); setDesc(''); setExpectedBehavior(''); setCurrentBehavior('');
      setTechStack(''); setStepsToReproduce(''); setTags(''); setDifficulty('MEDIUM');
      setEditingId(null);
  };

  const handleAuditAction = async (status: 'VERIFIED' | 'REJECTED') => {
    if (!reviewingItem) return;
    setIsAuditing(true);
    try {
      await verifySimulationSolution(
        reviewingItem.problem.id,
        reviewingItem.solution.id,
        reviewingItem.solution.studentId,
        auditRating,
        auditFeedback,
        status
      );
      setReviewingItem(null);
      setAuditFeedback('');
      setAuditRating(5);
    } catch (error: any) {
      console.error("Verification Error Details:", error);
      alert(`Verification protocol failure: ${error.message || 'Check browser console for RPC details.'}`);
    } finally {
      setIsAuditing(false);
    }
  };

  const startEdit = (p: Problem) => {
      setTitle(p.title);
      setDesc(p.description);
      setExpectedBehavior(p.expectedBehavior || '');
      setCurrentBehavior(p.currentBehavior || '');
      setTechStack(p.techStack || '');
      setStepsToReproduce(p.stepsToReproduce || '');
      setTags(p.tags.join(', '));
      setDifficulty(p.difficulty || 'MEDIUM');
      setEditingId(p.id);
      setIsPostModalOpen(true);
  };

  const handleBanToggle = async (id: string, currentStatus: boolean) => {
      if(confirm(currentStatus ? "Unban this protocol user?" : "Ban this user? They will be detached immediately.")) {
          setProcessingId(id);
          try { await adminBanUser(id, currentStatus); } catch(e) { alert("Error updating user status"); }
          setProcessingId(null);
      }
  };

  const handleVerifyIdentity = async (id: string) => {
      if(confirm("Verify this entity and grant full grid access?")) {
          setProcessingId(id);
          try { await adminVerifyUser(id); } catch(e) { alert("Verification protocol failure"); }
          setProcessingId(null);
      }
  };

  const handleDeleteUser = async (id: string) => {
      if(confirm("Permanently wipe user identity from grid?")) {
          setProcessingId(id);
          try { await adminDeleteUser(id); } catch(e) { alert("Error deleting user"); }
          setProcessingId(null);
      }
  };

  const handleDeleteProblem = async (id: string) => {
      if(confirm("Permanently delete this problem from grid?")) {
          setProcessingId(id);
          try { await adminDeleteProblem(id); } catch(e) { alert("Error deleting problem"); }
          setProcessingId(null);
      }
  }

  // Selection Logic
  const toggleSelection = (id: string) => {
    setSelectedProblemIds(prev => 
        prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const toggleSelectAll = () => {
    if (selectedProblemIds.length === problems.length) {
        setSelectedProblemIds([]);
    } else {
        setSelectedProblemIds(problems.map(p => p.id));
    }
  };

  const handleBulkDelete = async () => {
    if (confirm(`CRITICAL: You are about to permanently extract and WIPE ${selectedProblemIds.length} nodes from the grid. Proceed?`)) {
        setIsBulkDeleting(true);
        try {
            await bulkDeleteProblems(selectedProblemIds);
            setSelectedProblemIds([]);
        } catch (e) {
            alert("Bulk extraction failed. Grid sync lost.");
        } finally {
            setIsBulkDeleting(false);
        }
    }
  };

  const handleOpenProblemDetails = (problem: Problem) => {
    setCurrentProblemForDetails(problem);
    setShowProblemDetailModal(true);
  };

  // Automated Bulk Upload Logic
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processFileAutomatically(file);
    }
  };

  const processFileAutomatically = async (file: File) => {
    setBulkStatus('parsing');
    const reader = new FileReader();

    reader.onload = async (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const json = XLSX.utils.sheet_to_json(worksheet) as any[];

        if (json.length === 0) throw new Error("Spreadsheet contains no usable nodes.");

        // Robust Mapping Protocol with Header Normalization
        const problemsData: Partial<Problem>[] = json.map(item => {
          // Normalize keys: convert everything to UPPER_SNAKE_CASE to match your CSV
          const normalized: Record<string, any> = {};
          Object.keys(item).forEach(key => {
            const normalizedKey = key.trim().toUpperCase().replace(/\s+/g, '_');
            normalized[normalizedKey] = item[key];
          });

          const rawTags = normalized.METADATA_TAGS || normalized.TAGS || "";
          const mappedTags = typeof rawTags === 'string' 
            ? rawTags.split(',').map(t => t.trim()).filter(t => t)
            : Array.isArray(rawTags) ? rawTags : [];

          return {
            title: String(normalized.SIMULATION_TITLE || normalized.TITLE || "Unnamed Protocol"),
            description: String(normalized.TECHNICAL_BRIEF || normalized.DESCRIPTION || ""),
            expectedBehavior: String(normalized.TARGET_OUTCOME || normalized.EXPECTED_BEHAVIOR || ""),
            currentBehavior: String(normalized.CURRENT_ERROR_OR_BUG || normalized.CURRENT_BEHAVIOR || ""),
            techStack: String(normalized.SYSTEM_STACK || normalized.TECH_STACK || ""),
            stepsToReproduce: String(normalized.STEPS_TO_REPRODUCE || ""),
            impact: String(normalized.IMPACT || "Normal"),
            difficulty: (String(normalized.TIER_LEVEL || normalized.DIFFICULTY || "MEDIUM").toUpperCase()) as any,
            tags: mappedTags,
            bounty: String(normalized.BOUNTY || '₹0 (Practice)'),
            isSimulation: true,
            companyName: 'Simulation Hub'
          };
        });

        setParsedCount(problemsData.length);
        setBulkStatus('uploading');

        await bulkAddProblems(problemsData);
        setBulkStatus('success');

        // Auto-close modal after successful synchronization
        setTimeout(() => {
          setIsBulkModalOpen(false);
          setBulkStatus('idle');
          if (fileInputRef.current) fileInputRef.current.value = "";
        }, 2500);

      } catch (err: any) {
        console.error("Bulk Protocol Failure:", err);
        setBulkStatus('error');
        alert(`Grid injection failed: ${err.message}`);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  return (
    <div className="min-h-screen bg-transparent pt-32 px-4 pb-12 relative">
      <div className="max-w-7xl mx-auto">

