import React, { useState, useEffect, useMemo } from 'react';
import { useStore } from '../context/Store.tsx';
import { UserRole, Problem, User } from '../types.ts';

import Navbar from '../components/Navbar.tsx';
import ProblemDetailModal from '../components/ProblemDetailModal.tsx';

// Modular Sections
import Hero from '../components/landing/Hero.tsx';
import About from '../components/landing/About.tsx';
import Offerings from '../components/landing/Offerings.tsx';
import HowItWorks from '../components/landing/HowItWorks.tsx';
import Features from '../components/landing/Features.tsx';
import ImpactStories from '../components/landing/ImpactStories.tsx';
import Leadership from '../components/landing/Leadership.tsx';
import LiveFeed from '../components/landing/LiveFeed.tsx';
import LeaderboardSnippet from '../components/landing/LeaderboardSnippet.tsx';
import Testimonials from '../components/landing/Testimonials.tsx';
import FAQ from '../components/landing/FAQ.tsx';
import CTA from '../components/landing/CTA.tsx';
import LandingFooter from '../components/landing/LandingFooter.tsx';
import PracticeStats from '../components/landing/PracticeStats.tsx';

type ViewState = 'HOME' | 'LEADERBOARD' | 'PRIVACY' | 'TERMS' | 'CONTACT' | 'AUTH' | 'DASHBOARD' | 'PAYMENT_HISTORY' | 'PROFILE_VIEW' | 'SIMULATIONS';

interface LandingPageProps {
  onLoginClick: (role: UserRole) => void;
  onViewChange: (view: any) => void;
  onProfileClick: (id: string) => void;
  onPageNav: (title: string, category: string) => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ onLoginClick, onViewChange, onProfileClick, onPageNav }) => {
  const { problems, allUsers } = useStore();
  const [scrolled, setScrolled] = useState(false);
  const [showProblemDetailModal, setShowProblemDetailModal] = useState(false);
  const [currentProblemForDetails, setCurrentProblemForDetails] = useState<Problem | null>(null);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const stats = useMemo(() => {
    const totalUsers = allUsers.length;
    const totalCompanies = allUsers.filter(u => u.role === UserRole.COMPANY).length;
    const totalStudents = allUsers.filter(u => u.role === UserRole.STUDENT).length;
    const openProblems = problems.filter(p => p.status === 'OPEN').length;
    const totalProblems = problems.length;
    const practiceCount = problems.filter(p => p.isSimulation || p.companyName.toLowerCase().includes('practice')).length;

    return { totalUsers, totalCompanies, totalStudents, openProblems, totalProblems, practiceCount };
  }, [allUsers, problems]);

  const topStudents = useMemo(() => 
    allUsers
      .filter(u => u.role === UserRole.STUDENT && (u.rating || 0) > 0)
      .sort((a, b) => (b.rating || 0) - (a.rating || 0))
      .slice(0, 3)
  , [allUsers]);

  const handleOpenProblemDetails = (problem: Problem) => {
    setCurrentProblemForDetails(problem);
    setShowProblemDetailModal(true);
  };

  const handleSolveFromDetails = (problemId: string) => {
    setShowProblemDetailModal(false);
    onViewChange('AUTH');
    onLoginClick(UserRole.STUDENT);
  };

  return (
    <div className="min-h-screen font-sans bg-white text-gray-900 selection:bg-blue-100 selection:text-blue-900">
      <Navbar onViewChange={onViewChange} transparent={!scrolled} onProfileClick={onProfileClick} />

      <Hero onLoginClick={onLoginClick} stats={stats} />

      <PracticeStats count={stats.practiceCount} onViewChange={onViewChange} />

      <About />

      <Offerings />

      <HowItWorks onLoginClick={onLoginClick} />

      <Features />

      <ImpactStories />

      <Leadership />

      <LiveFeed 
        problems={problems} 
        allUsers={allUsers} 
        onViewChange={onViewChange}
        onProblemClick={handleOpenProblemDetails}
        onProfileHover={() => {}}
        onProfileLeave={() => {}}
        showProfileCard={null}
        hoveredUser={null}
        onProfileClick={onProfileClick}
      />

      <LeaderboardSnippet 
        topStudents={topStudents}
        onViewChange={onViewChange}
        onProfileHover={() => {}}
        onProfileLeave={() => {}}
        showProfileCard={null}
        hoveredUser={null}
        onProfileClick={onProfileClick}
      />

      <Testimonials />

      <FAQ />

      <CTA onLoginClick={onLoginClick} />

      <LandingFooter onLoginClick={onLoginClick} onViewChange={onViewChange} onPageNav={onPageNav} />

      <ProblemDetailModal
        isOpen={showProblemDetailModal}
        onClose={() => setShowProblemDetailModal(false)}
        problem={currentProblemForDetails}
        onSolveClick={handleSolveFromDetails}
        onProfileClick={onProfileClick}
      />
    </div>
  );
};

export default LandingPage;

import React, { useState, useEffect } from 'react';
import { useStore } from '../context/Store.tsx';
import { UserRole } from '../types.ts';
import { Loader2, ArrowLeft, CheckCircle2, AlertTriangle, Zap, Terminal, Shield, Lock, Cpu, ArrowRight, Sparkles, XCircle, RefreshCw } from 'lucide-react';
import Modal from '../components/Modal.tsx';

interface AuthPageProps {
  initialRole?: UserRole;
  onBack: () => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ initialRole, onBack }) => {
  const { login, register, resetPassword } = useStore();
  const [isLogin, setIsLogin] = useState(true);
  const [role, setRole] = useState<UserRole>(initialRole || UserRole.STUDENT);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [extraInfo, setExtraInfo] = useState('');
  const [error, setError] = useState('');
  const [isErrorModalOpen, setIsErrorModalOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [isForgotPassword, setIsForgotPassword] = useState(false);
  const [message, setMessage] = useState('');

  const humanizeError = (rawError: string) => {
    const err = rawError.toLowerCase();
    if (err.includes('auth/invalid-credential') || err.includes('auth/wrong-password') || err.includes('auth/user-not-found')) {
      return "Incorrect digital mail or access cipher. Please verify your credentials and try again.";
    }
    if (err.includes('auth/invalid-email')) {
      return "The digital mail format provided is invalid. Check for typos.";
    }
    if (err.includes('auth/email-already-in-use')) {
      return "This identity is already synced to the grid. Try logging in instead.";
    }
    if (err.includes('.edu') || err.includes('ac.xx')) {
      return "Solver protocol requires a verified .edu or academic digital mail node.";
    }
    return rawError || "The grid encountered an unknown synchronization error. Please retry the protocol.";
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setMessage('');
    setLoading(true);

    try {
      if (isForgotPassword) {
        await resetPassword(email);
        setMessage('Reset link deployed to your inbox. Check junk if missing.');
        setLoading(false);
        return;
      }

      if (isLogin) {
        await login(email, password);
      } else {
        if (role === UserRole.STUDENT) {
            const eduRegex = /^[a-zA-Z0-9._%+-]+@[a-zA-Z0-9.-]+\.(edu|ac\.[a-z]{2}|edu\.in)$/;
            if (!eduRegex.test(email)) throw new Error("Solver requires .edu or .ac.xx credentials.");
        }
        if (role === UserRole.ADMIN && extraInfo !== 'admin2024') throw new Error("Invalid Root Key.");

        await register(email, password, role, name, extraInfo);
        setMessage(`Verification sent to ${email}. Authenticate to proceed.`);
        setIsLogin(true);
      }
    } catch (err: any) {
      setError(humanizeError(err.message));
      setIsErrorModalOpen(true);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-paper p-4 md:p-6 relative overflow-hidden">
      {/* Dynamic Background Decoration */}
      <div className="absolute top-10 left-10 opacity-5 animate-float pointer-events-none select-none hidden lg:block z-0">
        <Cpu className="w-64 h-64" />
      </div>
      <div className="absolute bottom-10 right-10 opacity-5 animate-float [animation-delay:2s] pointer-events-none select-none hidden lg:block z-0">
        <Terminal className="w-64 h-64" />
      </div>

      <button 
        onClick={onBack}
        className="fixed top-6 left-6 md:top-8 md:left-8 z-50 flex items-center gap-3 px-5 py-3 bg-white border-2 border-black font-black text-[10px] md:text-xs uppercase tracking-widest shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] hover:translate-x-1 hover:translate-y-1 hover:shadow-none transition-all group"
      >
        <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" /> 
        Return to Grid
      </button>

      <div className="w-full max-w-lg relative z-10 py-10">
        <div className="tactile-card bg-white p-8 md:p-14 rounded-[2rem] md:rounded-[3rem] relative overflow-visible border-[3px] border-black animate-pop">
          <div className="sticker-tape"></div>

          <div className="text-center mb-8 md:mb-10">
             <div className="inline-flex items-center gap-2 px-3 py-1.5 bg-black text-white rounded-xl text-[10px] font-black uppercase tracking-widest mb-6">
                <Lock className="w-3.5 h-3.5 text-citrus fill-citrus" />
                {isLogin ? 'Identity Protocol' : 'Registration Sequence'}
             </div>
             <h2 className="text-3xl md:text-5xl font-black text-black tracking-tighter leading-none mb-2">
                {isForgotPassword ? 'Reset Access' : (isLogin ? 'Welcome Back.' : 'Join the Grid.')}
             </h2>
             <p className="text-gray-400 text-[10px] md:text-xs font-bold uppercase tracking-widest mt-4">
                {isForgotPassword ? "System recovery initiated" : "Authorize your credentials to sync"}
             </p>
          </div>

          {message && (
             <div className="bg-forest text-white p-4 rounded-xl mb-8 text-[10px] font-black uppercase tracking-widest border-2 border-black shadow-[4px_4px_0px_0px_rgba(253,224,71,1)] flex items-center animate-fade-in">
                <CheckCircle2 className="w-4 h-4 mr-3 flex-shrink-0" /> {message}
             </div>
          )}

          <form className="space-y-6" onSubmit={handleSubmit}>
             {!isLogin && !isForgotPassword && (
               <div className="grid grid-cols-2 gap-3 md:gap-4 mb-8">
                  <button 
                    type="button" 
                    onClick={() => setRole(UserRole.STUDENT)} 
                    className={`py-4 text-[10px] font-black uppercase tracking-widest rounded-xl border-2 transition-all flex items-center justify-center gap-2 ${role === UserRole.STUDENT ? 'bg-black text-white border-black shadow-[4px_4px_0px_0px_rgba(253,224,71,1)]' : 'bg-white text-gray-400 border-gray-100 hover:border-black hover:text-black'}`}
                  >
                    <Zap className="w-4 h-4" /> Solver
                  </button>
                  <button 
                    type="button" 
                    onClick={() => setRole(UserRole.COMPANY)} 
                    className={`py-4 text-[10px] font-black uppercase tracking-widest rounded-xl border-2 transition-all flex items-center justify-center gap-2 ${role === UserRole.COMPANY ? 'bg-black text-white border-black shadow-[4px_4px_0px_0px_rgba(253,224,71,1)]' : 'bg-white text-gray-400 border-gray-100 hover:border-black hover:text-black'}`}
                  >
                    <Shield className="w-4 h-4" /> Company
                  </button>
               </div>
             )}

             <div className="space-y-5">
               {!isLogin && !isForgotPassword && (
                 <>
                   <div className="space-y-2">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-1">Full Identity</label>
                     <input type="text" required placeholder="Alex Murphy" className="w-full bg-paper border-2 border-black rounded-xl px-5 py-4 text-black font-bold placeholder:text-gray-300 focus:bg-citrus/5 outline-none transition-all shadow-sm" value={name} onChange={e => setName(e.target.value)} />
                   </div>
                   <div className="space-y-2">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-1">
                       {role === UserRole.STUDENT ? "Academic Institute" : "Entity Name"}
                     </label>
                     <input type="text" required placeholder={role === UserRole.STUDENT ? "IIT Kharagpur" : "CyberDyne Systems"} className="w-full bg-paper border-2 border-black rounded-xl px-5 py-4 text-black font-bold placeholder:text-gray-300 focus:bg-citrus/5 outline-none transition-all shadow-sm" value={extraInfo} onChange={e => setExtraInfo(e.target.value)} />
                   </div>
                 </>
               )}

               <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-1">Digital Mail</label>
                 <input type="email" required placeholder="user@grid.com" className="w-full bg-paper border-2 border-black rounded-xl px-5 py-4 text-black font-bold placeholder:text-gray-300 focus:bg-citrus/5 outline-none transition-all shadow-sm" value={email} onChange={e => setEmail(e.target.value)} />
               </div>

               {!isForgotPassword && (
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-1">Access Cipher</label>
                    <input type="password" required placeholder="••••••••" className="w-full bg-paper border-2 border-black rounded-xl px-5 py-4 text-black font-bold placeholder:text-gray-300 focus:bg-citrus/5 outline-none transition-all shadow-sm" value={password} onChange={e => setPassword(e.target.value)} />
                  </div>
               )}
             </div>

             <div className="flex justify-end items-center text-[10px] font-black uppercase tracking-widest mt-2">
                {!isForgotPassword && isLogin && (
                    <button type="button" onClick={() => setIsForgotPassword(true)} className="text-coral hover:underline decoration-2 transition-all">Forgot Cipher?</button>
                )}
                {isForgotPassword && (
                    <button type="button" onClick={() => setIsForgotPassword(false)} className="text-gray-400 hover:text-black transition-all">Back to terminal</button>
                )}
             </div>

             <button 
                type="submit" 
                disabled={loading} 
                className="tactile-btn w-full bg-black text-white font-black py-5 rounded-2xl text-xl uppercase tracking-widest flex justify-center items-center gap-4 transition-all hover:bg-forest disabled:opacity-50 mt-4"
             >
                {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : (
                   <>
                    {isForgotPassword ? 'Reset Link' : (isLogin ? 'Authenticate' : 'Initialize')}
                    <ArrowRight className="w-6 h-6" />
                   </>
                )}
             </button>
          </form>

          {!isForgotPassword && (
              <div className="text-center mt-8 pt-8 border-t-2 border-gray-100">
                 <p className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">
                    {isLogin ? "No identity found?" : "Already synced?"}
                    <button onClick={() => { setIsLogin(!isLogin); setError(''); setMessage(''); }} className="text-coral ml-2 hover:underline decoration-2 transition-all">
                       {isLogin ? "Generate New" : "Switch to Login"}
                    </button>
                 </p>
              </div>
          )}
        </div>

        <div className="absolute -bottom-6 -right-4 px-6 py-4 bg-citrus border-2 border-black rounded-2xl font-black text-[10px] md:text-xs uppercase tracking-widest rotate-6 shadow-lg flex items-center gap-2 pointer-events-none select-none">
           <Sparkles className="w-4 h-4" /> Secured Protocol
        </div>
      </div>

      {/* User-Friendly Error Modal */}
      <Modal 
        isOpen={isErrorModalOpen} 
        onClose={() => setIsErrorModalOpen(false)} 
        title="Protocol Interrupted"
      >
        <div className="flex flex-col items-center text-center space-y-6">
          <div className="w-20 h-20 bg-coral text-white rounded-full flex items-center justify-center border-4 border-black shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] animate-pop">
            <XCircle className="w-10 h-10" />
          </div>

          <div className="space-y-2">
            <h3 className="text-2xl font-black tracking-tighter uppercase">Signal Lost. 👀</h3>
            <p className="text-sm font-bold text-gray-500 leading-relaxed">
              {error}
            </p>
          </div>

          <div className="w-full pt-4">
            <button 
              onClick={() => setIsErrorModalOpen(false)}
              className="tactile-btn w-full bg-black text-white py-4 rounded-xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-forest transition-all"
            >
              <RefreshCw className="w-4 h-4" /> Retry Authentication
            </button>
          </div>

          <p className="text-[9px] font-black uppercase text-gray-300 tracking-[0.3em]">
            Error Code: AUTH_SEQ_FAIL
          </p>
        </div>
      </Modal>
    </div>
  );
};

export default AuthPage;

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Problem, UserRole, Solution, Review, SiteConfig, Payment, Badge, SkillLevel } from '../types.ts';
import { auth, db } from '../services/firebase.ts';
import { supabase } from '../services/supabase.ts';
import { evaluateSolutionWithAI } from '../services/geminiService.ts';

interface AppContextType {
  user: User | null;
  loading: boolean;
  allUsers: User[];
  problems: Problem[];
  payments: Payment[];
  siteConfig: SiteConfig;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string, role: UserRole, name: string, extraInfo: string) => Promise<void>;
  logout: () => void;
  resetPassword: (email: string) => Promise<void>;
  addProblem: (data: Partial<Problem>) => Promise<void>;
  bulkAddProblems: (problemsData: Partial<Problem>[]) => Promise<void>;
  editProblem: (problemId: string, data: Partial<Problem>) => Promise<void>;
  manualCloseProblem: (problemId: string) => Promise<void>;
  addSolution: (problemId: string, content: string, file?: File, details?: { githubLink?: string, techStack?: string, limitations?: string }) => Promise<void>;
  acceptSolution: (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, paymentMethod: string) => Promise<void>;
  verifySimulationSolution: (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, status: 'VERIFIED' | 'REJECTED') => Promise<void>;
  updateUserProfile: (data: Partial<User>) => Promise<void>;
  adminBanUser: (userId: string, currentStatus: boolean) => Promise<void>;
  adminVerifyUser: (userId: string) => Promise<void>;
  adminDeleteUser: (userId: string) => Promise<void>;
  adminDeleteProblem: (problemId: string) => Promise<void>;
  bulkDeleteProblems: (problemIds: string[]) => Promise<void>;
  updateSiteConfig: (newConfig: Partial<SiteConfig>) => Promise<void>;
  fetchSingleUser: (userId: string) => Promise<User | null>;
  fetchUserByUsername: (username: string) => Promise<User | null>;
  clearAuditNotification: () => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const calculateSkillLevel = (avg: number): SkillLevel => {
  if (avg >= 90) return 'Advanced';
  if (avg >= 75) return 'Intermediate';
  if (avg >= 60) return 'Junior';
  return 'Beginner';
};

const BADGE_RULES: Badge[] = [
    { id: 'first_fix', name: 'First Fix', threshold: 1, icon: '🎯', description: 'Solved your first practice simulation.', bonusPoints: 10, awardedAt: '' } as any,
    { id: 'debugger', name: 'Debugger', threshold: 5, icon: '🐛', description: 'Crushed 5 technical simulations.', bonusPoints: 50, awardedAt: '' } as any,
    { id: 'pro_solver', name: 'Pro Solver', threshold: 20, icon: '🔥', description: '20 simulations verified.', bonusPoints: 200, awardedAt: '' } as any
];

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [problems, setProblems] = useState<Problem[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [siteConfig, setSiteConfig] = useState<SiteConfig>({ baseFontSize: 16, enableDarkMode: true });

  const solutionUnsubscribes = useRef<Record<string, () => void>>({});

  const detectPlagiarism = (content: string, problemId: string): { similarity: number, status: 'CLEAN' | 'FLAGGED' | 'PENALIZED' } => {
    const currentProblem = problems.find(p => p.id === problemId);
    if (!currentProblem || !currentProblem.solutions) return { similarity: 0, status: 'CLEAN' };

    let maxSim = 0;
    currentProblem.solutions.forEach(s => {
      const common = s.content.split('').filter((c, i) => content[i] === c).length;
      const sim = (common / Math.max(content.length, s.content.length)) * 100;
      if (sim > maxSim) maxSim = sim;
    });

    if (maxSim > 90) return { similarity: maxSim, status: 'PENALIZED' };
    if (maxSim > 80) return { similarity: maxSim, status: 'FLAGGED' };
    return { similarity: maxSim, status: 'CLEAN' };
  };

  useEffect(() => {
    const unsub = db.collection("settings").doc("global").onSnapshot((doc) => {
        if (doc.exists) setSiteConfig(doc.data() as SiteConfig);
    }, (error) => {
        console.warn("Global settings access restricted:", error.message);
    });
    return () => unsub();
  }, []);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (firebaseUser) => {
      if (firebaseUser && firebaseUser.emailVerified) {
        const unsub = db.collection("users").doc(firebaseUser.uid).onSnapshot((snap) => {
          if (snap.exists) {
            const userData = { id: firebaseUser.uid, ...snap.data() } as User;
            if (!userData.isBanned) setUser(userData);
            else auth.signOut();
          }
        }, (error) => {
            console.error("User profile sync error:", error.message);
        });
        return () => unsub();
      } else { 
        setUser(null); 
      }
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const unsub = db.collection("users").onSnapshot((snapshot) => {
        const usersList = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() } as User));
        setAllUsers(usersList);
    }, (error) => {
        console.warn("Users list restricted for guest/role:", error.message);
        setAllUsers(user ? [user] : []);
    });
    return () => unsub();
  }, [user?.id]);

  useEffect(() => {
    const unsub = db.collection("problems").orderBy("createdAt", "desc").onSnapshot((snapshot) => {
        const problemsData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data(), solutions: [] })) as Problem[];
        setProblems(problemsData);

        if (auth.currentUser) {
          problemsData.forEach(p => {
            if (!solutionUnsubscribes.current[p.id]) {
              solutionUnsubscribes.current[p.id] = db.collection("problems").doc(p.id).collection("solutions").onSnapshot((s) => {
                  setProblems(current => current.map(cp => cp.id === p.id ? { ...cp, solutions: s.docs.map(sd => ({ id: sd.id, ...sd.data() } as Solution)) } : cp));
              }, (error) => {
                  // Silently handle nested solutions permissions
              });
            }
          });
        }
      }, (error) => {
          console.warn("Problems feed restricted:", error.message);
          setProblems([]);
      });

    return () => {
      unsub();
      Object.values(solutionUnsubscribes.current).forEach((un: any) => un());
      solutionUnsubscribes.current = {};
    };
  }, [user?.id]);

  const clearAuditNotification = async () => {
    if (!user) return;
    await db.collection("users").doc(user.id).update({ auditNotification: null });
  };

  const fetchSingleUser = async (userId: string) => {
    try {
        const doc = await db.collection("users").doc(userId).get();
        return doc.exists ? { id: doc.id, ...doc.data() } as User : null;
    } catch { return null; }
  };

  const fetchUserByUsername = async (username: string) => {
    try {
        const snap = await db.collection("users").where("username", "==", username).limit(1).get();
        return !snap.empty ? { id: snap.docs[0].id, ...snap.docs[0].data() } as User : null;
    } catch { return null; }
  };

  const login = async (email: string, password: string) => {
    await auth.signInWithEmailAndPassword(email, password);
  };

  const register = async (email: string, password: string, role: UserRole, name: string, extraInfo: string) => {
    const userCredential = await auth.createUserWithEmailAndPassword(email, password);
    const uid = userCredential.user!.uid;
    const username = name.toLowerCase().replace(/\s+/g, '_') + '_' + Math.floor(Math.random() * 1000);

    // Logic: Companies start unverified, others (Students/Mentors) start verified or subject to email verify
    const isVerifiedInitially = role !== UserRole.COMPANY;

    const newUser: any = { 
      id: uid, 
      username, 
      email, 
      name, 
      role, 
      rating: 0, 
      leaderboardScore: 0, 
      penaltyPoints: 0, 
      solvedCount: 0, 
      simSolvedCount: 0, 
      skillLevel: 'Beginner', 
      badges: [], 
      reviews: [], 
      joinedAt: new Date().toISOString(),
      bio: '', 
      skills: [],
      isVerified: isVerifiedInitially
    };

    // Only add these fields if they have a value to avoid 'undefined' errors in Firestore
    if (role === UserRole.STUDENT) {
      newUser.university = extraInfo || "";
    } else if (role === UserRole.COMPANY) {
      newUser.companyName = extraInfo || "";
    }

    await db.collection("users").doc(uid).set(newUser);
    await userCredential.user!.sendEmailVerification();
    await auth.signOut();
  };

  const logout = async () => {
    Object.values(solutionUnsubscribes.current).forEach((un: any) => un());
    solutionUnsubscribes.current = {};
    setUser(null);
    await auth.signOut();
  };

  const resetPassword = (email: string) => auth.sendPasswordResetEmail(email);

  const addProblem = async (data: Partial<Problem>) => {
    if (!user || !user.isVerified) return;
    await db.collection("problems").add({ 
        ...data, companyId: user.id, companyName: user.companyName || user.name, 
        status: 'OPEN', createdAt: new Date().toISOString() 
    });
  };

  const bulkAddProblems = async (problemsData: Partial<Problem>[]) => {
    if (!user || user.role !== UserRole.ADMIN) return;

    const batch = db.batch();
    const problemsCol = db.collection("problems");

    problemsData.forEach((data) => {
        const newDocRef = problemsCol.doc();
        batch.set(newDocRef, {
            ...data,
            companyId: user.id,
            companyName: data.companyName || 'Simulation Hub',
            status: 'OPEN',
            createdAt: new Date().toISOString(),
            isSimulation: data.isSimulation ?? true
        });
    });

    await batch.commit();
  };

  const addSolution = async (problemId: string, content: string, file?: File, details?: { githubLink?: string, techStack?: string, limitations?: string }) => {
    if (!user) return;
    const plag = detectPlagiarism(content, problemId);
    const prob = problems.find(p => p.id === problemId);
    const aiEval = await evaluateSolutionWithAI(prob?.description || "", content);

    let attachmentUrl = null;
    if (file) {
      const path = `solutions/${problemId}/${user.id}/${Date.now()}_${file.name}`;
      const { data: uploadData, error: uploadError } = await supabase.storage.from('solutions').upload(path, file);

      if (uploadError) {
          console.error("Supabase Storage Error:", uploadError);
          if (uploadError.message.includes("Bucket not found")) {
              throw new Error("Critical: 'solutions' bucket missing in Supabase. Check dashboard.");
          }
          throw uploadError;
      }

      attachmentUrl = supabase.storage.from('solutions').getPublicUrl(path).data.publicUrl;
    }

    await db.collection("problems").doc(problemId).collection("solutions").add({ 
        problemId, studentId: user.id, studentName: user.name, 
        content, 
        githubLink: details?.githubLink || "",
        techStack: details?.techStack || "",
        limitations: details?.limitations || "",
        submittedAt: new Date().toISOString(), 
        isAccepted: false, isVerified: false, isRejected: false,
        reviewStatus: 'PENDING',
        aiEvaluation: aiEval,
        plagiarismMetadata: plag,
        attachmentUrl 
    });
  };

  const verifySimulationSolution = async (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, status: 'VERIFIED' | 'REJECTED') => {
    if (!user || (user.role !== UserRole.MENTOR && user.role !== UserRole.ADMIN)) return;

    await db.runTransaction(async (transaction) => {
      const studentRef = db.collection("users").doc(studentId);
      const solRef = db.collection("problems").doc(problemId).collection("solutions").doc(solutionId);

      const studentSnap = await transaction.get(studentRef);
      const solSnap = await transaction.get(solRef);

      if (!studentSnap.exists || !solSnap.exists) {
          throw new Error("Target node or submission detached.");
      }

      const studentData = studentSnap.data() as User;
      const solData = solSnap.data() as Solution;
      const isVerified = status === 'VERIFIED';

      transaction.update(solRef, { 
        isVerified, 
        isRejected: !isVerified, 
        reviewStatus: status,
        rating, 
        feedback, 
        mentorId: user.id, 
        mentorName: user.name 
      });

      if (isVerified) {
        const verifiedSims = (studentData.simSolvedCount || 0) + 1;
        const pastScores = (studentData.reviews || []).map(r => r.rating).slice(-4);
        const allScores = [...pastScores, rating];
        const rollingAvg = Math.round(allScores.reduce((a,b) => a + b, 0) / allScores.length);

        let bonusPoints = 0;
        const earnedBadges = studentData.badges || [];
        const newBadges: Badge[] = [];
        BADGE_RULES.forEach(rule => {
            if (verifiedSims >= (rule as any).threshold && !earnedBadges.find(b => b.id === rule.id)) {
                const b = { ...rule, awardedAt: new Date().toISOString() };
                newBadges.push(b);
                bonusPoints += b.bonusPoints;
            }
        });

        const plag = solData.plagiarismMetadata;
        let penaltyInc = 0;
        if (plag?.status === 'PENALIZED') penaltyInc = 100;
        else if (plag?.status === 'FLAGGED') penaltyInc = 25;

        const finalScore = (verifiedSims * 10) + (rollingAvg * 2) + bonusPoints - ((studentData.penaltyPoints || 0) + penaltyInc);

        transaction.update(studentRef, {
            simSolvedCount: verifiedSims,
            rollingAverage: rollingAvg,
            skillLevel: calculateSkillLevel(rollingAvg),
            penaltyPoints: (studentData.penaltyPoints || 0) + penaltyInc,
            leaderboardScore: finalScore,
            badges: [...earnedBadges, ...newBadges],
            reviews: [...(studentData.reviews || []), {
                id: solutionId, problemTitle: 'Simulation Exercise',
                rating, feedback, createdAt: new Date().toISOString(),
                companyName: `Mentor: ${user.name}`
            }],
            auditNotification: { 
                problemId, 
                problemTitle: 'Simulation Verified', 
                status: 'VERIFIED', 
                feedback, 
                read: false 
            }
        });
      } else {
        transaction.update(studentRef, {
            auditNotification: { 
                problemId, 
                problemTitle: 'Simulation Review', 
                status: 'REJECTED', 
                feedback, 
                read: false 
            }
        });
      }
    });
  };

  const acceptSolution = async (pId: string, sId: string, stId: string, r: number, f: string) => {
      if (!user) return;
      await db.runTransaction(async (transaction) => {
          const studentRef = db.collection("users").doc(stId);
          const solRef = db.collection("problems").doc(pId).collection("solutions").doc(sId);
          const studentSnap = await transaction.get(studentRef);

          transaction.update(solRef, { isAccepted: true, rating: r, feedback: f });
          transaction.update(db.collection("problems").doc(pId), { status: 'CLOSED' });

          if (studentSnap.exists) {
            const data = studentSnap.data() as User;
            transaction.update(studentRef, { solvedCount: (data.solvedCount || 0) + 1 });
          }
      });
  };

  const updateUserProfile = async (data: Partial<User>) => {
    if (!user) return;
    await db.collection("users").doc(user.id).update(data);
  };

  const adminBanUser = async (id: string, s: boolean) => { await db.collection("users").doc(id).update({ isBanned: !s }); };
  const adminVerifyUser = async (id: string) => { await db.collection("users").doc(id).update({ isVerified: true }); };
  const adminDeleteUser = async (id: string) => { await db.collection("users").doc(id).delete(); };

  const adminDeleteProblem = async (id: string) => { 
    if (!user || user.role !== UserRole.ADMIN) return;

    // Deep wipe: get sub-collection first
    const solSnap = await db.collection("problems").doc(id).collection("solutions").get();
    const batch = db.batch();
    solSnap.docs.forEach(doc => batch.delete(doc.ref));
    batch.delete(db.collection("problems").doc(id));
    await batch.commit();
  };

  const bulkDeleteProblems = async (ids: string[]) => {
    if (!user || user.role !== UserRole.ADMIN) return;

    // Process in sequential chunks/loops to ensure all sub-collections are wiped
    for (const id of ids) {
      const solSnap = await db.collection("problems").doc(id).collection("solutions").get();
      const batch = db.batch();

      // Delete all solution nodes first
      solSnap.docs.forEach(doc => batch.delete(doc.ref));

      // Delete the problem node
      batch.delete(db.collection("problems").doc(id));

      await batch.commit();
    }
  };

  const updateSiteConfig = async (c: Partial<SiteConfig>) => { await db.collection("settings").doc("global").set(c, { merge: true }); };
  const editProblem = async (id: string, d: any) => { await db.collection("problems").doc(id).update(d); };
  const manualCloseProblem = async (id: string) => { await db.collection("problems").doc(id).update({ status: 'CLOSED' }); };

  return (
    <AppContext.Provider value={{ user, loading, allUsers, problems, payments, siteConfig, login, register, logout, resetPassword, addProblem, bulkAddProblems, addSolution, acceptSolution, verifySimulationSolution, editProblem, manualCloseProblem, updateUserProfile, adminBanUser, adminVerifyUser, adminDeleteUser, adminDeleteProblem, bulkDeleteProblems, updateSiteConfig, fetchSingleUser, fetchUserByUsername, clearAuditNotification }}>
      {children}
    </AppContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useStore error");
  return context;
};

import React, { useState, useMemo, useRef } from 'react';
import { useStore } from '../context/Store.tsx';
import { UserRole, Problem, User, Solution } from '../types.ts';
import { 
  Users, CheckCircle2, Star, Trophy, Loader2, Shield, Activity, 
  Terminal, Cpu, IndianRupee, Settings, Trash2, Ban, Plus, 
  Briefcase, Layers, Info, Tag, Wand2, AlertTriangle, BarChart3, 
  BrainCircuit, Layout, Zap, Edit2, Eye, XCircle, Download, FileArchive, ArrowUpRight, ShieldCheck, UserCheck, FileSpreadsheet, X, HelpCircle,
  Square, CheckSquare, Trash
} from 'lucide-react';
import ProblemDetailModal from '../components/ProblemDetailModal.tsx';
import Modal from '../components/Modal.tsx';
import StarRatingInput from '../components/StarRatingInput.tsx';
import { refineProblemDescription } from '../services/geminiService.ts';
import * as XLSX from 'xlsx';

interface AdminPortalProps {
  onProfileClick: (id: string) => void;
}

const AdminPortal: React.FC<AdminPortalProps> = ({ onProfileClick }) => {
  const { allUsers, problems, siteConfig, updateSiteConfig, adminDeleteUser, adminDeleteProblem, bulkDeleteProblems, adminBanUser, adminVerifyUser, addProblem, bulkAddProblems, editProblem, verifySimulationSolution } = useStore();
  const [activeTab, setActiveTab] = useState<'OVERVIEW' | 'USERS' | 'CONTENT' | 'SIMULATION_AUDITS' | 'SETTINGS'>('OVERVIEW');
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [showProblemDetailModal, setShowProblemDetailModal] = useState(false);
  const [currentProblemForDetails, setCurrentProblemForDetails] = useState<Problem | null>(null);

  // Selection State
  const [selectedProblemIds, setSelectedProblemIds] = useState<string[]>([]);
  const [isBulkDeleting, setIsBulkDeleting] = useState(false);

  // Simulation Review State
  const [reviewingItem, setReviewingItem] = useState<{ solution: Solution, problem: Problem } | null>(null);
  const [auditRating, setAuditRating] = useState(5);
  const [auditFeedback, setAuditFeedback] = useState('');
  const [isAuditing, setIsAuditing] = useState(false);

  // Post/Edit Simulation State
  const [isPostModalOpen, setIsPostModalOpen] = useState(false);
  const [isBulkModalOpen, setIsBulkModalOpen] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [title, setTitle] = useState('');
  const [desc, setDesc] = useState('');
  const [expectedBehavior, setExpectedBehavior] = useState('');
  const [currentBehavior, setCurrentBehavior] = useState('');
  const [techStack, setTechStack] = useState('');
  const [stepsToReproduce, setStepsToReproduce] = useState('');
  const [difficulty, setDifficulty] = useState<'EASY' | 'MEDIUM' | 'HARD'>('MEDIUM');
  const [tags, setTags] = useState('');

  // Bulk Upload State
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [bulkStatus, setBulkStatus] = useState<'idle' | 'parsing' | 'uploading' | 'success' | 'error'>('idle');
  const [parsedCount, setParsedCount] = useState(0);

  const stats = useMemo(() => {
    const totalUsers = allUsers.length;
    const totalCompanies = allUsers.filter(u => u.role === UserRole.COMPANY).length;
    const totalStudents = allUsers.filter(u => u.role === UserRole.STUDENT).length;
    const pendingCompanies = allUsers.filter(u => u.role === UserRole.COMPANY && !u.isVerified).length;
    const onlineUsers = allUsers.filter(u => {
      if (!u.lastSeen) return false;
      const lastSeenTime = new Date(u.lastSeen).getTime();
      return (Date.now() - lastSeenTime) < 5 * 60 * 1000;
    }).length;

    const totalProblems = problems.length;
    const totalSimulations = problems.filter(p => p.isSimulation).length;
    const totalBountyValue = problems.reduce((acc, p) => {
      const val = parseFloat(p.bounty.replace(/[^0-9.]/g, '')) || 0;
      return acc + val;
    }, 0);

    return { totalUsers, totalCompanies, totalStudents, onlineUsers, totalProblems, totalSimulations, totalBountyValue, pendingCompanies };
  }, [allUsers, problems]);

  const pendingSimulationAudits = useMemo(() => {
    return problems
      .filter(p => p.isSimulation || p.companyName.toLowerCase().includes('practice'))
      .flatMap(p => (p.solutions || []).filter(s => s.reviewStatus === 'PENDING' || (!s.isVerified && !s.isRejected)).map(s => ({ problem: p, solution: s })));
  }, [problems]);

  const handleRefine = async () => {
    if (!desc.trim()) return;
    setIsRefining(true);
    const refined = await refineProblemDescription(desc);
    setDesc(refined);
    setIsRefining(false);
  };

  const handlePostOrUpdateSimulation = async (e: React.FormEvent) => {
    e.preventDefault();
    setProcessingId('POSTING');
    const problemData: Partial<Problem> = {
        title,
        description: desc,
        expectedBehavior,
        currentBehavior,
        techStack,
        stepsToReproduce,
        bounty: '₹0 (Practice)',
        isSimulation: true,
        difficulty,
        companyName: 'Simulation Hub',
        tags: tags.split(',').map(t => t.trim()).filter(t => t)
    };

    try {
        if (editingId) {
            await editProblem(editingId, problemData);
        } else {
            await addProblem(problemData);
        }
        setIsPostModalOpen(false);
        resetForm();
    } catch (error) {
        alert("Operation failed on the grid.");
    } finally {
        setProcessingId(null);
    }
  };

  const resetForm = () => {
      setTitle(''); setDesc(''); setExpectedBehavior(''); setCurrentBehavior('');
      setTechStack(''); setStepsToReproduce(''); setTags(''); setDifficulty('MEDIUM');
      setEditingId(null);
  };

  const handleAuditAction = async (status: 'VERIFIED' | 'REJECTED') => {
    if (!reviewingItem) return;
    setIsAuditing(true);
    try {
      await verifySimulationSolution(
        reviewingItem.problem.id,
        reviewingItem.solution.id,
        reviewingItem.solution.studentId,
        auditRating,
        auditFeedback,
        status
      );
      setReviewingItem(null);
      setAuditFeedback('');
      setAuditRating(5);
    } catch (error: any) {
      console.error("Verification Error Details:", error);
      alert(`Verification protocol failure: ${error.message || 'Check browser console for RPC details.'}`);
    } finally {
      setIsAuditing(false);
    }
  };

  const startEdit = (p: Problem) => {
      setTitle(p.title);
      setDesc(p.description);
      setExpectedBehavior(p.expectedBehavior || '');
      setCurrentBehavior(p.currentBehavior || '');
      setTechStack(p.techStack || '');
      setStepsToReproduce(p.stepsToReproduce || '');
      setTags(p.tags.join(', '));
      setDifficulty(p.difficulty || 'MEDIUM');
      setEditingId(p.id);
      setIsPostModalOpen(true);
  };

  const handleBanToggle = async (id: string, currentStatus: boolean) => {
      if(confirm(currentStatus ? "Unban this protocol user?" : "Ban this user? They will be detached immediately.")) {
          setProcessingId(id);
          try { await adminBanUser(id, currentStatus); } catch(e) { alert("Error updating user status"); }
          setProcessingId(null);
      }
  };

  const handleVerifyIdentity = async (id: string) => {
      if(confirm("Verify this entity and grant full grid access?")) {
          setProcessingId(id);
          try { await adminVerifyUser(id); } catch(e) { alert("Verification protocol failure"); }
          setProcessingId(null);
      }
  };

  const handleDeleteUser = async (id: string) => {
      if(confirm("Permanently wipe user identity from grid?")) {
          setProcessingId(id);
          try { await adminDeleteUser(id); } catch(e) { alert("Error deleting user"); }
          setProcessingId(null);
      }
  };

  const handleDeleteProblem = async (id: string) => {
      if(confirm("Permanently delete this problem from grid?")) {
          setProcessingId(id);
