const AdminPortal: React.FC<{ onProfileClick: (id: string) => void }> = ({ onProfileClick }) => {
  const { allUsers, problems, adminDeleteProblem, bulkDeleteProblems, bulkAddProblems } = useStore();
  const [activeTab, setActiveTab] = useState<'OVERVIEW' | 'USERS' | 'CONTENT' | 'SIMULATION_AUDITS' | 'SETTINGS'>('OVERVIEW');
  const [showProblemDetailModal, setShowProblemDetailModal] = useState(false);
  const [currentProblemForDetails, setCurrentProblemForDetails] = useState<Problem | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [visibleCount, setVisibleCount] = useState(20);

  const [selectedProblemIds, setSelectedProblemIds] = useState<string[]>([]);
  const [isBulkDeleting, setIsBulkDeleting] = useState(false);
  const bulkInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (activeTab !== 'CONTENT') setSelectedProblemIds([]);
    setVisibleCount(20); // Reset visible count on tab change
  }, [activeTab]);

  const stats = useMemo(() => {
    const totalUsers = allUsers.length;
    const onlineUsers = allUsers.filter(u => u.lastSeen && (Date.now() - new Date(u.lastSeen).getTime()) < 5 * 60 * 1000).length;
    const totalSimulations = problems.filter(p => p.isSimulation).length;
    const totalBountyValue = problems.reduce((acc, p) => acc + (parseFloat(p.bounty.replace(/[^0-9.]/g, '')) || 0), 0);
    return { totalUsers, onlineUsers, totalSimulations, totalBountyValue };
  }, [allUsers, problems]);

  const pendingSimulationAudits = useMemo(() => {
    return problems.flatMap(p => (p.solutions || []).filter(s => s.reviewStatus === 'PENDING').map(s => ({ problem: p, solution: s })));
  }, [problems]);

  const handleDownloadTemplate = () => {
    const headers = ["Title", "Description", "Bounty", "Difficulty", "Tags"];
    const csvContent = [headers, ["Sample React Debugging", "Fix the memory leak...", "5000", "MEDIUM", "React, Hooks"]].map(e => e.join(",")).join("\n");
    const link = document.createElement("a");
    link.setAttribute("href", URL.createObjectURL(new Blob([csvContent], { type: 'text/csv' })));
    link.setAttribute("download", "simulation_template.csv");
    link.click();
  };

  const handleBulkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsSyncing(true);
    const reader = new FileReader();
    reader.onload = async (evt) => {
        try {
            const data: any[] = XLSX.utils.sheet_to_json(XLSX.read(evt.target?.result, { type: 'binary' }).Sheets[XLSX.read(evt.target?.result, { type: 'binary' }).SheetNames[0]]);
            const pToUp = data.map(item => ({
                title: item.Title || 'Untitled Simulation',
                description: item.Description || '',
                bounty: (item.Bounty || '0').toString(),
                difficulty: (item.Difficulty || 'MEDIUM').toUpperCase(),
                tags: (item.Tags || '').split(',').map((t: string) => t.trim()),
                isSimulation: true
            }));
            if (pToUp.length) await bulkAddProblems(pToUp);
        } catch (err) { alert("Format Error."); } finally { setIsSyncing(false); }
    };
    reader.readAsBinaryString(file);
  };

  const handleBulkDelete = async () => {
    if (!selectedProblemIds.length) return;
    if (confirm(`Execute wipe protocol for ${selectedProblemIds.length} nodes?`)) {
        setIsBulkDeleting(true);
        try { await bulkDeleteProblems(selectedProblemIds); setSelectedProblemIds([]); } finally { setIsBulkDeleting(false); }
    }
  };

  return (
    <div className="min-h-screen bg-transparent pt-32 px-4 pb-12 relative">
      <div className="max-w-7xl mx-auto">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-12 gap-8 reveal">
            <div className="tactile-card bg-black text-white p-10 rounded-[3rem] shadow-xl relative overflow-hidden flex-1 w-full">
              <div className="absolute right-[-20px] top-[-20px] opacity-10 p-4"><Shield className="w-64 h-64" /></div>
              <div className="relative z-10">
                  <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-coral text-white rounded-xl text-[10px] font-black uppercase tracking-widest border-2 border-black mb-6">
                     <Terminal className="w-4 h-4" /> System Oversight
                  </div>
                  <h1 className="text-5xl md:text-7xl font-black mb-2 tracking-tighter leading-none">Admin <span className="text-citrus italic">Console.</span></h1>
                  <p className="text-gray-400 font-bold uppercase tracking-[0.2em] mt-4">Infrastructure & Audit Control 👀</p>
              </div>
            </div>
            <div className="flex flex-col sm:flex-row gap-4 w-full md:w-auto">
                <button onClick={handleDownloadTemplate} className="tactile-btn px-6 py-6 bg-paper text-black border-4 border-black rounded-[2rem] font-black shadow-xl"><Download className="w-5 h-5" /></button>
                <input type="file" ref={bulkInputRef} onChange={handleBulkUpload} className="hidden" accept=".xlsx,.xls,.csv" />
                <button disabled={isSyncing} onClick={() => bulkInputRef.current?.click()} className="tactile-btn px-8 py-6 bg-citrus text-black border-4 border-black rounded-[2rem] font-black text-lg flex items-center gap-4 shadow-xl">
                    {isSyncing ? <Loader2 className="w-6 h-6 animate-spin" /> : <FileSpreadsheet className="w-6 h-6" />} Sync Nodes
                </button>
            </div>
        </div>

        <div className="flex space-x-4 mb-10 overflow-x-auto pb-4">
           {['OVERVIEW', 'USERS', 'CONTENT', 'SIMULATION_AUDITS', 'SETTINGS'].map((tab) => (
             <button key={tab} onClick={() => setActiveTab(tab as any)} className={`tactile-btn px-8 py-3 rounded-xl font-black text-xs uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === tab ? 'bg-black text-white' : 'bg-white text-black hover:bg-citrus'}`}>
                {tab.replace('_', ' ')} {tab === 'SIMULATION_AUDITS' && pendingSimulationAudits.length > 0 && <span className="ml-2 bg-coral text-white px-2 py-0.5 rounded-full text-[8px]">{pendingSimulationAudits.length}</span>}
             </button>
           ))}
        </div>

        {activeTab === 'OVERVIEW' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8 mb-12">
             <div className="tactile-card p-8 rounded-3xl bg-white text-center">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Online Now</p>
                <div className="text-5xl font-black text-black leading-none">{stats.onlineUsers}</div>
            </div>
            <div className="tactile-card p-8 rounded-3xl bg-white text-center">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Total Nodes</p>
                <div className="text-5xl font-black text-black leading-none">{stats.totalUsers}</div>
            </div>
            <div className="tactile-card p-8 rounded-3xl bg-white text-center">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Simulations</p>
                <div className="text-5xl font-black text-black leading-none">{stats.totalSimulations}</div>
            </div>
            <div className="tactile-card p-8 rounded-3xl bg-citrus text-center border-black">
                <p className="text-[10px] font-black text-black uppercase tracking-widest opacity-40 mb-2">Volume</p>
                <div className="text-4xl font-black text-black">₹{stats.totalBountyValue.toLocaleString('en-IN')}</div>
            </div>
          </div>
        )}

        {activeTab === 'CONTENT' && (
            <div className="tactile-card bg-white rounded-[2.5rem] overflow-hidden reveal mb-20 border-2 border-black shadow-[12px_12px_0px_0px_rgba(0,0,0,1)]">
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                    <thead className="bg-gray-50 text-[10px] uppercase text-gray-400 font-black tracking-widest border-b-2 border-black/5">
                        <tr>
                            <th className="p-6 w-12">
                                <button onClick={() => setSelectedProblemIds(selectedProblemIds.length === problems.length ? [] : problems.map(p => p.id))}>
                                    {selectedProblemIds.length === problems.length ? <CheckSquare className="w-5 h-5 text-forest" /> : <Square className="w-5 h-5" />}
                                </button>
                            </th>
                            <th className="p-6">Title</th>
                            <th className="p-6">Type</th>
                            <th className="p-6">Difficulty</th>
                            <th className="p-6">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y-2 divide-gray-50">
                        {problems.slice(0, visibleCount).map(p => (
                            <ProblemRow 
                                key={p.id} 
                                p={p} 
                                isSelected={selectedProblemIds.includes(p.id)} 
                                onToggle={(id) => setSelectedProblemIds(p => p.includes(id) ? p.filter(i => i !== id) : [...p, id])}
                                onDelete={adminDeleteProblem}
                                onDetail={(p) => { setCurrentProblemForDetails(p); setShowProblemDetailModal(true); }}
                            />
                        ))}
                    </tbody>
                    </table>
                </div>
                {visibleCount < problems.length && (
                    <div className="p-8 text-center bg-gray-50 border-t-2 border-black/5">
                        <button onClick={() => setVisibleCount(c => c + 30)} className="text-sm font-black uppercase text-coral hover:underline">Reveal More Nodes ({problems.length - visibleCount} hidden)</button>
                    </div>
                )}
            </div>
        )}

        {selectedProblemIds.length > 0 && activeTab === 'CONTENT' && (
            <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[1000] w-full max-w-2xl px-6 animate-pop">
                <div className="bg-coral text-white p-6 rounded-[2rem] border-4 border-black shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] flex items-center justify-between gap-6">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-black text-white rounded-2xl flex items-center justify-center font-black border-2 border-white/20">{selectedProblemIds.length}</div>
                        <div><p className="font-black uppercase tracking-widest text-xs">Node extraction sequence</p></div>
                    </div>
                    <div className="flex gap-3">
                        <button onClick={() => setSelectedProblemIds([])} className="px-6 py-3 bg-black/20 rounded-xl font-black text-[10px] uppercase">Cancel</button>
                        <button onClick={handleBulkDelete} disabled={isBulkDeleting} className="px-8 py-3 bg-white text-coral rounded-xl font-black text-[10px] uppercase flex items-center gap-2">
                            {isBulkDeleting ? <Loader2 className="w-4 h-4 animate-spin" /> : <><Trash className="w-4 h-4" /> Wipe Nodes</>}
                        </button>
                    </div>
                </div>
            </div>
        )}
      </div>
      <ProblemDetailModal isOpen={showProblemDetailModal} onClose={() => setShowProblemDetailModal(false)} problem={currentProblemForDetails} onProfileClick={onProfileClick} />
    </div>
  );
};

export default AdminPortal;

import React, { createContext, useContext, useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { User, Problem, UserRole, Solution, Review, SiteConfig, Payment, Badge, SkillLevel, PlagiarismMetadata } from '../types.ts';
import { auth, db } from '../services/firebase.ts';
import { supabase } from '../services/supabase.ts';
import { evaluateSolutionWithAI } from '../services/geminiService.ts';

interface AppContextType {
  user: User | null;
  loading: boolean;
  allUsers: User[];
  problems: Problem[];
  payments: Payment[];
  siteConfig: SiteConfig;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string, role: UserRole, name: string, extraInfo: string) => Promise<void>;
  logout: () => void;
  resetPassword: (email: string) => Promise<void>;
  addProblem: (data: Partial<Problem>) => Promise<void>;
  bulkAddProblems: (problemsData: Partial<Problem>[]) => Promise<void>;
  editProblem: (problemId: string, data: Partial<Problem>) => Promise<void>;
  manualCloseProblem: (problemId: string) => Promise<void>;
  addSolution: (problemId: string, content: string, file?: File, details?: { githubLink?: string, techStack?: string, limitations?: string }) => Promise<void>;
  acceptSolution: (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, paymentMethod: string) => Promise<void>;
  verifySimulationSolution: (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, status: 'VERIFIED' | 'REJECTED') => Promise<void>;
  updateUserProfile: (data: Partial<User>) => Promise<void>;
  adminBanUser: (userId: string, currentStatus: boolean) => Promise<void>;
  adminVerifyUser: (userId: string) => Promise<void>;
  adminDeleteUser: (userId: string) => Promise<void>;
  adminDeleteProblem: (problemId: string) => Promise<void>;
  bulkDeleteProblems: (problemIds: string[]) => Promise<void>;
  updateSiteConfig: (newConfig: Partial<SiteConfig>) => Promise<void>;
  fetchSingleUser: (userId: string) => Promise<User | null>;
  fetchUserByUsername: (username: string) => Promise<User | null>;
  clearAuditNotification: () => Promise<void>;
  overridePlagiarismStatus: (problemId: string, solutionId: string, newStatus: 'CLEAN' | 'FLAGGED' | 'PENALIZED') => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const calculateSimilarity = (str1: string, str2: string): number => {
  const set1 = new Set(str1.toLowerCase().split(/\s+/));
  const set2 = new Set(str2.toLowerCase().split(/\s+/));
  const intersection = new Set([...set1].filter(x => set2.has(x)));
  const union = new Set([...set1, ...set2]);
  return union.size === 0 ? 0 : (intersection.size / union.size) * 100;
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [internalAuthUser, setInternalAuthUser] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [problems, setProblems] = useState<Problem[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [siteConfig, setSiteConfig] = useState<SiteConfig>({ baseFontSize: 16, enableDarkMode: true });

  const solutionUnsubscribes = useRef<Record<string, () => void>>({});
  const profileUnsubscribe = useRef<(() => void) | null>(null);

  useEffect(() => {
    const unsub = db.collection("settings").doc("global").onSnapshot(doc => {
      if (doc.exists) setSiteConfig(doc.data() as SiteConfig);
    });
    return unsub;
  }, []);

  useEffect(() => {
    const unsub = auth.onAuthStateChanged(firebaseUser => {
      setInternalAuthUser(firebaseUser);
      if (!firebaseUser) { setUser(null); setLoading(false); }
    });
    return unsub;
  }, []);

  useEffect(() => {
    if (profileUnsubscribe.current) profileUnsubscribe.current();
    if (internalAuthUser?.emailVerified) {
      profileUnsubscribe.current = db.collection("users").doc(internalAuthUser.uid).onSnapshot(snap => {
        if (snap.exists) {
          const userData = { id: internalAuthUser.uid, ...snap.data() } as User;
          if (!userData.isBanned) setUser(userData);
          else auth.signOut();
        }
        setLoading(false);
      }, () => setLoading(false));
    } else if (internalAuthUser) { setLoading(false); }
    return () => profileUnsubscribe.current?.();
  }, [internalAuthUser]);

  useEffect(() => {
    const unsub = db.collection("users").onSnapshot(snapshot => {
        setAllUsers(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as User)));
    });
    return unsub;
  }, []);

  useEffect(() => {
    const unsub = db.collection("problems").orderBy("createdAt", "desc").onSnapshot(snapshot => {
        const problemsData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data(), solutions: [] })) as Problem[];
        setProblems(problemsData);
        if (internalAuthUser) {
          problemsData.forEach(p => {
            if (!solutionUnsubscribes.current[p.id]) {
              solutionUnsubscribes.current[p.id] = db.collection("problems").doc(p.id).collection("solutions").onSnapshot(s => {
                  setProblems(current => current.map(cp => cp.id === p.id ? { ...cp, solutions: s.docs.map(sd => ({ id: sd.id, ...sd.data() } as Solution)) } : cp));
              });
            }
          });
        }
    });
    return () => {
      unsub();
      Object.values(solutionUnsubscribes.current).forEach(un => un());
      solutionUnsubscribes.current = {};
    };
  }, [internalAuthUser]);

  const addSolution = useCallback(async (pId: string, content: string, file?: File, details?: any) => {
    if (!user) return;
    let attachmentUrl = null;
    if (file) {
        const path = `solutions/${pId}/${user.id}/${Date.now()}_${file.name}`;
        await supabase.storage.from('solutions').upload(path, file);
        attachmentUrl = supabase.storage.from('solutions').getPublicUrl(path).data.publicUrl;
    }
    const existingSols = problems.find(p => p.id === pId)?.solutions || [];
    let maxSimilarity = 0; let targetId = '';
    existingSols.forEach(sol => {
      const sim = calculateSimilarity(content, sol.content);
      if (sim > maxSimilarity) { maxSimilarity = sim; targetId = sol.id; }
    });
    let plagStatus: 'CLEAN' | 'FLAGGED' | 'PENALIZED' = 'CLEAN';
    if (maxSimilarity > 90) plagStatus = 'PENALIZED';
    else if (maxSimilarity > 80) plagStatus = 'FLAGGED';

    const aiResult = await evaluateSolutionWithAI(problems.find(p => p.id === pId)?.description || '', content);
    await db.collection("problems").doc(pId).collection("solutions").add({ 
      problemId: pId, studentId: user.id, studentName: user.name, content, submittedAt: new Date().toISOString(), reviewStatus: 'PENDING', attachmentUrl, 
      plagiarismMetadata: { similarityPercentage: maxSimilarity, targetSolutionId: targetId, status: plagStatus },
      aiEvaluation: aiResult, ...details 
    });
  }, [user, problems]);

  const verifySimulationSolution = useCallback(async (pId: string, sId: string, stId: string, rating: number, feedback: string, status: 'VERIFIED' | 'REJECTED') => {
    if (!user || (user.role !== UserRole.MENTOR && user.role !== UserRole.ADMIN)) return;
    await db.runTransaction(async (transaction) => {
      const studentRef = db.collection("users").doc(stId);
      const solRef = db.collection("problems").doc(pId).collection("solutions").doc(sId);
      const studentSnap = await transaction.get(studentRef);
      const studentData = studentSnap.data() as User;
      const solSnap = await transaction.get(solRef);
      const solData = solSnap.data() as Solution;
      const isVerified = status === 'VERIFIED';
      transaction.update(solRef, { isVerified, isRejected: !isVerified, reviewStatus: status, rating, feedback, mentorId: user.id, mentorName: user.name });
      if (isVerified) {
        const verifiedSims = (studentData.simSolvedCount || 0) + 1;
        const pastScores = (studentData.reviews || []).map(r => r.rating).slice(-4);
        const rollingAvg = Math.round(([...pastScores, rating].reduce((a,b) => a+b, 0)) / (pastScores.length + 1));
        const penalty = (solData.plagiarismMetadata?.status === 'PENALIZED' ? 50 : 0) + (studentData.penaltyPoints || 0);
        transaction.update(studentRef, {
            simSolvedCount: verifiedSims, rollingAverage: rollingAvg, penaltyPoints: penalty,
            leaderboardScore: (verifiedSims * 10) + (rollingAvg * 2) - penalty,
            reviews: [...(studentData.reviews || []), { id: sId, problemTitle: 'Simulation Exercise', rating, feedback, createdAt: new Date().toISOString(), companyName: `Mentor: ${user.name}` }],
            auditNotification: { problemId: pId, problemTitle: 'Simulation Verified', status: 'VERIFIED', feedback, read: false }
        });
      } else { transaction.update(studentRef, { auditNotification: { problemId: pId, problemTitle: 'Simulation Review', status: 'REJECTED', feedback, read: false } }); }
    });
  }, [user]);

  const stableActions = useMemo(() => ({
    login: async (e: string, p: string) => await auth.signInWithEmailAndPassword(e, p),
    register: async (email: string, password: string, role: UserRole, name: string, extraInfo: string) => {
      const userCredential = await auth.createUserWithEmailAndPassword(email, password);
      const uid = userCredential.user!.uid;
      const newUser: any = { 
        id: uid, username: name.toLowerCase().replace(/\s+/g, '_') + '_' + Math.floor(Math.random() * 1000), email, name, role, isVerified: role !== UserRole.COMPANY,
        rating: 0, leaderboardScore: 0, penaltyPoints: 0, solvedCount: 0, simSolvedCount: 0, skillLevel: 'Beginner', badges: [], reviews: [], joinedAt: new Date().toISOString(), bio: '', skills: []
      };
      if (role === UserRole.STUDENT) newUser.university = extraInfo || "";
      else if (role === UserRole.COMPANY) newUser.companyName = extraInfo || "";
      await db.collection("users").doc(uid).set(newUser);
      await userCredential.user!.sendEmailVerification();
      await auth.signOut();
    },
    logout: async () => { await auth.signOut(); },
    resetPassword: (email: string) => auth.sendPasswordResetEmail(email),
    addProblem: async (data: Partial<Problem>) => { if (user?.isVerified) await db.collection("problems").add({ ...data, companyId: user.id, companyName: user.companyName || user.name, status: 'OPEN', createdAt: new Date().toISOString() }); },
    bulkAddProblems: async (problemsData: Partial<Problem>[]) => {
      if (user?.role !== UserRole.ADMIN) return;
      const batch = db.batch();
      problemsData.forEach(data => batch.set(db.collection("problems").doc(), { ...data, companyId: user.id, companyName: data.companyName || 'Simulation Hub', status: 'OPEN', createdAt: new Date().toISOString(), isSimulation: data.isSimulation ?? true }));
      await batch.commit();
    },
    acceptSolution: async (pId: string, sId: string, stId: string, r: number, f: string) => {
      await db.runTransaction(async t => { t.update(db.collection("problems").doc(pId).collection("solutions").doc(sId), { isAccepted: true, rating: r, feedback: f }); t.update(db.collection("problems").doc(pId), { status: 'CLOSED' }); });
    },
    editProblem: async (id: string, d: any) => { await db.collection("problems").doc(id).update(d); },
    manualCloseProblem: async (id: string) => { await db.collection("problems").doc(id).update({ status: 'CLOSED' }); },
    updateUserProfile: async (d: any) => { if(user) await db.collection("users").doc(user.id).update(d); },
    adminBanUser: async (id: string, s: boolean) => { await db.collection("users").doc(id).update({ isBanned: !s }); },
    adminVerifyUser: async (id: string) => { await db.collection("users").doc(id).update({ isVerified: true }); },
    adminDeleteUser: async (id: string) => { await db.collection("users").doc(id).delete(); },
    adminDeleteProblem: async (id: string) => { await db.collection("problems").doc(id).delete(); },
    bulkDeleteProblems: async (ids: string[]) => { const batch = db.batch(); ids.forEach(id => batch.delete(db.collection("problems").doc(id))); await batch.commit(); },
    updateSiteConfig: async (c: any) => { await db.collection("settings").doc("global").set(c, { merge: true }); },
    fetchSingleUser: async (id: string) => { const doc = await db.collection("users").doc(id).get(); return doc.exists ? { id: doc.id, ...doc.data() } as User : null; },
    fetchUserByUsername: async (u: string) => { const snap = await db.collection("users").where("username", "==", u).limit(1).get(); return !snap.empty ? { id: snap.docs[0].id, ...snap.docs[0].data() } as User : null; },
    clearAuditNotification: async () => { if(user) await db.collection("users").doc(user.id).update({ auditNotification: null }); },
    overridePlagiarismStatus: async (pId: string, sId: string, status: any) => { await db.collection("problems").doc(pId).collection("solutions").doc(sId).update({ "plagiarismMetadata.status": status }); },
  }), [user]);

  const contextValue = useMemo(() => ({
    user, loading, allUsers, problems, payments, siteConfig,
    ...stableActions, addSolution, verifySimulationSolution
  }), [user, loading, allUsers, problems, payments, siteConfig, stableActions, addSolution, verifySimulationSolution]);

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

export const useStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useStore must be used within AppProvider");
  return context;
};

