const ProblemCard = memo(({ p, onClick, idx }: { p: Problem, onClick: (p: Problem) => void, idx: number }) => (
    <div 
        onClick={() => onClick(p)}
        className={`tactile-card p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] cursor-pointer group flex flex-col h-full transition-all duration-300 ${idx % 2 === 0 ? 'md:rotate-[-0.5deg]' : 'md:rotate-[0.5deg]'} hover:rotate-0 bg-white`}
    >
        <div className="sticker-tape opacity-10 group-hover:opacity-100 transition-opacity"></div>
        <div className="flex justify-between items-start mb-6">
            <div className="px-3 py-1 bg-gray-50 border-2 border-black rounded-lg text-[9px] font-black uppercase tracking-widest flex items-center gap-2 max-w-[60%]">
                <Target className="w-3 h-3 text-coral shrink-0" />
                <span className="truncate">{p.companyName}</span>
            </div>
            <div className="text-right shrink-0">
                <div className="flex items-center font-black text-forest text-lg md:text-2xl">
                    <IndianRupee className="w-3 h-3 md:w-4 md:h-4" />
                    {p.bounty.replace(/[^\d]/g, '')}
                </div>
            </div>
        </div>
        <h3 className="text-lg md:text-2xl font-black text-black mb-3 md:mb-4 line-clamp-2 leading-tight group-hover:text-coral transition-colors">{p.title}</h3>
        <p className="text-gray-500 text-xs md:text-sm font-bold line-clamp-3 mb-6 md:mb-8 flex-grow leading-relaxed opacity-70">{p.description}</p>
        <div className="flex flex-wrap gap-2 mb-6 md:mb-8">
            {p.tags.slice(0, 3).map(tag => (
                <span key={tag} className="text-[8px] md:text-[9px] font-black uppercase tracking-[0.2em] bg-citrus/20 border border-black/5 px-2 py-1 rounded">
                    {tag}
                </span>
            ))}
        </div>
        <button 
            disabled={p.status !== 'OPEN'} 
            className={`tactile-btn w-full py-4 md:py-5 rounded-xl md:rounded-2xl font-black text-[10px] md:text-xs uppercase tracking-widest flex items-center justify-center transition-all ${p.status === 'OPEN' ? 'bg-black text-white hover:bg-coral' : 'bg-gray-100 text-gray-400 cursor-not-allowed border-black/10 shadow-none'}`}
        >
            {p.status === 'OPEN' ? <><Code2 className="w-4 h-4 mr-2" /> Initialize Solution</> : <><Lock className="w-4 h-4 mr-2" /> Locked</>}
        </button>
    </div>
));

const StudentPortal: React.FC<StudentPortalProps> = ({ onProfileClick }) => {
    const { user, allUsers, problems, addSolution, payments } = useStore();
    const [selectedProblemIdForSubmission, setSelectedProblemIdForSubmission] = useState<string | null>(null);
    const [currentProblemForDetails, setCurrentProblemForDetails] = useState<Problem | null>(null);
    const [showProblemDetailModal, setShowProblemDetailModal] = useState(false);

    const [solutionText, setSolutionText] = useState('');
    const [githubLink, setGithubLink] = useState('');
    const [techStack, setTechStack] = useState('');
    const [limitations, setLimitations] = useState('');
    const [solutionFile, setSolutionFile] = useState<File | null>(null);

    const [searchQuery, setSearchQuery] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [showSuccessModal, setShowSuccessModal] = useState(false);
    const [visibleCount, setVisibleCount] = useState(12);

    const fileInputRef = useRef<HTMLInputElement>(null);
    const currentUserData = useMemo(() => allUsers.find(u => u.id === user?.id) || user, [allUsers, user]);
    const totalEarned = useMemo(() => payments.reduce((acc, p) => acc + (parseFloat(p.netAmount?.replace(/[^\d.]/g, '') || '0')), 0), [payments]);

    const filteredProblems = useMemo(() => {
        return problems.filter(p => {
          const query = searchQuery.toLowerCase();
          return !query || p.title.toLowerCase().includes(query) || p.description.toLowerCase().includes(query) || p.tags.some(tag => tag.toLowerCase().includes(query));
        });
    }, [problems, searchQuery]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (selectedProblemIdForSubmission && solutionText.trim()) {
            setIsSubmitting(true);
            try {
                await addSolution(selectedProblemIdForSubmission, solutionText, solutionFile || undefined, { githubLink, techStack, limitations });
                setSolutionText(''); setGithubLink(''); setTechStack(''); setLimitations(''); setSolutionFile(null);
                setSelectedProblemIdForSubmission(null);
                setShowSuccessModal(true);
            } catch (error: any) { alert(`Submission Failed: ${error.message}`); }
            setIsSubmitting(false);
        }
    };

    return (
        <div className="min-h-screen bg-transparent pt-24 md:pt-32 px-4 md:px-10 pb-12">
           <div className="max-w-7xl mx-auto">
                <div className="mb-10 md:mb-12 flex flex-col lg:flex-row justify-between items-start lg:items-end gap-6 md:gap-8">
                    <div className="space-y-4 w-full lg:w-auto">
                        <div className="flex flex-wrap gap-3">
                            <div className="inline-flex items-center gap-2 px-3 py-1.5 bg-black text-white rounded-xl text-[9px] md:text-[10px] font-black uppercase tracking-widest border border-black shadow-[3px_3px_0px_0px_rgba(253,224,71,1)]">
                               <Zap className="w-4 h-4 text-citrus fill-citrus animate-pulse" /> Solver Tier Alpha
                            </div>
                            <div className="inline-flex items-center gap-2 px-3 py-1.5 bg-forest text-citrus rounded-xl text-[9px] md:text-[10px] font-black uppercase tracking-widest border border-black shadow-[0,0,0,1]">
                               <ShieldCheck className="w-4 h-4" /> College Verified
                            </div>
                        </div>
                        <h1 className="text-3xl sm:text-5xl md:text-7xl font-black text-black tracking-tighter leading-none">Solver <span className="text-coral italic">Workspace.</span></h1>
                        <div onClick={() => currentUserData && onProfileClick(currentUserData.id)} className="flex items-center gap-3 md:gap-4 cursor-pointer group">
                            <div className="w-10 h-10 md:w-14 md:h-14 rounded-2xl border-2 border-black bg-citrus overflow-hidden flex items-center justify-center font-black shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]">
                               {currentUserData?.profilePicUrl ? <img src={currentUserData.profilePicUrl} className="w-full h-full object-cover" /> : currentUserData?.name.charAt(0)}
                            </div>
                            <div>
                                <span className="text-lg md:text-2xl font-black hover:text-coral transition-colors">{currentUserData?.name}</span>
                                <div className="text-[9px] md:text-[10px] font-black uppercase text-gray-400">{currentUserData?.university || 'Academic'} Grid</div>
                            </div>
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-3 md:gap-6 w-full lg:w-auto">
                       <div className="tactile-card bg-forest text-white p-4 md:p-6 rounded-2xl md:rounded-3xl">
                          <p className="text-[8px] md:text-[10px] font-black uppercase tracking-widest opacity-60 mb-2">Net Extraction</p>
                          <div className="flex items-center text-xl md:text-3xl font-black"><IndianRupee className="w-4 h-4 md:w-5 md:h-5 mr-1" />{totalEarned.toLocaleString('en-IN')}</div>
                       </div>
                       <div className="tactile-card bg-citrus text-black p-4 md:p-6 rounded-2xl md:rounded-3xl border-black">
                          <p className="text-[8px] md:text-[10px] font-black uppercase tracking-widest opacity-60 mb-2">Reputation</p>
                          <div className="flex items-center text-xl md:text-3xl font-black">{currentUserData?.rating?.toFixed(1) || '0.0'}<Star className="w-4 h-4 md:w-5 md:h-5 ml-1 fill-black" /></div>
                       </div>
                    </div>
                </div>

                <div className="mb-8 md:mb-12 relative group">
                    <Search className="absolute left-5 md:left-6 top-1/2 -translate-y-1/2 h-5 w-5 md:h-6 md:w-6 text-gray-400 group-focus-within:text-coral transition-colors" />
                    <input type="text" placeholder="Scan roadblocks by tech stack or tags..." className="w-full pl-12 md:pl-16 pr-6 md:pr-8 py-4 md:py-6 rounded-2xl md:rounded-[2rem] border-[3px] md:border-4 border-black shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] outline-none transition-all text-base md:text-xl font-bold" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-10">
                    {filteredProblems.slice(0, visibleCount).map((p, idx) => (
                        <ProblemCard key={p.id} p={p} onClick={handleOpenProblemDetails} idx={idx} />
                    ))}
                </div>

                {visibleCount < filteredProblems.length && (
                    <div className="mt-16 text-center">
                        <button onClick={() => setVisibleCount(c => c + 12)} className="tactile-btn px-12 py-5 bg-black text-white rounded-2xl font-black uppercase tracking-widest hover:bg-forest transition-all">Reveal More Roadblocks ({filteredProblems.length - visibleCount} hidden)</button>
                    </div>
                )}

                {filteredProblems.length === 0 && (
                    <div className="text-center py-20 md:py-32 tactile-card border-dashed bg-white/50 rounded-[2rem]">
                        <Terminal className="w-12 h-12 md:w-16 md:h-16 text-gray-200 mx-auto mb-6 animate-pulse" />
                        <p className="text-gray-400 text-base md:text-xl font-black uppercase tracking-widest">Awaiting Grid Inputs...</p>
                        <button onClick={() => setSearchQuery('')} className="mt-6 text-coral font-black underline decoration-citrus decoration-4 underline-offset-8">Reset Filter</button>
                    </div>
                )}
           </div>

           <ProblemDetailModal isOpen={showProblemDetailModal} onClose={() => setShowProblemDetailModal(false)} problem={currentProblemForDetails} onSolveClick={(id) => { setSelectedProblemIdForSubmission(id); setShowProblemDetailModal(false); }} onProfileClick={onProfileClick} />

           <Modal isOpen={!!selectedProblemIdForSubmission} onClose={() => setSelectedProblemIdForSubmission(null)} title="Deploy Protocol">
                <form onSubmit={handleSubmit} className="space-y-6 max-h-[70vh] overflow-y-auto px-1 custom-scrollbar">
                    <div className="p-3 bg-gray-100 border-2 border-black rounded-xl font-black text-forest text-xs truncate">Target: {filteredProblems.find(p => p.id === selectedProblemIdForSubmission)?.title}</div>
                    <div className="grid md:grid-cols-2 gap-4">
                      <input type="url" className="w-full border-2 border-black rounded-xl p-4 font-bold bg-paper outline-none shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]" placeholder="GitHub Repository" value={githubLink} onChange={e => setGithubLink(e.target.value)} />
                      <input type="text" className="w-full border-2 border-black rounded-xl p-4 font-bold bg-paper outline-none shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]" placeholder="Tech Stack" value={techStack} onChange={e => setTechStack(e.target.value)} />
                    </div>
                    <textarea required className="w-full border-2 border-black rounded-xl p-5 h-32 font-mono text-xs shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] bg-paper" placeholder="// Methodology summary..." value={solutionText} onChange={e => setSolutionText(e.target.value)} />
                    <textarea className="w-full border-2 border-black rounded-xl p-4 font-mono text-xs shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] bg-paper" placeholder="// Known limitations..." value={limitations} onChange={e => setLimitations(e.target.value)} />
                    <div onClick={() => fileInputRef.current?.click()} className={`w-full border-2 border-black border-dashed rounded-2xl p-6 flex flex-col items-center justify-center cursor-pointer hover:bg-citrus/5 ${solutionFile ? 'bg-forest/5' : 'bg-paper'}`}>
                        <input type="file" ref={fileInputRef} onChange={e => e.target.files?.[0] && setSolutionFile(e.target.files[0])} className="hidden" accept=".zip,.rar,.7z" />
                        {solutionFile ? <div className="flex items-center gap-4 animate-pop"><FileArchive className="w-10 h-10 text-forest" /><div className="text-left"><p className="text-sm font-black truncate max-w-[150px]">{solutionFile.name}</p></div></div> : <><Upload className="w-8 h-8 text-gray-300 mb-2" /><p className="text-xs font-black uppercase">Attach ZIP</p></>}
                    </div>
                    <button type="submit" disabled={isSubmitting || (!solutionFile && !githubLink)} className="tactile-btn w-full bg-forest text-white py-5 rounded-2xl font-black text-lg uppercase flex items-center justify-center gap-4 disabled:opacity-50">
                        {isSubmitting ? <Loader2 className="w-6 h-6 animate-spin" /> : <>Commit Changes <ArrowUpRight className="w-6 h-6" /></>}
                    </button>
                </form>
           </Modal>
           <ProfileEditModal isOpen={false} onClose={() => {}} />
           <SubmissionSuccessModal isOpen={showSuccessModal} onClose={() => setShowSuccessModal(false)} problemTitle={filteredProblems.find(p => p.id === selectedProblemIdForSubmission)?.title || 'Task'} />
        </div>
    );
};

export default StudentPortal;

import React, { createContext, useContext, useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { User, Problem, UserRole, Solution, Review, SiteConfig, Payment, Badge, SkillLevel, PlagiarismMetadata } from '../types.ts';
import { auth, db } from '../services/firebase.ts';
import { supabase } from '../services/supabase.ts';
import { evaluateSolutionWithAI } from '../services/geminiService.ts';

interface AppContextType {
  user: User | null;
  loading: boolean;
  allUsers: User[];
  problems: Problem[];
  payments: Payment[];
  siteConfig: SiteConfig;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string, role: UserRole, name: string, extraInfo: string) => Promise<void>;
  logout: () => void;
  resetPassword: (email: string) => Promise<void>;
  addProblem: (data: Partial<Problem>) => Promise<void>;
  bulkAddProblems: (problemsData: Partial<Problem>[]) => Promise<void>;
  editProblem: (problemId: string, data: Partial<Problem>) => Promise<void>;
  manualCloseProblem: (problemId: string) => Promise<void>;
  addSolution: (problemId: string, content: string, file?: File, details?: { githubLink?: string, techStack?: string, limitations?: string }) => Promise<void>;
  acceptSolution: (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, paymentMethod: string) => Promise<void>;
  verifySimulationSolution: (problemId: string, solutionId: string, studentId: string, rating: number, feedback: string, status: 'VERIFIED' | 'REJECTED') => Promise<void>;
  updateUserProfile: (data: Partial<User>) => Promise<void>;
  adminBanUser: (userId: string, currentStatus: boolean) => Promise<void>;
  adminVerifyUser: (userId: string) => Promise<void>;
  adminDeleteUser: (userId: string) => Promise<void>;
  adminDeleteProblem: (problemId: string) => Promise<void>;
  bulkDeleteProblems: (problemIds: string[]) => Promise<void>;
  updateSiteConfig: (newConfig: Partial<SiteConfig>) => Promise<void>;
  fetchSingleUser: (userId: string) => Promise<User | null>;
  fetchUserByUsername: (username: string) => Promise<User | null>;
  clearAuditNotification: () => Promise<void>;
  overridePlagiarismStatus: (problemId: string, solutionId: string, newStatus: 'CLEAN' | 'FLAGGED' | 'PENALIZED') => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Fix for Error on line 114: Explicitly defined as a function with parameter types to prevent "Type '{}' has no call signatures"
const calculateSimilarity = (str1: string, str2: string): number => {
  if (!str1 || !str2) return 0;
  const set1 = new Set(str1.toLowerCase().split(/\s+/));
  const set2 = new Set(str2.toLowerCase().split(/\s+/));
  const intersection = new Set([...set1].filter(x => set2.has(x)));
  const union = new Set([...set1, ...set2]);
  return union.size === 0 ? 0 : (intersection.size / union.size) * 100;
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [internalAuthUser, setInternalAuthUser] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [problems, setProblems] = useState<Problem[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [siteConfig, setSiteConfig] = useState<SiteConfig>({ baseFontSize: 16, enableDarkMode: true });

  const solutionUnsubscribes = useRef<Record<string, () => void>>({});
  const profileUnsubscribe = useRef<(() => void) | null>(null);

  useEffect(() => {
    const unsub = db.collection("settings").doc("global").onSnapshot(doc => {
      if (doc.exists) setSiteConfig(doc.data() as SiteConfig);
    });
    return unsub;
  }, []);

  useEffect(() => {
    const unsub = auth.onAuthStateChanged(firebaseUser => {
      setInternalAuthUser(firebaseUser);
      if (!firebaseUser) { setUser(null); setLoading(false); }
    });
    return unsub;
  }, []);

  useEffect(() => {
    if (profileUnsubscribe.current) profileUnsubscribe.current();
    if (internalAuthUser?.emailVerified) {
      profileUnsubscribe.current = db.collection("users").doc(internalAuthUser.uid).onSnapshot(snap => {
        if (snap.exists) {
          const userData = { id: internalAuthUser.uid, ...snap.data() } as User;
          if (!userData.isBanned) setUser(userData);
          else auth.signOut();
        }
        setLoading(false);
      }, () => setLoading(false));
    } else if (internalAuthUser) { setLoading(false); }
    return () => profileUnsubscribe.current?.();
  }, [internalAuthUser]);

  useEffect(() => {
    const unsub = db.collection("users").onSnapshot(snapshot => {
        setAllUsers(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as User)));
    });
    return unsub;
  }, []);

  useEffect(() => {
    const unsub = db.collection("problems").orderBy("createdAt", "desc").onSnapshot(snapshot => {
        const problemsData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data(), solutions: [] })) as Problem[];
        setProblems(problemsData);
        if (internalAuthUser) {
          problemsData.forEach(p => {
            if (!solutionUnsubscribes.current[p.id]) {
              solutionUnsubscribes.current[p.id] = db.collection("problems").doc(p.id).collection("solutions").onSnapshot(s => {
                  setProblems(current => current.map(cp => cp.id === p.id ? { ...cp, solutions: s.docs.map(sd => ({ id: sd.id, ...sd.data() } as Solution)) } : cp));
              });
            }
          });
        }
    });
    return () => {
      unsub();
      Object.values(solutionUnsubscribes.current).forEach(un => un());
      solutionUnsubscribes.current = {};
    };
  }, [internalAuthUser]);

  const addSolution = useCallback(async (pId: string, content: string, file?: File, details?: any) => {
    if (!user) return;
    let attachmentUrl = null;
    if (file) {
        const path = `solutions/${pId}/${user.id}/${Date.now()}_${file.name}`;
        await supabase.storage.from('solutions').upload(path, file);
        attachmentUrl = supabase.storage.from('solutions').getPublicUrl(path).data.publicUrl;
    }
    const existingSols = problems.find(p => p.id === pId)?.solutions || [];
    let maxSimilarity = 0; let targetId = '';
    existingSols.forEach(sol => {
      // Line 114 Fix: calculateSimilarity is ensured to be defined as a function
      const sim = calculateSimilarity(content, sol.content);
      if (sim > maxSimilarity) { maxSimilarity = sim; targetId = sol.id; }
    });
    let plagStatus: 'CLEAN' | 'FLAGGED' | 'PENALIZED' = 'CLEAN';
    if (maxSimilarity > 90) plagStatus = 'PENALIZED';
    else if (maxSimilarity > 80) plagStatus = 'FLAGGED';

    const aiResult = await evaluateSolutionWithAI(problems.find(p => p.id === pId)?.description || '', content);
    await db.collection("problems").doc(pId).collection("solutions").add({ 
      problemId: pId, studentId: user.id, studentName: user.name, content, submittedAt: new Date().toISOString(), reviewStatus: 'PENDING', attachmentUrl, 
      plagiarismMetadata: { similarityPercentage: maxSimilarity, targetSolutionId: targetId, status: plagStatus },
      aiEvaluation: aiResult, ...details 
    });
  }, [user, problems]);

  const verifySimulationSolution = useCallback(async (pId: string, sId: string, stId: string, rating: number, feedback: string, status: 'VERIFIED' | 'REJECTED') => {
    if (!user || (user.role !== UserRole.MENTOR && user.role !== UserRole.ADMIN)) return;
    await db.runTransaction(async (transaction) => {
      const studentRef = db.collection("users").doc(stId);
      const solRef = db.collection("problems").doc(pId).collection("solutions").doc(sId);
      const studentSnap = await transaction.get(studentRef);
      const studentData = studentSnap.data() as User;
      const solSnap = await transaction.get(solRef);
      const solData = solSnap.data() as Solution;
      const isVerified = status === 'VERIFIED';
      transaction.update(solRef, { isVerified, isRejected: !isVerified, reviewStatus: status, rating, feedback, mentorId: user.id, mentorName: user.name });
      if (isVerified) {
        const verifiedSims = (studentData.simSolvedCount || 0) + 1;
        const pastScores = (studentData.reviews || []).map(r => r.rating).slice(-4);
        const rollingAvg = Math.round(([...pastScores, rating].reduce((a,b) => a+b, 0)) / (pastScores.length + 1));
        const penalty = (solData.plagiarismMetadata?.status === 'PENALIZED' ? 50 : 0) + (studentData.penaltyPoints || 0);
        transaction.update(studentRef, {
            simSolvedCount: verifiedSims, rollingAverage: rollingAvg, penaltyPoints: penalty,
            leaderboardScore: (verifiedSims * 10) + (rollingAvg * 2) - penalty,
            reviews: [...(studentData.reviews || []), { id: sId, problemTitle: 'Simulation Exercise', rating, feedback, createdAt: new Date().toISOString(), companyName: `Mentor: ${user.name}` }],
            auditNotification: { problemId: pId, problemTitle: 'Simulation Verified', status: 'VERIFIED', feedback, read: false }
        });
      } else { transaction.update(studentRef, { auditNotification: { problemId: pId, problemTitle: 'Simulation Review', status: 'REJECTED', feedback, read: false } }); }
    });
  }, [user]);

  const stableActions = useMemo(() => ({
    login: async (e: string, p: string) => await auth.signInWithEmailAndPassword(e, p),
    register: async (email: string, password: string, role: UserRole, name: string, extraInfo: string) => {
      const userCredential = await auth.createUserWithEmailAndPassword(email, password);
      const uid = userCredential.user!.uid;
      const newUser: any = { 
        id: uid, username: name.toLowerCase().replace(/\s+/g, '_') + '_' + Math.floor(Math.random() * 1000), email, name, role, isVerified: role !== UserRole.COMPANY,
        rating: 0, leaderboardScore: 0, penaltyPoints: 0, solvedCount: 0, simSolvedCount: 0, skillLevel: 'Beginner', badges: [], reviews: [], joinedAt: new Date().toISOString(), bio: '', skills: []
      };
      if (role === UserRole.STUDENT) newUser.university = extraInfo || "";
      else if (role === UserRole.COMPANY) newUser.companyName = extraInfo || "";
      await db.collection("users").doc(uid).set(newUser);
      await userCredential.user!.sendEmailVerification();
      await auth.signOut();
    },
    logout: async () => { await auth.signOut(); },
    resetPassword: (email: string) => auth.sendPasswordResetEmail(email),
    addProblem: async (data: Partial<Problem>) => { if (user?.isVerified) await db.collection("problems").add({ ...data, companyId: user.id, companyName: user.companyName || user.name, status: 'OPEN', createdAt: new Date().toISOString() }); },
    bulkAddProblems: async (problemsData: Partial<Problem>[]) => {
      if (user?.role !== UserRole.ADMIN) return;
      const batch = db.batch();
      problemsData.forEach(data => batch.set(db.collection("problems").doc(), { ...data, companyId: user.id, companyName: data.companyName || 'Simulation Hub', status: 'OPEN', createdAt: new Date().toISOString(), isSimulation: data.isSimulation ?? true }));
      await batch.commit();
    },
    acceptSolution: async (pId: string, sId: string, stId: string, r: number, f: string) => {
      await db.runTransaction(async t => { t.update(db.collection("problems").doc(pId).collection("solutions").doc(sId), { isAccepted: true, rating: r, feedback: f }); t.update(db.collection("problems").doc(pId), { status: 'CLOSED' }); });
    },
    editProblem: async (id: string, d: any) => { await db.collection("problems").doc(id).update(d); },
    manualCloseProblem: async (id: string) => { await db.collection("problems").doc(id).update({ status: 'CLOSED' }); },
    updateUserProfile: async (d: any) => { if(user) await db.collection("users").doc(user.id).update(d); },
    adminBanUser: async (id: string, s: boolean) => { await db.collection("users").doc(id).update({ isBanned: !s }); },
    adminVerifyUser: async (id: string) => { await db.collection("users").doc(id).update({ isVerified: true }); },
    adminDeleteUser: async (id: string) => { await db.collection("users").doc(id).delete(); },
    adminDeleteProblem: async (id: string) => { await db.collection("problems").doc(id).delete(); },
    bulkDeleteProblems: async (ids: string[]) => { const batch = db.batch(); ids.forEach(id => batch.delete(db.collection("problems").doc(id))); await batch.commit(); },
    updateSiteConfig: async (c: any) => { await db.collection("settings").doc("global").set(c, { merge: true }); },
    fetchSingleUser: async (id: string) => { const doc = await db.collection("users").doc(id).get(); return doc.exists ? { id: doc.id, ...doc.data() } as User : null; },
    fetchUserByUsername: async (u: string) => { const snap = await db.collection("users").where("username", "==", u).limit(1).get(); return !snap.empty ? { id: snap.docs[0].id, ...snap.docs[0].data() } as User : null; },
    clearAuditNotification: async () => { if(user) await db.collection("users").doc(user.id).update({ auditNotification: null }); },
    overridePlagiarismStatus: async (pId: string, sId: string, status: any) => { await db.collection("problems").doc(pId).collection("solutions").doc(sId).update({ "plagiarismMetadata.status": status }); },
  }), [user]);

  const contextValue = useMemo(() => ({
    user, loading, allUsers, problems, payments, siteConfig,
    ...stableActions, addSolution, verifySimulationSolution
  }), [user, loading, allUsers, problems, payments, siteConfig, stableActions, addSolution, verifySimulationSolution]);

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

export const useStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useStore must be used within AppProvider");
  return context;
};

