                    <div className="p-3 bg-gray-100 border-2 border-black rounded-xl font-black text-forest text-xs truncate">Target: {filteredProblems.find(p => p.id === selectedProblemIdForSubmission)?.title}</div>
                    <div className="grid md:grid-cols-2 gap-4">
                      <input type="url" className="w-full border-2 border-black rounded-xl p-4 font-bold bg-paper outline-none shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]" placeholder="GitHub Repository" value={githubLink} onChange={e => setGithubLink(e.target.value)} />
                      <input type="text" className="w-full border-2 border-black rounded-xl p-4 font-bold bg-paper outline-none shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]" placeholder="Tech Stack" value={techStack} onChange={e => setTechStack(e.target.value)} />
                    </div>
                    <textarea required className="w-full border-2 border-black rounded-xl p-5 h-32 font-mono text-xs shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] bg-paper" placeholder="// Technical methodology summary..." value={solutionText} onChange={e => setSolutionText(e.target.value)} />
                    <textarea className="w-full border-2 border-black rounded-xl p-4 font-mono text-xs shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] bg-paper" placeholder="// Known limitations or future improvements..." value={limitations} onChange={e => setLimitations(e.target.value)} />
                    <div onClick={() => fileInputRef.current?.click()} className={`w-full border-2 border-black border-dashed rounded-2xl p-6 flex flex-col items-center justify-center cursor-pointer hover:bg-citrus/5 ${solutionFile ? 'bg-forest/5' : 'bg-paper'}`}>
                        <input type="file" ref={fileInputRef} onChange={e => e.target.files?.[0] && setSolutionFile(e.target.files[0])} className="hidden" accept=".zip,.rar,.7z" />
                        {solutionFile ? <div className="flex items-center gap-4 animate-pop"><FileArchive className="w-10 h-10 text-forest" /><div className="text-left"><p className="text-sm font-black truncate max-w-[150px]">{solutionFile.name}</p></div></div> : <><Upload className="w-8 h-8 text-gray-300 mb-2" /><p className="text-xs font-black uppercase">Attach Solution Archive (ZIP)</p></>}
                    </div>
                    <button type="submit" disabled={isSubmitting || (!solutionFile && !githubLink)} className="tactile-btn w-full bg-black text-white py-5 rounded-2xl font-black text-lg uppercase tracking-widest flex items-center justify-center gap-4 disabled:opacity-50">
                        {isSubmitting ? <Loader2 className="w-6 h-6 animate-spin" /> : <>Commit Deployment <ArrowUpRight className="w-6 h-6" /></>}
                    </button>
                </form>
           </Modal>
           <SubmissionSuccessModal isOpen={showSuccessModal} onClose={() => setShowSuccessModal(false)} problemTitle={filteredProblems.find(p => p.id === selectedProblemIdForSubmission)?.title || 'Task'} />
        </div>
    );
};

