export type VerificationStatus = 'PENDING_VERIFICATION' | 'VERIFIED' | 'REJECTED';

export interface Badge {
  id: string;
  name: string;
  description: string;
  icon: string;
  awardedAt: string;
  bonusPoints: number;
}

export interface User {
  id: string;
