                    <input type="text" placeholder={`Scan ${activeTab === 'PRACTICE' ? 'my active practice' : 'available bounties'} by keywords...`} className="w-full pl-12 md:pl-16 pr-6 md:pr-8 py-4 md:py-6 rounded-2xl md:rounded-[2rem] border-[3px] md:border-4 border-black shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] outline-none transition-all text-base md:text-xl font-bold bg-white" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
