      </div>

      {/* Manual Post Modal */}
      <Modal isOpen={showPostModal} onClose={() => setShowPostModal(false)} title="Manual Deployment">
          <form onSubmit={handleManualPost} className="space-y-6 max-h-[75vh] overflow-y-auto px-1 custom-scrollbar">
